import { AnimatePresence } from 'framer-motion';
import ErrorBoundary from './components/ErrorBoundary';
import { LazyLoad } from './components/ui/MotionComponents';

import { LockScreen } from './components/security/LockScreen';
import { SocialModal } from './components/social/SocialModal';
import { BackupRestoreModal } from './components/ui/BackupRestoreModal';
import { BottomNav } from './components/ui/BottomNav';
import { ProactiveBanner } from './components/ai/ProactiveMessage';
import { useProactiveCoach } from './hooks/useProactiveCoach';
import { C } from './data/constants';
import { useFitnessData } from './hooks/useFitnessData';

import { WelcomeWizard } from './components/onboarding/WelcomeWizard';
import { FreeWorkoutBuilder } from './components/workout/FreeWorkoutBuilder';
import { WeeklyPlanGenerator } from './components/workout/WeeklyPlanGenerator';
import { createViewConfigs } from './router/viewConfigs';

const css = `@import url('https://fonts.googleapis.com/css2?family=Bebas+Neue&family=DM+Mono:ital,wght@0,400;0,500;1,400&family=Outfit:wght@300;400;500;600;700&family=Inter:wght@400;500;600&display=swap'); *{box-sizing:border-box;margin:0;padding:0} html,body{background: #080b0f;color:#eceae4;font-family:'Outfit',sans-serif;-webkit-tap-highlight-color:transparent;min-height:100vh;letter-spacing:0.01em;} h1,h2,h3,.title{font-family:'Bebas Neue',cursive;letter-spacing:2px;} .mono{font-family:'DM Mono',monospace;letter-spacing:-0.02em;} .small{font-family:'Inter',sans-serif;font-size:0.75rem;color:#888;} input:focus{outline:none;border-color:#e8c84a !important;box-shadow: 0 0 12px rgba(232,200,74,0.15)} button:active{transform:scale(0.96)} input[type=number]::-webkit-inner-spin-button{-webkit-appearance:none} .glass { background: rgba(18, 25, 35, 0.6); backdrop-filter: blur(4px); border: 1px solid rgba(232, 200, 74, 0.15); border-radius: 16px; box-shadow: 0 4px 15px rgba(0,0,0,0.3); }`;

export default function App() {
  const {
    isUnlocked,
    isFirstTime,
    view,
    profile,
    history,
    currentPlan,
    workoutData,
    showClubModal,
    showFreeBuilder,
    showWeeklyPlan,
    pendingRestoreBackup,
    setView,
    setProfile,
    setShowClubModal,
    setShowFreeBuilder,
    setShowWeeklyPlan,
    setPendingRestoreBackup,
    handleStartWorkout,
    handleFinishWorkout,
    handleFeedbackSubmit,
    handleInstantSave,
    handleReset,
    handleUnlock,
    handleConfirmRestore,
  } = useFitnessData();

  useProactiveCoach(profile, history);

  if (!isUnlocked) {
    if (isFirstTime) {
      return (
        <WelcomeWizard
          onComplete={handleUnlock}
          profile={profile}
          setProfile={setProfile}
          onClearMocks={handleReset}
        />
      );
    }
    return <LockScreen onUnlock={handleUnlock} isFirstTime={false} />;
  }

  const viewConfigs = createViewConfigs({
    view,
    profile,
    setProfile,
    history,
    setView,
    handleStartWorkout,
    handleFinishWorkout,
    handleFeedbackSubmit,
    handleInstantSave,
    handleReset,
    handleUnlock,
    workoutData,
    currentPlan,
  });

  const currentView = viewConfigs[view];

  return (
    <div
      style={{
        paddingTop: 'calc(12px + env(safe-area-inset-top))',
        paddingBottom: 100,
        minHeight: '100vh',
        position: 'relative',
        background: C.bg,
        color: C.text,
      }}
    >
      <style>{css}</style>
      <ProactiveBanner />

      {pendingRestoreBackup && (
        <BackupRestoreModal
          createdTime={pendingRestoreBackup.createdTime}
          onConfirm={handleConfirmRestore}
          onDismiss={() => setPendingRestoreBackup(null)}
        />
      )}

      <ErrorBoundary>
        <LazyLoad skeleton="card" skeletonClassName="mt-20 mx-4">
          <AnimatePresence mode="wait">{currentView}</AnimatePresence>
        </LazyLoad>
      </ErrorBoundary>

      <BottomNav
        view={view}
        setView={setView}
        historyCount={history.length}
        onOpenClub={() => setShowClubModal(true)}
      />

      {showClubModal && <SocialModal onClose={() => setShowClubModal(false)} />}
      {showFreeBuilder && (
        <FreeWorkoutBuilder
          profile={profile}
          onClose={() => setShowFreeBuilder(false)}
          onStart={(plan) => {
            setShowFreeBuilder(false);
            handleStartWorkout(plan);
          }}
        />
      )}
      {showWeeklyPlan && (
        <WeeklyPlanGenerator
          profile={profile}
          setProfile={setProfile}
          onClose={() => setShowWeeklyPlan(false)}

        />
      )}
    </div>
  );
}

import { get, set } from 'idb-keyval';

const CACHE_TTL = 24 * 60 * 60 * 1000; // 24 horas

interface CacheEntry {
  workout: any;
  timestamp: number;
}

export const getCachedWorkout = async (contextHash: string) => {
  try {
    const cached = await get<CacheEntry>(`fittrack_ai_${contextHash}`);
    if (cached && Date.now() - cached.timestamp < CACHE_TTL) {
      return cached.workout;
    }
    return null;
  } catch (_e) {
    return null;
  }
};

export const cacheWorkout = async (contextHash: string, workout: any) => {
  try {
    await set(`fittrack_ai_${contextHash}`, {
      workout,
      timestamp: Date.now(),
    });
  } catch (e) {
    console.warn('IDB caching failed', e);
  }
};

import { useFrame } from '@react-three/fiber';
// @ts-nocheck
import { useRef, useState } from 'react';
import type * as THREE from 'three';

export const MuscleSphere = ({
  position,
  args,
  intensity = 0,
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  name: _name,
  isCylinder = false,
  isBox = false,
  fallbackColor = '#1e2832',
}: any) => {
  const meshRef = useRef<THREE.Mesh>(null);
  const [hovered, setHover] = useState(false);

  useFrame((state) => {
    if (meshRef.current && intensity > 0.5) {
      // Pulsação cyborg baseada na intensidade
      meshRef.current.scale.x = 1 + Math.sin(state.clock.elapsedTime * 3) * 0.02 * intensity;
      meshRef.current.scale.y = 1 + Math.sin(state.clock.elapsedTime * 3) * 0.02 * intensity;
    }
  });

  const getColor = () => {
    if (hovered) return '#ffffff';
    if (intensity <= 0) return fallbackColor;
    // Cyberpunk colors: Low fatigue = yellow/greenish. High fatigue = red/neon pink
    if (intensity < 0.3) return '#e8c84a'; // Amarelo
    if (intensity < 0.7) return '#f48c06'; // Laranja
    return '#dc2f02'; // Vermelho intenso
  };

  return (
    <mesh
      ref={meshRef}
      position={position}
      onPointerOver={(e) => {
        e.stopPropagation();
        setHover(true);
      }}
      onPointerOut={() => setHover(false)}
    >
      {isBox ? (
        <boxGeometry args={args} />
      ) : isCylinder ? (
        <cylinderGeometry args={args} />
      ) : (
        <sphereGeometry args={args} />
      )}

      <meshStandardMaterial
        color={getColor()}
        roughness={0.2}
        metalness={0.8}
        emissive={getColor()}
        emissiveIntensity={intensity > 0 ? intensity * 0.8 : 0}
      />
    </mesh>
  );
};

import { ContactShadows, Environment, OrbitControls } from '@react-three/drei';
import { Canvas, useFrame } from '@react-three/fiber';
import type React from 'react';
import { Suspense, useRef } from 'react';
import type * as THREE from 'three';
import { C } from '../../data/constants';
import { MuscleSphere } from './MuscleSphere';

const PoseRig = ({
  fatigueStats,
  landmarksRef,
}: { fatigueStats: Record<string, number>; landmarksRef?: React.MutableRefObject<any[]> }) => {
  const leftArmRef = useRef<THREE.Group>(null);
  const rightArmRef = useRef<THREE.Group>(null);

  useFrame(() => {
    if (landmarksRef && landmarksRef.current && landmarksRef.current.length > 0) {
      const landmarks = landmarksRef.current;
      // Mapping MediaPipe to 3D Rotations (simplified)
      // Left Shoulder (11), Left Elbow (13), Left Wrist (15)
      // Right Shoulder (12), Right Elbow (14), Right Wrist (16)
      try {
        if (leftArmRef.current) {
          leftArmRef.current.position.y = 4.8 - landmarks[11].y * 2;
          leftArmRef.current.position.x = -1.2 + landmarks[11].x * 2;
        }
        if (rightArmRef.current) {
          rightArmRef.current.position.y = 4.8 - landmarks[12].y * 2;
          rightArmRef.current.position.x = 1.2 - landmarks[12].x * 2;
        }
      } catch (_e) { /* Silently handle missing landmark data */ }
    }
  });

  return (
    <group position={[0, -2, 0]}>
      {/* CABEÇA */}
      <MuscleSphere
        name="Head"
        position={[0, 6, 0]}
        args={[0.5, 32, 32]}
        intensity={0}
        fallbackColor="#333"
      />

      {/* PESCOÇO */}
      <MuscleSphere
        name="Neck"
        position={[0, 5.2, 0]}
        args={[0.2, 0.4, 32]}
        isCylinder
        intensity={0}
        fallbackColor="#333"
      />

      {/* OMBROS E BRAÇOS DENTRO DE GRUPOS ANIMADOS */}
      <group ref={leftArmRef} position={[-1.2, 4.8, 0]}>
        <MuscleSphere
          name="LeftShoulder"
          position={[0, 0, 0]}
          args={[0.6, 32, 32]}
          intensity={fatigueStats['Ombros'] || 0}
        />
        <MuscleSphere
          name="LeftBicep"
          position={[-0.2, -1.3, 0.2]}
          args={[0.3, 1.2, 32]}
          isCylinder
          intensity={fatigueStats['Bíceps'] || 0}
        />
        <MuscleSphere
          name="LeftForearm"
          position={[-0.2, -3.0, 0]}
          args={[0.25, 1.5, 32]}
          isCylinder
          intensity={0}
          fallbackColor="#333"
        />
      </group>

      <group ref={rightArmRef} position={[1.2, 4.8, 0]}>
        <MuscleSphere
          name="RightShoulder"
          position={[0, 0, 0]}
          args={[0.6, 32, 32]}
          intensity={fatigueStats['Ombros'] || 0}
        />
        <MuscleSphere
          name="RightBicep"
          position={[0.2, -1.3, 0.2]}
          args={[0.3, 1.2, 32]}
          isCylinder
          intensity={fatigueStats['Bíceps'] || 0}
        />
        <MuscleSphere
          name="RightForearm"
          position={[0.2, -3.0, 0]}
          args={[0.25, 1.5, 32]}
          isCylinder
          intensity={0}
          fallbackColor="#333"
        />
      </group>

      {/* PEITO E COSTAS (Tronco Upper) */}
      <MuscleSphere
        name="Peito"
        position={[0, 4.2, 0.3]}
        args={[1.2, 1.2, 0.4]}
        isBox
        intensity={fatigueStats['Peito'] || 0}
      />
      <MuscleSphere
        name="Costas"
        position={[0, 4.2, -0.3]}
        args={[1.2, 1.2, 0.4]}
        isBox
        intensity={fatigueStats['Costas'] || 0}
      />

      {/* CORE / ABD */}
      <MuscleSphere
        name="Core"
        position={[0, 2.7, 0]}
        args={[0.9, 1.4, 0.6]}
        isBox
        intensity={fatigueStats['Core'] || 0}
      />

      {/* PERNAS - COXAS E PANTURRILHA */}
      <MuscleSphere
        name="LeftLeg"
        position={[-0.5, 1, 0]}
        args={[0.4, 2, 32]}
        isCylinder
        intensity={fatigueStats['Pernas'] || 0}
      />
      <MuscleSphere
        name="RightLeg"
        position={[0.5, 1, 0]}
        args={[0.4, 2, 32]}
        isCylinder
        intensity={fatigueStats['Pernas'] || 0}
      />

      <MuscleSphere
        name="LeftCalf"
        position={[-0.5, -1.2, 0]}
        args={[0.3, 2, 32]}
        isCylinder
        intensity={fatigueStats['Pernas'] || 0}
      />
      <MuscleSphere
        name="RightCalf"
        position={[0.5, -1.2, 0]}
        args={[0.3, 2, 32]}
        isCylinder
        intensity={fatigueStats['Pernas'] || 0}
      />
    </group>
  );
};

export const MuscleViewer = ({
  fatigueStats,
  landmarksRef,
}: { fatigueStats: Record<string, number>; landmarksRef?: React.MutableRefObject<any[]> }) => {
  // fatigueStats: Record do nome do músculo para intensity (0.0 a 1.0)

  // Core Cyberpunk android geometry mapped to Fittrack muscles
  return (
    <div
      style={{
        height: 350,
        width: '100%',
        background: 'linear-gradient(180deg, #05070a 0%, #0e1318 100%)',
        borderRadius: 12,
        overflow: 'hidden',
        border: `1px solid ${C.border}`,
        position: 'relative',
      }}
    >
      <div style={{ position: 'absolute', top: 10, left: 10, pointerEvents: 'none', zIndex: 10 }}>
        <p style={{ fontFamily: "'Bebas Neue'", color: C.accent, fontSize: 16 }}>
          MODELO BIOMÉTRICO
        </p>
        <p style={{ color: C.muted, fontSize: 10 }}>Rodar Rato/Touch 360º</p>
      </div>
      <Suspense
        fallback={
          <div style={{ color: 'white', textAlign: 'center', marginTop: 100 }}>
            Carregando 3D...
          </div>
        }
      >
        <Canvas camera={{ position: [0, 0, 10], fov: 45 }}>
          <ambientLight intensity={0.4} />
          <spotLight position={[10, 10, 10]} angle={0.15} penumbra={1} intensity={1} castShadow />
          <pointLight position={[-10, -10, -10]} intensity={0.5} />

          <PoseRig fatigueStats={fatigueStats} landmarksRef={landmarksRef} />

          <ContactShadows position={[0, -4, 0]} opacity={0.6} scale={10} blur={2} far={4} />
          <Environment preset="city" />
          <OrbitControls
            maxPolarAngle={Math.PI / 1.5}
            minPolarAngle={Math.PI / 4}
            enableZoom={true}
            autoRotate
            autoRotateSpeed={2}
          />
        </Canvas>
      </Suspense>
    </div>
  );
};

