import { motion } from 'framer-motion';
import { C } from '../../data/constants';
import type { Challenge } from '../../services/predictiveChallenges';
import { DeadHangWidget } from './DeadHangWidget';

export const ActiveChallenges = ({
  challenges,
  onChallengeComplete,
}: { challenges: Challenge[]; onChallengeComplete?: (id: string) => void }) => {
  const activeCs = challenges.filter((c) => c.status === 'active');

  if (activeCs.length === 0) return null;

  const getTimeLeft = (isoString: string) => {
    const hrs = Math.max(0, (new Date(isoString).getTime() - new Date().getTime()) / 3600000);
    if (hrs > 24) return `${Math.floor(hrs / 24)} dias`;
    return `${Math.floor(hrs)} horas`;
  };

  return (
    <div style={{ marginBottom: 20 }}>
      <p
        style={{
          fontFamily: "'Bebas Neue'",
          fontSize: 16,
          letterSpacing: 2,
          color: C.muted,
          marginBottom: 10,
        }}
      >
        DESAFIOS DA IA PREDITIVA
      </p>
      <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
        {activeCs.map((c, i) => (
          <motion.div
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ delay: i * 0.1 }}
            key={c.id}
            className="glass"
            style={{ padding: 14, borderLeft: `3px solid ${C.accent}` }}
          >
            <div
              style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}
            >
              <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                <span style={{ fontSize: 20 }}>
                  {c.type === 'strength' ? '🏋️' : c.type === 'trending' ? '🔥' : '⏱️'}
                </span>
                <div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                    <h4 style={{ fontSize: 15, color: C.text, margin: 0 }}>{c.title}</h4>
                    {c.type === 'trending' && (
                      <span
                        style={{
                          background: '#ff4d4d22',
                          color: '#ff4d4d',
                          fontSize: 9,
                          fontWeight: 'bold',
                          padding: '2px 6px',
                          borderRadius: 4,
                          fontFamily: "'DM Mono'",
                        }}
                      >
                        TRENDING 2026
                      </span>
                    )}
                  </div>
                  <p style={{ fontSize: 12, color: C.muted, marginTop: 4 }}>{c.description}</p>
                </div>
              </div>
              <div
                style={{
                  background: C.accentLow,
                  color: C.accent,
                  padding: '4px 8px',
                  borderRadius: 6,
                  fontSize: 11,
                  fontWeight: 'bold',
                }}
              >
                +{c.xpReward} XP
              </div>
            </div>
            <div
              style={{
                marginTop: 12,
                display: 'flex',
                justifyContent: 'space-between',
                fontSize: 11,
                color: C.muted,
              }}
            >
              <span>
                Expira em: <strong style={{ color: C.red }}>{getTimeLeft(c.deadline)}</strong>
              </span>
            </div>

            {c.targetExercise === 'Dead Hang' && (
              <DeadHangWidget
                targetSeconds={c.targetValue}
                onSuccess={() => onChallengeComplete && onChallengeComplete(c.id)}
              />
            )}
          </motion.div>
        ))}
      </div>
    </div>
  );
};

import { motion } from 'framer-motion';
// @ts-nocheck
import { useEffect, useState } from 'react';
import Confetti from 'react-confetti';
import { C } from '../../data/constants';

interface DeadHangWidgetProps {
  targetSeconds: number;
  onSuccess: () => void;
}

export const DeadHangWidget = ({ targetSeconds, onSuccess }: DeadHangWidgetProps) => {
  const [isActive, setIsActive] = useState(false);
  const [seconds, setSeconds] = useState(0);
  const [showConfetti, setShowConfetti] = useState(false);
  const [completed, setCompleted] = useState(false);

  useEffect(() => {
    let interval: any = null;
    if (isActive && !completed) {
      interval = setInterval(() => {
        setSeconds((s) => {
          const next = s + 1;
          if (next >= targetSeconds) {
            setIsActive(false);
            setCompleted(true);
            setShowConfetti(true);
            onSuccess();
            setTimeout(() => setShowConfetti(false), 5000);
          }
          return next;
        });
      }, 1000);
    } else if (!isActive && seconds !== 0 && !completed) {
      clearInterval(interval);
    }
    return () => clearInterval(interval);
  }, [isActive, seconds, completed, targetSeconds, onSuccess]);

  const progress = Math.min((seconds / targetSeconds) * 100, 100);

  return (
    <div
      style={{
        background: C.card,
        border: `1px solid ${C.accent}`,
        borderRadius: 12,
        padding: 16,
        marginTop: 12,
        position: 'relative',
        overflow: 'hidden',
      }}
    >
      {showConfetti && (
        <Confetti
          width={300}
          height={150}
          recycle={false}
          style={{ position: 'absolute', inset: 0 }}
        />
      )}

      <div
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          marginBottom: 12,
        }}
      >
        <span style={{ fontSize: 13, color: C.text, fontWeight: 'bold' }}>
          🕒 Temporizador: Dead Hang
        </span>
        <span
          style={{ fontFamily: "'DM Mono'", fontSize: 16, color: completed ? C.green : C.accent }}
        >
          {seconds}s / {targetSeconds}s
        </span>
      </div>

      <div
        style={{
          width: '100%',
          height: 8,
          background: C.bg,
          borderRadius: 4,
          overflow: 'hidden',
          marginBottom: 16,
        }}
      >
        <motion.div
          initial={{ width: 0 }}
          animate={{ width: `${progress}%` }}
          style={{ height: '100%', background: completed ? C.green : C.accent }}
        />
      </div>

      {!completed ? (
        <div style={{ display: 'flex', gap: 10 }}>
          <button
            onClick={() => setIsActive(!isActive)}
            style={{
              flex: 1,
              background: isActive ? C.red : C.accent,
              color: isActive ? '#fff' : '#000',
              border: 'none',
              borderRadius: 8,
              padding: 10,
              fontWeight: 'bold',
              cursor: 'pointer',
            }}
          >
            {isActive ? 'PARAR' : seconds > 0 ? 'RETOMAR' : 'INICIAR'}
          </button>
          {seconds > 0 && !isActive && (
            <button
              onClick={() => setSeconds(0)}
              style={{
                background: C.surface,
                color: C.text,
                border: `1px solid ${C.border}`,
                borderRadius: 8,
                padding: 10,
                cursor: 'pointer',
              }}
            >
              RESET
            </button>
          )}
        </div>
      ) : (
        <div style={{ textAlign: 'center', color: C.green, fontWeight: 'bold', fontSize: 14 }}>
          🎉 DESAFIO CONCLUÍDO! XP ATRIBUÍDO!
        </div>
      )}
    </div>
  );
};

import { motion } from 'framer-motion';
import { Activity, Brain, Droplets, Scale } from 'lucide-react';
