interface MetricBoxProps {
  label: string;
  value: number | null;
  unit: string;
  icon: React.ComponentType<{ size?: number; color?: string }>;
  trend?: 'up' | 'down' | 'neutral';
  precision?: number;
}

const MetricBox: React.FC<MetricBoxProps> = ({
  label,
  value,
  unit,
  icon: Icon,
  trend = 'neutral',
  precision = 1,
}) => {
  const isPositive = trend === 'up';
  const isNegative = trend === 'down';
  const color = isPositive ? '#00ff88' : isNegative ? '#ff4444' : '#00d4ff';

  return (
    <div
      style={{
        background: 'rgba(0,0,0,0.4)',
        border: '1px solid rgba(255,255,255,0.05)',
        borderRadius: '12px',
        padding: '16px',
        position: 'relative',
        overflow: 'hidden',
      }}
    >
      <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '8px' }}>
        <Icon size={16} color={'rgba(255,255,255,0.5)'} />
        <span
          style={{
            fontSize: '10px',
            color: 'rgba(255,255,255,0.5)',
            fontWeight: 'bold',
            textTransform: 'uppercase',
            letterSpacing: '2px',
          }}
        >
          {label}
        </span>
      </div>
      <div style={{ display: 'flex', alignItems: 'baseline', gap: '4px' }}>
        <span
          style={{
            fontSize: '1.5rem',
            fontWeight: 900,
            fontFamily: 'monospace',
            color: '#fff',
            letterSpacing: '-1px',
          }}
        >
          {value !== null ? value.toFixed(precision) : '--'}
        </span>
        <span style={{ fontSize: '0.75rem', color: 'rgba(255,255,255,0.5)', fontWeight: 'bold' }}>
          {unit}
        </span>
      </div>
      {trend !== 'neutral' && value !== null && (
        <div
          style={{
            position: 'absolute',
            top: '16px',
            right: '16px',
            color,
            fontWeight: 'bold',
            textShadow: `0 0 10px ${color}80`,
          }}
        >
          {isPositive ? '↑' : '↓'}
        </div>
      )}
    </div>
  );
};

