            title="Ovulatória (14-15)"
          />
          <div style={{ flex: 13, background: '#a78bfa', opacity: 0.6 }} title="Lútea (16-28)" />
        </div>
        <div
          style={{
            display: 'flex',
            justifyContent: 'space-between',
            marginTop: 2,
          }}
        >
          {['Mens.', 'Folic.', 'Ov.', 'Lútea'].map((l, i) => (
            <span key={i} style={{ fontSize: 8, color: '#3a4550' }}>
              {l}
            </span>
          ))}
        </div>
      </div>

      {/* Dica da fase */}
      <motion.div
        key={phase}
        initial={{ opacity: 0, y: 4 }}
        animate={{ opacity: 1, y: 0 }}
        style={{
          background: `${config.color}11`,
          border: `1px solid ${config.color}33`,
          borderRadius: 8,
          padding: '8px 12px',
        }}
      >
        <p style={{ fontSize: 12, color: '#eceae4', lineHeight: 1.5 }}>💡 {config.tip}</p>
      </motion.div>
    </GlassCard>
  );
}

import { format, subDays } from 'date-fns';
import { motion } from 'framer-motion';
import { Calendar, CalendarPlus, CheckCircle, ChevronRight, Dumbbell, Zap } from 'lucide-react';
import type React from 'react';
import { useMemo } from 'react';

interface DailyBriefingProps {
  history: any[];
  plannedWorkoutToday?: {
    title: string;
    period: 'Manhã' | 'Tarde' | 'Noite';
    slot: 'morning' | 'afternoon';
  } | null;
  onStartPlannedWorkout: () => void;
  onStartFreeWorkout: () => void;
  onNavigateToPlanner: () => void;
}

export const DailyBriefing: React.FC<DailyBriefingProps> = ({
  history,
  plannedWorkoutToday,
  onStartPlannedWorkout,
  onStartFreeWorkout,
  onNavigateToPlanner,
}) => {
  // Lógica para encontrar o treino de ontem corrigindo o bug de timezone
  const yesterdaysWorkout = useMemo(() => {
    const yesterdayString = format(subDays(new Date(), 1), 'yyyy-MM-dd');
    return history.find(
      (w) => w.date === yesterdayString || w.startTime?.startsWith(yesterdayString),
    );
  }, [history]);

  return (
    <motion.div
      initial={{ opacity: 0, y: -20 }}
