      </div>

      {/* BLOCO 2: A Missão de Hoje */}
      <div
        style={{
          borderRadius: '16px',
          padding: '20px',
          border: `1px solid ${plannedWorkoutToday ? 'rgba(204, 255, 0, 0.3)' : 'rgba(255, 255, 255, 0.1)'}`,
