          <span style={{ position: 'relative', display: 'flex', width: '12px', height: '12px' }}>
            {plannedWorkoutToday && (
              <span
                style={{
                  animation: 'ping 1.5s cubic-bezier(0, 0, 0.2, 1) infinite',
                  position: 'absolute',
                  width: '100%',
                  height: '100%',
                  borderRadius: '50%',
                  background: '#ccff00',
                  opacity: 0.75,
                }}
              />
            )}
            <span
              style={{
                position: 'relative',
                display: 'inline-flex',
                borderRadius: '50%',
