                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  gap: '8px',
                }}
              >
                <CalendarPlus size={16} /> Montar Semana
              </button>
            </div>
          </>
        )}
      </div>
    </motion.div>
  );
