import { motion } from 'framer-motion';
import { C } from '../../data/constants';

interface ReadinessGaugeProps {
  acwr: number;
  label?: string;
}

export function ReadinessGauge({ acwr, label = 'ACWR (Prontidão)' }: ReadinessGaugeProps) {
  // ACWR Sweet Spot: 0.8 - 1.3
  // Perigo (Risco Alto): > 1.5
  // Destreinamento: < 0.8

  // Limites visuais do medidor (0.5 a 2.0)
  const min = 0.5;
  const max = 2.0;

  // Clamping
  const clamped = Math.max(min, Math.min(max, acwr));

  // Percentagem (0 a 1)
  const percent = (clamped - min) / (max - min);

  // Cores dinâmicas Dark Neon
  let strokeColor = C.green; // Sweet spot
  let statusText = 'ZONA SEGURA';
  let statusColor = C.green;

  if (acwr > 1.5) {
    strokeColor = C.red;
    statusText = 'SOBRECARGA';
    statusColor = C.red;
  } else if (acwr > 1.3) {
    strokeColor = '#f59e0b';
    statusText = 'ALERTA / FADIGA';
    statusColor = '#f59e0b';
  } else if (acwr < 0.8) {
    strokeColor = '#00d4ff'; // Blue Neon for undertraining
    statusText = 'DESTREINAMENTO';
    statusColor = '#00d4ff';
  }

  // Geometria do SVG (Semi-círculo)
  const radius = 60;
  const circumference = Math.PI * radius; // Apenas metade do perímetro
  const strokeDashoffset = circumference - percent * circumference;

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        position: 'relative',
      }}
    >
      <svg width="200" height="120" viewBox="0 0 200 120">
        <defs>
          <filter id="glow" x="-20%" y="-20%" width="140%" height="140%">
            <feGaussianBlur stdDeviation="6" result="blur" />
            <feComposite in="SourceGraphic" in2="blur" operator="over" />
          </filter>
        </defs>

        {/* Arco de fundo (Track) */}
        <path
          d="M 20 100 A 80 80 0 0 1 180 100"
          fill="none"
          stroke="rgba(255, 255, 255, 0.05)"
          strokeWidth="16"
          strokeLinecap="round"
        />

        {/* Arco animado (Value) */}
        <motion.path
          d="M 20 100 A 80 80 0 0 1 180 100"
          fill="none"
          stroke={strokeColor}
          strokeWidth="16"
          strokeLinecap="round"
          strokeDasharray={circumference}
          initial={{ strokeDashoffset: circumference }}
          animate={{ strokeDashoffset }}
          transition={{ duration: 1.5, ease: 'easeOut', delay: 0.2 }}
          filter="url(#glow)"
        />
      </svg>

      {/* Rótulo de Valor */}
      <div
        style={{
          position: 'absolute',
          top: '70px',
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
        }}
      >
        <span
          style={{
            fontFamily: "'Bebas Neue', sans-serif",
            fontSize: 32,
            letterSpacing: 2,
            color: '#fff',
            lineHeight: 1,
          }}
        >
          {acwr.toFixed(2)}
        </span>
        <span
          style={{
            fontSize: 10,
            color: 'rgba(255, 255, 255, 0.5)',
            textTransform: 'uppercase',
            letterSpacing: 1,
            marginTop: 4,
          }}
        >
          {label}
        </span>
      </div>

      {/* Rótulo de Status */}
      <div
        style={{
          marginTop: 8,
          padding: '4px 12px',
          borderRadius: 12,
          background: `rgba(${statusColor === C.red ? '239,68,68' : statusColor === C.green ? '56,176,0' : statusColor === '#f59e0b' ? '249,115,22' : '0,212,255'}, 0.15)`,
          border: `1px solid ${statusColor}`,
          color: statusColor,
          fontSize: 11,
          fontWeight: 800,
          letterSpacing: 1,
          fontFamily: "'Bebas Neue', sans-serif",
        }}
      >
        {statusText}
      </div>
    </div>
  );
}

import { motion } from 'framer-motion';
import { useState } from 'react';

export const REWARDS = {
  muscleGroups: ['Peito', 'Costas', 'Pernas', 'Ombros', 'Braços', 'Core'],
  bonuses: ['+15% Recovery', 'Rival AI -10%', 'XP Boost x2', 'Desconto 20%'],
  durations: ['próximas 4h', 'próximo treino', '24h', 'permanente (Premium)'],
};

export const spinRoulette = () => {
  const now = Date.now();
  const lastSpin = localStorage.getItem('last_roulette_spin');
  if (lastSpin && now - Number.parseInt(lastSpin) < 24 * 60 * 60 * 1000) {
    // Para simplificar testes, iremos apenas retornar msg local,
    // mas pode ser modificado para libertar o botão localmente.
    return { error: 'Apenas 1 spin por dia. Volta amanhã!' };
  }

  const pityCounter = Number.parseInt(localStorage.getItem('roulette_pity') || '0');

  const muscle = REWARDS.muscleGroups[Math.floor(Math.random() * REWARDS.muscleGroups.length)];
  let bonus = REWARDS.bonuses[Math.floor(Math.random() * REWARDS.bonuses.length)];
  let duration = REWARDS.durations[Math.floor(Math.random() * REWARDS.durations.length)];

  if (pityCounter >= 4) {
    bonus = '+15% Recovery';
    duration = 'permanente (Premium)';
    localStorage.setItem('roulette_pity', '0');
  } else {
    if (bonus !== '+15% Recovery') {
      localStorage.setItem('roulette_pity', (pityCounter + 1).toString());
    } else {
      localStorage.setItem('roulette_pity', '0');
    }
  }

  const reward = { muscle, bonus, duration, timestamp: now };
  localStorage.setItem('last_roulette_spin', now.toString());
  localStorage.setItem('current_roulette_reward', JSON.stringify(reward));
  return { success: true, reward };
};

export const RecoveryRoulette = () => {
  const [spinning, setSpinning] = useState(false);
  const [reward, setReward] = useState<any>(null);
  const [error, setError] = useState('');

  const handleSpin = async () => {
    setSpinning(true);
    setError('');

    await new Promise((resolve) => setTimeout(resolve, 1500)); // Delay da animação

    const result = spinRoulette();
    if (result.error) {
      setError(result.error);
    } else {
      setReward(result.reward);
    }
    setSpinning(false);
  };

  return (
    <div
      style={{
        background: '#1a1f25',
        borderRadius: 12,
        padding: 14,
        border: '1px solid rgba(232, 200, 74, 0.2)',
        marginBottom: 20,
      }}
    >
      <h3 style={{ color: '#e8c84a', fontFamily: "'Bebas Neue'", fontSize: 20, marginBottom: 8 }}>
        🎰 RECOVERY ROULETTE
      </h3>

      <div
        style={{
          position: 'relative',
          height: 80,
          background: '#080b0f',
          borderRadius: 8,
          overflow: 'hidden',
          marginBottom: 16,
        }}
      >
        <motion.div
          style={{
            position: 'absolute',
            inset: 0,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
          }}
          animate={spinning ? { x: [0, -100, 100, -50, 50, 0] } : {}}
          transition={{ duration: 0.5, repeat: spinning ? 3 : 0 }}
        >
          {reward ? (
            <div style={{ textAlign: 'center' }}>
              <p style={{ fontSize: 20, fontWeight: 'bold' }}>{reward.bonus}</p>
              <p style={{ fontSize: 11, color: '#999' }}>
                {reward.muscle} • {reward.duration}
              </p>
            </div>
          ) : (
            <p style={{ fontSize: 32, opacity: 0.3 }}>🎲🎲🎲</p>
          )}
        </motion.div>
      </div>

      <button
        onClick={handleSpin}
        disabled={spinning || !!reward}
        style={{
          width: '100%',
          padding: '12px',
          borderRadius: 8,
          border: 'none',
          background: spinning || reward ? '#555' : 'linear-gradient(to right, #e8c84a, #d4b03a)',
          color: '#080b0f',
          fontWeight: 'bold',
          cursor: spinning || reward ? 'not-allowed' : 'pointer',
        }}
      >
        {spinning ? 'A RODAR...' : reward ? 'BÓNUS DIÁRIO RECLAMADO' : 'LANÇAR (1X/DIA)'}
      </button>

      {error && <p style={{ color: '#ef4444', fontSize: 11, marginTop: 8 }}>{error}</p>}
    </div>
  );
};

