import { AnimatePresence, motion } from 'framer-motion';
import type React from 'react';
import { useEffect, useState } from 'react';
import { type UnifiedHealthMetrics, healthBridge } from '../../services/healthBridge';
import { useHealthStore } from '../../stores/useHealthStore';
import { GlassCard } from '../ui/GlassCard';

export const HealthSyncSettings: React.FC = () => {
  const [isConnected, setIsConnected] = useState(false);
  const [lastSync, setLastSync] = useState<UnifiedHealthMetrics | null>(null);
  const [loading, setLoading] = useState(false);

  const { syncHealthData } = useHealthStore();

  useEffect(() => {
    const token = localStorage.getItem('google_fit_token');
    setIsConnected(!!token);
  }, []);

  const handleConnectGoogle = async () => {
    setLoading(true);
    const ok = await healthBridge.connectGoogleFit();
    if (ok) {
      setIsConnected(true);
      await handleSync();
    }
    setLoading(false);
  };

  const handleSync = async () => {
    setLoading(true);
    await syncHealthData([], true); // Force Refresh (needs history, pass empty or fetch it)
    const storeData = useHealthStore.getState().healthKitData;
    if (storeData) {
      setLastSync(storeData);
    }
    setLoading(false);
  };

  const handleDisconnect = () => {
    healthBridge.disconnect();
    setIsConnected(false);
    setLastSync(null);
  };

  return (
    <GlassCard glow style={{ padding: 20, marginBottom: 20 }}>
      <h2 style={{ fontFamily: "'Bebas Neue'", fontSize: 24, color: '#e8c84a', marginBottom: 12 }}>
        🔄 Saúde & Conectividade
      </h2>
      <p style={{ fontSize: 14, color: '#eceae4', marginBottom: 16 }}>
        Sincroniza os teus dados de actividade e sono para um Readiness Score mais preciso.
      </p>

      {!isConnected ? (
        <button
          onClick={handleConnectGoogle}
          disabled={loading}
          style={{
            background: 'linear-gradient(135deg, #e8c84a, #d4b83a)',
            color: '#000',
            border: 'none',
            padding: '12px 24px',
            borderRadius: 8,
            fontWeight: 'bold',
            cursor: 'pointer',
            fontFamily: "'Bebas Neue'",
            fontSize: 16,
          }}
        >
          {loading ? 'A ligar...' : '🔗 Ligar ao Google Fit'}
        </button>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
          <div style={{ display: 'flex', gap: 12 }}>
            <button
              onClick={handleSync}
              disabled={loading}
              style={{
                background: 'rgba(255,255,255,0.1)',
                color: '#eceae4',
                border: '1px solid #eceae4',
                padding: '8px 16px',
                borderRadius: 8,
                cursor: 'pointer',
                fontFamily: "'Bebas Neue'",
                fontSize: 16,
              }}
            >
              {loading ? 'A sincronizar...' : '📊 Sincronizar Agora'}
            </button>
            <button
              onClick={handleDisconnect}
              style={{
                background: 'transparent',
                color: '#ff3366',
                border: '1px solid #ff3366',
                padding: '8px 16px',
                borderRadius: 8,
                cursor: 'pointer',
                fontFamily: "'Bebas Neue'",
                fontSize: 16,
              }}
            >
              Desligar
            </button>
          </div>

          <AnimatePresence>
            {lastSync && (
              <motion.div
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                style={{
                  display: 'grid',
                  gridTemplateColumns: '1fr 1fr',
                  gap: 8,
                  background: '#0f1419',
                  padding: 12,
                  borderRadius: 8,
                }}
              >
                <div style={{ fontSize: 12, color: '#55626e' }}>⚖️ Peso</div>
                <div
                  style={{
                    fontSize: 14,
                    color: '#eceae4',
                    textAlign: 'right',
                    fontFamily: 'monospace',
                  }}
                >
                  {lastSync.weight?.toFixed(1) || 'N/A'} kg
                </div>

                {lastSync.sleepHours && (
                  <>
                    <div style={{ fontSize: 12, color: '#55626e' }}>😴 Sono</div>
                    <div
                      style={{
                        fontSize: 14,
                        color: '#eceae4',
                        textAlign: 'right',
                        fontFamily: 'monospace',
                      }}
                    >
                      {lastSync.sleepHours.toFixed(1)}h
                    </div>
                  </>
                )}

                <div style={{ fontSize: 12, color: '#55626e' }}>📅 Último Sync</div>
                <div style={{ fontSize: 12, color: '#55626e', textAlign: 'right' }}>
                  {new Date(lastSync.lastSync).toLocaleString()}
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      )}
    </GlassCard>
  );
};

import { useState } from 'react';
import { C } from '../../data/constants';
import { useSocialStore } from '../../stores/useSocialStore';

export const ClubTab = () => {
  const { myClub, createClub, joinClub, leaveClub, submitXP, clubLoading, clubError } =
    useSocialStore();
  const [clubName, setClubName] = useState('');
  const [inviteCode, setInviteCode] = useState('');
  const [joinError, setJoinError] = useState<string | null>(null);

  const handleCreate = async () => {
    if (!clubName) return;
    await createClub(clubName);
    setClubName('');
  };

  const handleJoin = async (code?: string) => {
    const target = (code ?? inviteCode).toUpperCase();
    if (!target) return;
    setJoinError(null);
    try {
      await joinClub(target);
    } catch (err) {
      setJoinError(err instanceof Error ? err.message : 'Falha ao entrar no clube.');
    }
  };

  return (
    <div>
      {!myClub ? (
        <div>
          <div style={{ marginBottom: 20 }}>
            <input
              type="text"
              value={clubName}
              onChange={(e) => setClubName(e.target.value)}
              placeholder="Nome do Novo Clube"
              style={{
                width: '100%',
                background: C.dim,
                border: `1px solid ${C.border}`,
                borderRadius: 8,
                padding: 12,
                color: '#fff',
                marginBottom: 8,
              }}
            />
            <button
              onClick={handleCreate}
              disabled={clubLoading}
              style={{
                width: '100%',
                padding: 14,
                background: C.accent,
                color: C.bg,
                fontWeight: 'bold',
                borderRadius: 8,
                cursor: 'pointer',
                border: 'none',
              }}
            >
              {clubLoading ? 'A CRIAR...' : 'CRIAR CLUBE'}
            </button>
          </div>

          <div style={{ position: 'relative' }}>
            <input
              type="text"
              value={inviteCode}
              onChange={(e) => setInviteCode(e.target.value)}
              placeholder="Código de convite (6 caracteres)"
              style={{
                width: '100%',
                background: C.dim,
                border: `1px solid ${C.border}`,
                borderRadius: 8,
                padding: 12,
                color: '#fff',
              }}
            />
            <button
              onClick={() => handleJoin()}
              disabled={clubLoading}
              style={{
                position: 'absolute',
                right: 6,
                top: 6,
                padding: '6px 12px',
                background: `${C.accent}33`,
                color: C.accent,
                border: 'none',
                borderRadius: 4,
                cursor: 'pointer',
                fontWeight: 'bold',
              }}
            >
              ENTRAR
            </button>
          </div>
          {(joinError || clubError) && (
            <p style={{ fontSize: 12, color: C.red, marginTop: 8 }}>{joinError ?? clubError}</p>
          )}
        </div>
      ) : (
        <>
          <div
            style={{
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center',
              marginBottom: 16,
            }}
          >
            <div>
              <p style={{ fontFamily: "'Bebas Neue'", fontSize: 20, color: '#fff', margin: 0 }}>
                {myClub.name}
              </p>
              <p style={{ fontFamily: "'DM Mono'", fontSize: 11, color: C.muted, margin: 0 }}>
                Código: {myClub.code}
              </p>
            </div>
            <p style={{ fontSize: 13, color: '#ccc' }}>{myClub.members.length}/10 membros</p>
          </div>

          <div style={{ display: 'flex', flexDirection: 'column', gap: 8, marginBottom: 20 }}>
            {myClub.members
              .slice()
