  </div>
);

// ============================================================
// 2. LAZY LOAD WRAPPER — Suspense com skeleton
// ============================================================

interface LazyLoadProps {
  children: React.ReactNode;
  fallback?: React.ReactNode;
  skeleton?: 'card' | 'text' | 'bodymap' | 'custom';
  skeletonClassName?: string;
}

export const LazyLoad: React.FC<LazyLoadProps> = ({
  children,
  fallback,
  skeleton = 'card',
  skeletonClassName = '',
}) => {
  const skeletonMap = {
    card: <SkeletonCard className={skeletonClassName} />,
    text: <SkeletonText className={skeletonClassName} />,
    bodymap: <SkeletonBodyMap />,
    custom: null,
  };

  return (
    <Suspense fallback={fallback || skeletonMap[skeleton] || <SkeletonCard />}>{children}</Suspense>
  );
};

// ============================================================
// 3. ENTRANCE ANIMATIONS — Fade, Slide, Scale
// ============================================================

const defaultEasing = [0.4, 0, 0.2, 1]; // ease-out

interface AnimatedProps {
  children: React.ReactNode;
  delay?: number;
  duration?: number;
  className?: string;
}

export const FadeIn: React.FC<AnimatedProps> = ({
  children,
  delay = 0,
  duration = 0.4,
  className = '',
}) => (
  <motion.div
    initial={{ opacity: 0 }}
    animate={{ opacity: 1 }}
    transition={{ duration, delay, ease: defaultEasing }}
    className={className}
  >
    {children}
  </motion.div>
);

export const SlideUp: React.FC<AnimatedProps> = ({
  children,
  delay = 0,
  duration = 0.4,
  className = '',
}) => (
  <motion.div
    initial={{ opacity: 0, y: 20 }}
    animate={{ opacity: 1, y: 0 }}
    transition={{ duration, delay, ease: defaultEasing }}
    className={className}
  >
    {children}
  </motion.div>
);

export const SlideIn: React.FC<AnimatedProps & { direction?: 'left' | 'right' }> = ({
  children,
  delay = 0,
  duration = 0.4,
  direction = 'right',
  className = '',
}) => (
  <motion.div
    initial={{ opacity: 0, x: direction === 'right' ? 30 : -30 }}
    animate={{ opacity: 1, x: 0 }}
    transition={{ duration, delay, ease: defaultEasing }}
    className={className}
  >
    {children}
  </motion.div>
);

export const ScaleIn: React.FC<AnimatedProps> = ({
  children,
  delay = 0,
  duration = 0.35,
  className = '',
}) => (
  <motion.div
    initial={{ opacity: 0, scale: 0.95 }}
    animate={{ opacity: 1, scale: 1 }}
    transition={{ duration, delay, ease: defaultEasing }}
    className={className}
  >
    {children}
  </motion.div>
);

// ============================================================
// 4. STAGGER LIST — Animação sequencial de itens
// ============================================================

interface StaggerListProps {
  children: React.ReactNode[];
  staggerDelay?: number;
  itemDuration?: number;
  className?: string;
}

export const StaggerList: React.FC<StaggerListProps> = ({
  children,
  staggerDelay = 0.08,
  itemDuration = 0.35,
  className = '',
}) => {
  const containerVariants: Variants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: { staggerChildren: staggerDelay },
    },
  };

  const itemVariants: Variants = {
    hidden: { opacity: 0, y: 15 },
    visible: {
      opacity: 1,
      y: 0,
      transition: { duration: itemDuration, ease: defaultEasing },
    },
  };

  return (
    <motion.div
      variants={containerVariants}
      initial="hidden"
      animate="visible"
      className={className}
    >
      {React.Children.map(children, (child, i) => (
        <motion.div key={i} variants={itemVariants}>
          {child}
        </motion.div>
      ))}
    </motion.div>
  );
};

// ============================================================
// 5. SCROLL TRIGGER — Animação ao entrar no viewport
// ============================================================

interface ScrollRevealProps {
  children: React.ReactNode;
  threshold?: number;
  triggerOnce?: boolean;
  animation?: 'fade' | 'slideUp' | 'slideLeft' | 'slideRight' | 'scale';
  delay?: number;
  className?: string;
}

export const ScrollReveal: React.FC<ScrollRevealProps> = ({
  children,
  threshold = 0.2,
  triggerOnce = true,
  animation = 'slideUp',
  delay = 0,
  className = '',
}) => {
  const { ref, inView } = useInView({ threshold, triggerOnce });

  const animations = {
    fade: { opacity: 0 },
    slideUp: { opacity: 0, y: 30 },
    slideLeft: { opacity: 0, x: -30 },
    slideRight: { opacity: 0, x: 30 },
    scale: { opacity: 0, scale: 0.9 },
  };

  return (
    <motion.div
      ref={ref}
      initial={animations[animation]}
      animate={inView ? { opacity: 1, y: 0, x: 0, scale: 1 } : {}}
      transition={{ duration: 0.5, delay, ease: defaultEasing }}
      className={className}
    >
      {children}
    </motion.div>
  );
};

// ============================================================
// 6. PAGE TRANSITION — Transição entre screens
// ============================================================

interface PageTransitionProps {
  children: React.ReactNode;
  direction?: number;
  className?: string;
  viewKey?: string;
}

export const PageTransition: React.FC<PageTransitionProps> = ({
  children,
  direction = 1,
  className = '',
  viewKey,
}) => (
  <AnimatePresence mode="wait">
    <motion.div
      key={viewKey}
      initial={{ opacity: 0, x: direction > 0 ? 50 : -50 }}
      animate={{ opacity: 1, x: 0 }}
      exit={{ opacity: 0, x: direction > 0 ? -50 : 50 }}
      transition={{ duration: 0.35, ease: defaultEasing }}
      className={className}
    >
      {children}
    </motion.div>
  </AnimatePresence>
);

// ============================================================
// 7. MODAL / PANEL — Com enter/exit animations
// ============================================================

interface AnimatedPanelProps {
  children: React.ReactNode;
  isOpen: boolean;
  onClose?: () => void;
  className?: string;
  position?: 'bottom' | 'right' | 'center';
}

export const AnimatedPanel: React.FC<AnimatedPanelProps> = ({
  children,
  isOpen,
  onClose,
  className = '',
  position = 'bottom',
}) => {
  const positionAnimations = {
    bottom: {
      hidden: { y: '100%' },
      visible: { y: 0 },
    },
    right: {
      hidden: { x: '100%' },
      visible: { x: 0 },
    },
    center: {
      hidden: { opacity: 0, scale: 0.95 },
      visible: { opacity: 1, scale: 1 },
    },
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <>
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black/50 z-40"
            onClick={onClose}
          />
          <motion.div
            initial={positionAnimations[position].hidden}
            animate={positionAnimations[position].visible}
            exit={positionAnimations[position].hidden}
            transition={{ duration: 0.3, ease: defaultEasing }}
            className={`fixed z-50 ${className}`}
          >
            {children}
          </motion.div>
        </>
      )}
    </AnimatePresence>
  );
};

// ============================================================
// 8. MICRO-INTERACTIONS — Botões, cards, toggles
// ============================================================

interface InteractiveProps {
  children: React.ReactNode;
  onClick?: () => void;
  className?: string;
  disabled?: boolean;
}

export const InteractiveButton: React.FC<InteractiveProps> = ({
  children,
  onClick,
  className = '',
  disabled = false,
}) => (
  <motion.button
    whileTap={disabled ? {} : { scale: 0.97 }}
    whileHover={disabled ? {} : { scale: 1.02 }}
    transition={{ type: 'spring', stiffness: 400, damping: 17 }}
    onClick={onClick}
    disabled={disabled}
    className={className}
  >
    {children}
  </motion.button>
);

export const InteractiveCard: React.FC<InteractiveProps> = ({
  children,
  onClick,
  className = '',
}) => (
  <motion.div
    whileTap={{ scale: 0.98 }}
    whileHover={{ scale: 1.01, y: -2 }}
    transition={{ type: 'spring', stiffness: 300, damping: 20 }}
    onClick={onClick}
    className={`cursor-pointer ${className}`}
  >
    {children}
  </motion.div>
);

// ============================================================
// 9. PROGRESS INDICATORS — Determinados e indeterminados
// ============================================================

interface ProgressBarProps {
  progress: number;
  className?: string;
  color?: string;
}

export const ProgressBar: React.FC<ProgressBarProps> = ({
  progress,
  className = '',
  color = 'bg-blue-600',
}) => (
  <div className={`w-full h-2 bg-gray-200 rounded-full overflow-hidden ${className}`}>
    <motion.div
      className={`h-full ${color} rounded-full`}
      initial={{ width: 0 }}
      animate={{ width: `${Math.min(progress, 100)}%` }}
      transition={{ duration: 0.5, ease: defaultEasing }}
    />
  </div>
);

// ============================================================
// 10. REDUCED MOTION — Respeitar preferências de acessibilidade
// ============================================================

import { useReducedMotion } from 'framer-motion';

export const usePrefersReducedMotion = (): boolean => {
  return useReducedMotion() || false;
};

export const AccessibleMotion: React.FC<{
  children: React.ReactNode;
  className?: string;
}> = ({ children, className = '' }) => {
  const shouldReduce = usePrefersReducedMotion();
  if (shouldReduce) {
    return <div className={className}>{children}</div>;
  }
  return <>{children}</>;
};

export default {
  Skeleton,
  SkeletonText,
  SkeletonCard,
  SkeletonBodyMap,
  LazyLoad,
  FadeIn,
  SlideUp,
  SlideIn,
  ScaleIn,
  StaggerList,
  ScrollReveal,
  PageTransition,
  AnimatedPanel,
  InteractiveButton,
  InteractiveCard,
  ProgressBar,
  usePrefersReducedMotion,
  AccessibleMotion,
};

