interface TooltipProps {
  text: string;
  children: React.ReactNode;
  position?: 'top' | 'bottom' | 'left' | 'right';
  icon?: boolean;
  small?: boolean;
}

export const Tooltip: React.FC<TooltipProps> = ({
  text,
  children,
  position = 'top',
  icon = true,
  small = false,
}) => {
  const [show, setShow] = useState(false);

  const getPositionStyles = () => {
    switch (position) {
      case 'bottom':
        return { top: '100%', left: '50%', transform: 'translateX(-50%)', marginTop: 8 };
      case 'left':
        return { right: '100%', top: '50%', transform: 'translateY(-50%)', marginRight: 8 };
      case 'right':
        return { left: '100%', top: '50%', transform: 'translateY(-50%)', marginLeft: 8 };
      default:
        return { bottom: '100%', left: '50%', transform: 'translateX(-50%)', marginBottom: 8 };
    }
  };

  const getArrowStyles = () => {
    switch (position) {
      case 'bottom':
        return { top: -5, left: '50%', transform: 'translateX(-50%) rotate(45deg)' };
      case 'left':
        return { right: -5, top: '50%', transform: 'translateY(-50%) rotate(45deg)' };
      case 'right':
        return { left: -5, top: '50%', transform: 'translateY(-50%) rotate(45deg)' };
      default:
        return { bottom: -5, left: '50%', transform: 'translateX(-50%) rotate(45deg)' };
    }
  };

  return (
    <div
      style={{
        position: 'relative',
        display: 'inline-flex',
        alignItems: 'center',
        gap: 4,
        cursor: 'help',
      }}
      onMouseEnter={() => setShow(true)}
      onMouseLeave={() => setShow(false)}
      onTouchStart={() => setShow(!show)}
    >
      {children}
      {icon && (
        <span
          style={{ color: C.muted, fontSize: small ? 10 : 12, lineHeight: 1, userSelect: 'none' }}
        >
          ℹ️
        </span>
      )}
      {show && (
        <div
          style={{
            position: 'absolute',
            ...getPositionStyles(),
            width: small ? 180 : 240,
            padding: small ? 8 : 12,
            background: '#1e2832',
            color: '#e2e8f0',
            borderRadius: 8,
            fontSize: small ? 11 : 12,
            boxShadow: '0 10px 25px rgba(0,0,0,0.5)',
            border: `1px solid ${C.border}`,
            zIndex: 1000,
            textAlign: 'center',
            lineHeight: 1.5,
            whiteSpace: 'normal',
            wordBreak: 'break-word',
          }}
        >
          {text}
          <div
            style={{
              position: 'absolute',
              width: 10,
              height: 10,
              background: '#1e2832',
              borderRight: `1px solid ${C.border}`,
              borderBottom: `1px solid ${C.border}`,
              ...getArrowStyles(),
            }}
          />
        </div>
      )}
    </div>
  );
};

// Componente para adicionar tooltip a um label
export const LabelWithTooltip: React.FC<{
  label: string;
