// Temporizador de "tempo sob tensão" para o modo Mobilidade
import { useEffect, useRef, useState } from 'react';

interface Props {
  exerciseName: string;
  defaultSeconds?: number;
}

export function MobilityTimer({ exerciseName, defaultSeconds = 30 }: Props) {
  const [targetSeconds, setTargetSeconds] = useState(defaultSeconds);
  const [timeLeft, setTimeLeft] = useState(defaultSeconds);
  const [isRunning, setIsRunning] = useState(false);
  const [completed, setCompleted] = useState(false);
  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);

  useEffect(() => {
    if (!isRunning) return;
    intervalRef.current = setInterval(() => {
      setTimeLeft((prev) => {
        if (prev <= 1) {
          setIsRunning(false);
          setCompleted(true);
          navigator.vibrate?.([200, 100, 200]);
          return 0;
        }
        return prev - 1;
      });
    }, 1000);
    return () => clearInterval(intervalRef.current!);
  }, [isRunning]);

  const reset = () => {
    setIsRunning(false);
    setCompleted(false);
    setTimeLeft(targetSeconds);
  };

  const progress = 1 - timeLeft / targetSeconds;
  const circumference = 2 * Math.PI * 40;
  const strokeDashoffset = circumference * (1 - progress);

  return (
    <div
      style={{
        background: 'rgba(167, 139, 250, 0.08)',
        border: '1px solid rgba(167, 139, 250, 0.25)',
        borderRadius: 16,
        padding: 20,
        marginBottom: 16,
      }}
    >
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          marginBottom: 16,
        }}
      >
        <div>
          <p
            style={{
              fontSize: 10,
              color: '#a78bfa',
              fontFamily: "'DM Mono', monospace",
              letterSpacing: 2,
            }}
          >
            🧘 TEMPO SOB TENSÃO
          </p>
          <p style={{ fontSize: 14, color: '#eceae4', fontWeight: 600 }}>{exerciseName}</p>
        </div>

        {/* Duração em segundos */}
        <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
          <button
            onClick={() => {
              const next = Math.max(10, targetSeconds - 10);
              setTargetSeconds(next);
              if (!isRunning) setTimeLeft(next);
            }}
            style={{
              background: 'rgba(255,255,255,0.08)',
              border: 'none',
              borderRadius: 6,
              width: 26,
              height: 26,
              color: '#fff',
              cursor: 'pointer',
              fontSize: 14,
            }}
          >
            −
          </button>
          <span
            style={{
              fontFamily: "'DM Mono', monospace",
              fontSize: 14,
              color: '#a78bfa',
              minWidth: 36,
              textAlign: 'center',
            }}
          >
            {targetSeconds}s
          </span>
          <button
            onClick={() => {
              const next = targetSeconds + 10;
              setTargetSeconds(next);
              if (!isRunning) setTimeLeft(next);
            }}
            style={{
