              cy="50"
              r="40"
              fill="none"
              stroke="rgba(167,139,250,0.15)"
              strokeWidth="8"
            />
            <circle
              cx="50"
              cy="50"
              r="40"
              fill="none"
              stroke="#a78bfa"
              strokeWidth="8"
