                <motion.span
                  key="time"
                  style={{
                    fontFamily: "'DM Mono', monospace",
                    fontSize: 24,
                    fontWeight: 700,
                    color: completed ? '#3dd68c' : '#a78bfa',
                  }}
                >
                  {timeLeft}
                </motion.span>
              )}
            </AnimatePresence>
          </div>
        </div>
      </div>

      {/* Botões de controlo */}
      <div style={{ display: 'flex', gap: 8 }}>
        <button
          onClick={() => setIsRunning((r) => !r)}
          disabled={completed}
          style={{
            flex: 2,
            background: isRunning ? 'rgba(239, 68, 68, 0.2)' : 'rgba(167, 139, 250, 0.25)',
            border: `1px solid ${isRunning ? '#ef4444' : '#a78bfa'}`,
            borderRadius: 10,
            padding: 12,
            color: isRunning ? '#fca5a5' : '#a78bfa',
            fontFamily: "'Bebas Neue', cursive",
            fontSize: 16,
            letterSpacing: 1.5,
            cursor: 'pointer',
          }}
        >
          {isRunning ? '⏸ PAUSAR' : completed ? '✓ COMPLETO' : '▶ INICIAR'}
        </button>
        <button
          onClick={reset}
          style={{
            flex: 1,
            background: 'rgba(255,255,255,0.06)',
            border: '1px solid rgba(255,255,255,0.1)',
            borderRadius: 10,
            padding: 12,
            color: '#55626e',
            fontFamily: "'Bebas Neue', cursive",
            fontSize: 16,
            letterSpacing: 1,
            cursor: 'pointer',
          }}
        >
          ↺ RESET
        </button>
      </div>
    </div>
  );
}

