import { useCallback, useEffect, useRef, useState } from 'react';
import { C } from '../../data/constants';
import { useAudioCoach } from '../../hooks/useAudioCoach';
import { useBluetoothHRM } from '../../hooks/useBluetoothHRM';
import { useProgressiveHaptics } from '../../hooks/useProgressiveHaptics';
import { useRobustTimer } from '../../hooks/useRobustTimer';

// Em atletas de Elite, a recuperação entre séries deve ser avaliada pelo ritmo cardíaco
const RECOVERY_THRESHOLD_BPM = 120;

/**
 * Beep player with AudioContext resume support for browser autoplay policy.
 * Requires user interaction first (click) to initialize audio context.
 */
function createBeepPlayer() {
  let audioCtx: AudioContext | null = null;

  const getContext = () => {
    if (!audioCtx) {
      const AudioCtx = window.AudioContext || (window as any).webkitAudioContext;
      if (!AudioCtx) return null;
      audioCtx = new AudioCtx();
    }
    if (audioCtx.state === 'suspended') {
      audioCtx.resume();
    }
    return audioCtx;
  };

  const playBeep = (frequency = 880, duration = 0.15) => {
    const ctx = getContext();
    if (!ctx) return;

    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(frequency, ctx.currentTime);
    gain.gain.setValueAtTime(0.15, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + duration);
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.start(ctx.currentTime);
    osc.stop(ctx.currentTime + duration);
  };

  return { playBeep };
}

export function RestTimer({ onClose }: { onClose: () => void }) {
  const [preset, setPreset] = useState(90);
  const [sec, setSec] = useState(90);
  const [on, setOn] = useState(true);
  const [suggestion, setSuggestion] = useState<string | null>(null);
  const [userInteracted, setUserInteracted] = useState(false);

  const fired = useRef(false);
  const maxWaitRef = useRef(0);
  const beepPlayer = useRef(createBeepPlayer());

  const { triggerRestTimerHaptic, playAlertBeep } = useProgressiveHaptics();

  // FASE 2: Integração de Hardware HRR (Heart Rate Recovery)
  const { bpm, status, connect } = useBluetoothHRM();
  const { speak } = useAudioCoach();

  const R = 68,
    circ = 2 * Math.PI * R;
  const pct = Math.max(0, Math.min(1, (preset - sec) / preset));

  // A série fica "Feita" se o relógio acabar OU se o coração já estiver recuperado (HRR)
  const isHeartRecovered = bpm > 0 && bpm <= RECOVERY_THRESHOLD_BPM;
  const isDone = sec <= 0 || isHeartRecovered;
  const crit = sec > 0 && sec <= 5;
  const fmt = (s: number) => `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;

  // Resume AudioContext on user interaction (click)
  const handleUserInteraction = useCallback(() => {
    if (!userInteracted) {
      setUserInteracted(true);
    }
  }, [userInteracted]);

  const playBeepSound = useCallback(() => {
    if (userInteracted) {
      beepPlayer.current.playBeep(880, 0.15);
      playAlertBeep(880, 0.1, 2);
    } else {
      // Fallback vibrate if AudioContext not yet allowed
      navigator.vibrate?.(100);
    }
  }, [userInteracted, playAlertBeep]);

  const handleComplete = useCallback(() => {
    if (!fired.current) {
      fired.current = true;
      setSec(0);
      triggerRestTimerHaptic(0);
      playBeepSound();
      speak('Descanso terminado. Prepara a próxima série.');
    }
  }, [triggerRestTimerHaptic, speak, playBeepSound]);

  const handleTick = useCallback(
    (s: number) => {
      maxWaitRef.current += 1;
      setSec((prev) => {
        if (prev !== s) {
          if (s > 0 && s <= 5) {
            triggerRestTimerHaptic(s);
            if (s === 1) playBeepSound();
          }

          // SNC Protect: Se o descanso passou os 2 minutos e o coração não desce
          if (maxWaitRef.current >= 120 && bpm > RECOVERY_THRESHOLD_BPM) {
            setSuggestion('Fadiga central elevada! Reduz a carga em 10% na próxima série.');
          }

          return s;
        }
        return prev;
      });
    },
    [triggerRestTimerHaptic, bpm, playBeepSound],
  );

  const { start } = useRobustTimer(preset, handleTick, handleComplete);

  useEffect(() => {
    if (on && sec > 0) {
      start();
    }
  }, [preset, on, start, sec]);

  // Se o coração recuperou, disparamos o feedback tátil e alertamos o atleta
  useEffect(() => {
    if (isHeartRecovered && !fired.current) {
      fired.current = true;
      triggerRestTimerHaptic(0);
      speak('Ritmo cardíaco recuperado. Série autorizada.');
    }
  }, [isHeartRecovered, triggerRestTimerHaptic, speak]);

  useEffect(() => {
    if (suggestion) {
      speak(suggestion, true);
    }
  }, [suggestion, speak]);

  const pick = (p: number) => {
    setPreset(p);
    setSec(p);
    setOn(true);
    fired.current = false;
    maxWaitRef.current = 0;
    setSuggestion(null);
  };

  return (
    <div
      onClick={handleUserInteraction}
      style={{
        position: 'fixed',
        inset: 0,
        background: 'rgba(8,11,15,0.95)',
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        zIndex: 300,
        padding: 24,
      }}
    >
      <div
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          width: '100%',
          maxWidth: 300,
          marginBottom: 20,
        }}
      >
        <p
          style={{
            fontFamily: "'Bebas Neue'",
            fontSize: 11,
            letterSpacing: 5,
            color: C.muted,
            margin: 0,
          }}
        >
          DESCANSO
        </p>

        <button
          onClick={connect}
          style={{
            background: 'none',
            border: `1px solid ${status === 'CONNECTED' ? C.green : C.muted}`,
            borderRadius: 12,
            padding: '2px 8px',
            color: status === 'CONNECTED' ? C.green : C.muted,
            fontSize: 10,
            cursor: 'pointer',
          }}
        >
          {status === 'CONNECTED' ? `❤️ ${bpm} BPM` : '🔗 CONETAR HRM'}
        </button>
      </div>

      <svg width={186} height={186}>
        <circle cx={93} cy={93} r={R} fill="none" stroke={C.dim} strokeWidth={7} />
        <circle
          cx={93}
          cy={93}
          r={R}
          fill="none"
          stroke={isDone ? C.green : crit ? C.red : C.accent}
          strokeWidth={7}
          strokeLinecap="round"
          strokeDasharray={circ}
          strokeDashoffset={circ * (1 - pct)}
          transform="rotate(-90 93 93)"
          style={{ transition: isDone ? 'none' : 'stroke-dashoffset 1s linear, stroke 0.3s' }}
        />
        <text
          x={93}
          y={87}
          textAnchor="middle"
          fill={isDone ? C.green : crit ? C.red : C.text}
          fontSize={isDone ? 26 : 40}
          fontFamily="Bebas Neue"
          letterSpacing={2}
        >
          {isDone ? 'GO!' : fmt(sec)}
        </text>
        <text x={93} y={108} textAnchor="middle" fill={C.muted} fontSize={10} fontFamily="DM Mono">
          {isDone ? 'Coração Recuperado' : `${preset}s`}
        </text>
      </svg>

      {suggestion && (
        <div
          style={{
            background: `${C.red}22`,
            border: `1px solid ${C.red}`,
            borderRadius: 8,
            padding: 12,
            marginTop: 16,
            maxWidth: 280,
            textAlign: 'center',
          }}
        >
          <span style={{ fontSize: 16, display: 'block' }}>⚠️</span>
          <span style={{ fontSize: 11, color: C.text, fontWeight: 'bold' }}>{suggestion}</span>
        </div>
      )}

      {!userInteracted && (
        <div
          style={{
            background: 'rgba(249,115,22,0.1)',
            border: '1px solid rgba(249,115,22,0.3)',
            borderRadius: 8,
            padding: '8px 12px',
            marginTop: 12,
            maxWidth: 280,
            textAlign: 'center',
            fontSize: 10,
            color: '#f97316',
          }}
        >
          🎵 Clique para ativar som do cronómetro
        </div>
      )}

      <div style={{ display: 'flex', gap: 8, marginTop: 24 }}>
        {[30, 60, 90, 120, 180].map((p) => (
          <button
            key={p}
            onClick={() => pick(p)}
            style={{
              background: preset === p ? C.accentLow : C.card,
              border: `1px solid ${preset === p ? C.accent : C.border}`,
              borderRadius: 6,
              padding: '6px 11px',
              color: preset === p ? C.accent : C.muted,
              fontSize: 11,
              fontFamily: "'DM Mono'",
              cursor: 'pointer',
            }}
          >
            {p}s
          </button>
        ))}
      </div>
      <div style={{ display: 'flex', gap: 10, marginTop: 16 }}>
        <button
          onClick={() => setOn((a) => !a)}
          style={{
            background: C.card,
            border: `1px solid ${C.border}`,
            borderRadius: 8,
            padding: '10px 18px',
            color: C.text,
            cursor: 'pointer',
            fontFamily: "'Barlow'",
            fontWeight: 600,
            fontSize: 13,
          }}
        >
          {on ? '⏸ Pausar' : '▶ Continuar'}
        </button>
        <button
          onClick={onClose}
          style={{
            background: C.accent,
            border: 'none',
            borderRadius: 8,
            padding: '10px 18px',
            color: '#000',
            cursor: 'pointer',
            fontFamily: "'Barlow'",
            fontWeight: 700,
            fontSize: 13,
          }}
        >
          ✓ Fechar
        </button>
      </div>
    </div>
  );
}

import { useEffect, useRef } from 'react';
import { C } from '../../data/constants';
import type { Hazard } from '../../hooks/useWalkingCoach';

interface GPSPoint {
  lat: number;
  lng: number;
}

interface WalkingMapProps {
  path: GPSPoint[];
  isActive: boolean;
  ghostPosition?: GPSPoint | null;
  hazards?: Hazard[];
}

export function WalkingMap({ path, isActive, ghostPosition, hazards = [] }: WalkingMapProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    const container = containerRef.current;
    if (!canvas || !container) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animationFrame: number;

    // Collect all points that need to be in the viewport
    const allPoints: GPSPoint[] = [...path];
    if (ghostPosition) allPoints.push(ghostPosition);
    hazards.forEach((hz) => allPoints.push({ lat: hz.lat, lng: hz.lng }));

    const draw = () => {
      // Ajustar resolução
      const rect = container.getBoundingClientRect();
      const dpr = window.devicePixelRatio || 1;

      if (canvas.width !== rect.width * dpr || canvas.height !== rect.height * dpr) {
        canvas.width = rect.width * dpr;
        canvas.height = rect.height * dpr;
        ctx.scale(dpr, dpr);
      } else {
        ctx.clearRect(0, 0, rect.width, rect.height);
      }

      // Desenhar grelha
      ctx.strokeStyle = 'rgba(255, 255, 255, 0.05)';
      ctx.lineWidth = 1;
      for (let x = 0; x < rect.width; x += 20) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, rect.height);
        ctx.stroke();
      }
      for (let y = 0; y < rect.height; y += 20) {
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(rect.width, y);
        ctx.stroke();
      }

      if (allPoints.length > 0) {
        const first = allPoints[0]!;
        let minLat = first.lat,
          maxLat = first.lat;
        let minLng = first.lng,
          maxLng = first.lng;
        allPoints.forEach((p) => {
          if (p.lat < minLat) minLat = p.lat;
          if (p.lat > maxLat) maxLat = p.lat;
          if (p.lng < minLng) minLng = p.lng;
          if (p.lng > maxLng) maxLng = p.lng;
        });

        const latRange = Math.max(maxLat - minLat, 0.0001);
        const lngRange = Math.max(maxLng - minLng, 0.0001);

        const paddingX = rect.width * 0.15;
        const paddingY = rect.height * 0.15;
        const usableW = rect.width - paddingX * 2;
        const usableH = rect.height - paddingY * 2;

        const mapX = (lng: number) => paddingX + ((lng - minLng) / lngRange) * usableW;
        const mapY = (lat: number) => paddingY + (1 - (lat - minLat) / latRange) * usableH;

        // ── Desenhar trajeto ──
        if (path.length > 1) {
          ctx.beginPath();
          ctx.moveTo(mapX(path[0]!.lng), mapY(path[0]!.lat));
          for (let i = 1; i < path.length; i++) {
            ctx.lineTo(mapX(path[i]!.lng), mapY(path[i]!.lat));
          }

          ctx.strokeStyle = C.accent;
          ctx.lineWidth = 4;
          ctx.lineCap = 'round';
          ctx.lineJoin = 'round';
          ctx.shadowBlur = 10;
          ctx.shadowColor = C.accent;
          ctx.stroke();
          ctx.shadowBlur = 0;
        }

        // ── 👻 Ghost Marker ──
        if (ghostPosition) {
          const gx = mapX(ghostPosition.lng);
          const gy = mapY(ghostPosition.lat);
          const time = Date.now() / 1000;

          // Ghost glow
          ctx.beginPath();
          ctx.arc(gx, gy, 14 + Math.sin(time * 2) * 3, 0, 2 * Math.PI);
          ctx.fillStyle = 'rgba(148, 163, 184, 0.15)';
          ctx.fill();

          // Ghost body
          ctx.beginPath();
          ctx.arc(gx, gy, 7, 0, 2 * Math.PI);
          ctx.fillStyle = 'rgba(148, 163, 184, 0.6)';
          ctx.shadowBlur = 12;
          ctx.shadowColor = 'rgba(148, 163, 184, 0.8)';
          ctx.fill();
          ctx.shadowBlur = 0;

          // Ghost label
          ctx.font = 'bold 9px "Outfit", sans-serif';
          ctx.fillStyle = 'rgba(148, 163, 184, 0.8)';
          ctx.textAlign = 'center';
          ctx.fillText('GHOST', gx, gy - 14);
        }

        // ── 📍 Hazard Markers ──
        hazards.forEach((hz) => {
          const hx = mapX(hz.lng);
          const hy = mapY(hz.lat);

          const colors: Record<string, { fill: string; glow: string }> = {
            danger: { fill: '#f97316', glow: 'rgba(249, 115, 22, 0.6)' },
            water: { fill: '#3b82f6', glow: 'rgba(59, 130, 246, 0.6)' },
            info: { fill: '#22c55e', glow: 'rgba(34, 197, 94, 0.6)' },
          };
          const color = colors[hz.type] ?? colors['info']!;

          // Diamond shape (rotated square)
          ctx.save();
          ctx.translate(hx, hy);
          ctx.rotate(Math.PI / 4);

          // Glow
          ctx.shadowBlur = 10;
          ctx.shadowColor = color.glow;
          ctx.fillStyle = color.fill;
          ctx.fillRect(-5, -5, 10, 10);
          ctx.shadowBlur = 0;

          ctx.restore();

          // Emoji label
          const emoji = hz.type === 'danger' ? '⚠️' : hz.type === 'water' ? '💧' : 'ℹ️';
          ctx.font = '10px sans-serif';
          ctx.textAlign = 'center';
          ctx.fillText(emoji, hx, hy - 12);
        });

        // ── Posição atual do atleta ──
        if (path.length > 0) {
          const lastPoint = path[path.length - 1]!;
          const endX = mapX(lastPoint.lng);
          const endY = mapY(lastPoint.lat);

          const time = Date.now() / 1000;
          const pulseRadius = 10 + Math.sin(time * 3) * 4;
          ctx.beginPath();
          ctx.arc(endX, endY, pulseRadius, 0, 2 * Math.PI);
          ctx.fillStyle = `rgba(204, 255, 0, ${0.2 + Math.sin(time * 3) * 0.1})`;
          ctx.fill();

          ctx.beginPath();
          ctx.arc(endX, endY, 6, 0, 2 * Math.PI);
          ctx.fillStyle = '#ffffff';
          ctx.shadowBlur = 15;
          ctx.shadowColor = '#ffffff';
          ctx.fill();
          ctx.shadowBlur = 0;
        }
      }

      animationFrame = requestAnimationFrame(draw);
    };

    draw();

    return () => cancelAnimationFrame(animationFrame);
  }, [path, isActive, ghostPosition, hazards]);

  return (
    <div
      ref={containerRef}
      style={{ width: '100%', height: '100%', position: 'relative', background: '#080b0f' }}
    >
      {!isActive && path.length === 0 ? (
        <div
          style={{
            position: 'absolute',
            inset: 0,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            background: 'rgba(8,11,15,0.8)',
            zIndex: 10,
            color: C.muted,
            fontSize: 12,
          }}
        >
          AGUARDAR SINAL GPS...
        </div>
      ) : null}

      <canvas ref={canvasRef} style={{ width: '100%', height: '100%', display: 'block' }} />
    </div>
  );
}

import { motion } from 'framer-motion';

import { useState } from 'react';
import { C } from '../../data/constants';
import { AnthropicService } from '../../services/anthropicService';
import { useDualWorkoutStore } from '../../stores/useDualWorkoutStore';
import { usePlanStore } from '../../stores/usePlanStore';

interface WeeklyPlanGeneratorProps {
  profile: any;
  setProfile: (p: any) => void;
  onClose: () => void;
}

const WEEK_DAYS = ['Segunda', 'Terça', 'Quarta', 'Quinta', 'Sexta', 'Sábado', 'Domingo'];

export function WeeklyPlanGenerator({
  profile,
  setProfile,
  onClose,
}: WeeklyPlanGeneratorProps) {
  const [weight, setWeight] = useState(profile.weight || '');
  const [height, setHeight] = useState(profile.height || '');
  const [gender, setGender] = useState(profile.gender || 'Feminino');
  const [age, setAge] = useState(profile.age || 25);
  const [goal, setGoal] = useState(profile.goal || 'Hipertrofia');

  const [equipment, setEquipment] = useState(profile.availableEquipment?.[0] || 'Ginásio Completo');
  const [trainingDays, setTrainingDays] = useState<string[]>(
    profile.trainingDays || ['Segunda', 'Quarta', 'Sexta'],
  );
  const [duration, setDuration] = useState(profile.preferredWorkoutDuration || 60);
  const [injuries, setInjuries] = useState(profile.injuries?.join(', ') || '');
  const [philosophy, setPhilosophy] = useState(profile.philosophy || 'classic');
  const [classicStyle, setClassicStyle] = useState(profile.classicStyle || 'upper_lower');
  const [dayPreferences, setDayPreferences] = useState<Record<string, string>>(
    profile.dayPreferences || {},
  );
  const [preferredSlot, setPreferredSlot] = useState<'morning' | 'afternoon'>('morning');
  const [customDays, setCustomDays] = useState<string[]>(
    Object.entries(profile.dayPreferences || {})
      .filter(([, val]) => {
        return (
          val &&
          ![
            'Padrão',
            'Pernas',
            'Peito',
            'Costas',
            'Ombros',
            'Braços',
            'Core',
            'Cardio/HIIT',
          ].includes(val as string)
        );
      })
      .map(([day]) => day as string),
  );

  const { setCurrentPlan } = usePlanStore();
  const { scheduleWorkout } = useDualWorkoutStore();

  const [isGenerating, setIsGenerating] = useState(false);
  const [plan, setPlan] = useState<any>(null);
  const [step, setStep] = useState('info');

  const toggleDay = (day: string) => {
    setTrainingDays((prev) =>
      prev.includes(day) ? prev.filter((d) => d !== day) : [...prev, day],
    );
  };

  const handleSaveInfo = () => {
    if (!weight || !height) {
      alert('Preenche pelo menos o Peso e Altura!');
      return;
    }
    if (trainingDays.length === 0) {
      alert('Seleciona pelo menos um dia de treino!');
      return;
    }
    setProfile({
      ...profile,
      weight: Number(weight),
      height: Number(height),
      age: Number(age),
      gender,
      goal,
      philosophy,
      classicStyle,
      availableEquipment: [equipment],
      trainingDays: trainingDays,
      preferredWorkoutDuration: Number(duration),
      injuries: injuries
        .split(',')
        .map((s: string) => s.trim())
        .filter((s: string) => s),
      dayPreferences: dayPreferences,
    });
    setStep('generate');
  };

  const handleGenerate = async () => {
    setIsGenerating(true);
    let generated: any = null;
    try {
      generated = await AnthropicService.generateWeeklyPlan(
        {
          ...profile,
          weight: Number(weight),
          height: Number(height),
          age: Number(age),
          gender,
          goal,
          philosophy,
          classicStyle,
          availableEquipment: [equipment],
          trainingDays: trainingDays,
          preferredWorkoutDuration: Number(duration),
          injuries: injuries
            .split(',')
            .map((s: string) => s.trim())
            .filter((s: string) => s),
          dayPreferences: dayPreferences,
        },
        philosophy,
      );
    } catch (error: any) {
      console.error('Erro crítico na geração do plano:', error);
      alert(
        'Erro crítico: Não foi possível processar o plano. Ocorreu uma falha no motor offline ou na IA.',
      );
    } finally {
      setIsGenerating(false);
    }

    if (generated && generated.plan) {
      const newPlan = {
        id: crypto.randomUUID(),
        name: generated.name || 'Plano IA Gerado',
        type: philosophy as any,
        description: generated.description || generated.reasoning || 'Plano personalizado.',
        workouts: generated.plan,
        createdAt: Date.now(),
      };
      setPlan(newPlan);
      setCurrentPlan(newPlan);

      // Injetar treinos gerados no Calendário Global (Agenda)
      const daysMap: Record<string, number> = {
        domingo: 0,
        segunda: 1,
        terça: 2,
        quarta: 3,
        quinta: 4,
        sexta: 5,
        sábado: 6,
      };
      const today = new Date();
      const currentDay = today.getDay();

      generated.plan.forEach((dayPlan: any) => {
        // Normalizar "Segunda-feira" -> "segunda"
        const normalizedDay = dayPlan.day.toLowerCase().split('-')[0].trim();
        const targetDay = daysMap[normalizedDay];

        if (targetDay !== undefined) {
          let daysUntil = targetDay - currentDay;
          if (daysUntil < 0) daysUntil += 7; // Empurra para a próxima semana se o dia já passou

          const targetDate = new Date(today);
          targetDate.setDate(today.getDate() + daysUntil);

          // Prevenir bug de fuso horário do toISOString() que empurra 1 dia para a frente
          const year = targetDate.getFullYear();
          const month = String(targetDate.getMonth() + 1).padStart(2, '0');
          const day = String(targetDate.getDate()).padStart(2, '0');
          const dateString = `${year}-${month}-${day}`;

          const isRest =
            dayPlan.focus.toLowerCase().includes('descanso') ||
            dayPlan.focus.toLowerCase().includes('recupera');
          if (!isRest) {
            scheduleWorkout(dateString, preferredSlot, newPlan.id, `${dayPlan.focus}`);
          }
        }
      });
    } else if (generated && generated.error) {
      alert('Erro detalhado da IA: ' + generated.error);
    } else {
      alert('Falha ao gerar plano. Verifica a tua ligação ou tenta novamente.');
    }
  };



  return (
    <div
      style={{
        position: 'fixed',
        inset: 0,
        background: 'rgba(8,11,15,0.95)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        zIndex: 300,
        padding: 24,
        backdropFilter: 'blur(5px)',
      }}
    >
      <div
        style={{
          background: C.card,
          border: `1px solid ${C.accent}`,
          borderRadius: 14,
          padding: 26,
          maxWidth: 400,
          width: '100%',
          maxHeight: '85vh',
          overflowY: 'auto',
        }}
      >
        <div
          style={{
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            marginBottom: 20,
          }}
        >
          <p
            style={{
              fontFamily: "'Bebas Neue'",
              fontSize: 24,
              letterSpacing: 2,
              color: C.accent,
              margin: 0,
            }}
          >
            📅 PLANO DE ELITE IA
          </p>
          <button
            onClick={onClose}
            style={{
              background: 'none',
              border: 'none',
              color: C.muted,
              fontSize: 20,
              cursor: 'pointer',
            }}
          >
            ×
          </button>
        </div>

        {step === 'info' && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
            <p style={{ fontSize: 13, color: '#fff', marginBottom: 16 }}>
              Configura as variáveis de biofeedback para uma precisão de Personal Trainer.
            </p>

            <div style={{ display: 'flex', gap: 10, marginBottom: 12 }}>
              <div style={{ flex: 1 }}>
                <label style={{ display: 'block', fontSize: 12, color: C.muted, marginBottom: 4 }}>
                  GÉNERO
                </label>
                <select
                  value={gender}
                  onChange={(e) => setGender(e.target.value)}
                  style={{
                    width: '100%',
                    background: C.surface,
                    border: `1px solid ${C.border}`,
                    borderRadius: 8,
                    padding: 10,
                    color: C.text,
                  }}
                >
                  <option value="Feminino">Feminino</option>
                  <option value="Masculino">Masculino</option>
                  <option value="Outro">Outro</option>
                </select>
              </div>
              <div style={{ flex: 1 }}>
                <label style={{ display: 'block', fontSize: 12, color: C.muted, marginBottom: 4 }}>
                  IDADE
                </label>
                <input
                  type="number"
                  value={age}
                  onChange={(e) => setAge(e.target.value)}
                  style={{
                    width: '100%',
                    background: C.surface,
                    border: `1px solid ${C.border}`,
                    borderRadius: 8,
                    padding: 10,
                    color: C.text,
                  }}
                />
              </div>
            </div>

            <div style={{ display: 'flex', gap: 10, marginBottom: 12 }}>
              <div style={{ flex: 1 }}>
                <label style={{ display: 'block', fontSize: 12, color: C.muted, marginBottom: 4 }}>
                  PESO (KG)
                </label>
                <input
                  type="number"
                  value={weight}
                  onChange={(e) => setWeight(e.target.value)}
                  style={{
                    width: '100%',
                    background: C.surface,
                    border: `1px solid ${C.border}`,
                    borderRadius: 8,
                    padding: 10,
                    color: C.text,
                  }}
                />
              </div>
              <div style={{ flex: 1 }}>
                <label style={{ display: 'block', fontSize: 12, color: C.muted, marginBottom: 4 }}>
                  ALTURA (CM)
                </label>
                <input
                  type="number"
                  value={height}
                  onChange={(e) => setHeight(e.target.value)}
                  style={{
                    width: '100%',
                    background: C.surface,
                    border: `1px solid ${C.border}`,
                    borderRadius: 8,
                    padding: 10,
                    color: C.text,
                  }}
                />
              </div>
            </div>

            <label style={{ display: 'block', fontSize: 12, color: C.muted, marginBottom: 4 }}>
              OBJETIVO PRINCIPAL
            </label>
            <select
              value={goal}
              onChange={(e) => setGoal(e.target.value)}
              style={{
                width: '100%',
                background: C.surface,
                border: `1px solid ${C.border}`,
