              }}
            >
              <option value="Ginásio Completo">Ginásio Comercial</option>
              <option value="Apenas Halteres">Home Gym (Halteres)</option>
              <option value="Peso Corporal">Calistenia (Sem Material)</option>
            </select>

            <label style={{ display: 'block', fontSize: 12, color: C.muted, marginBottom: 4 }}>
              DURAÇÃO IDEAL (MINUTOS)
            </label>
            <select
              value={duration}
              onChange={(e) => setDuration(Number(e.target.value))}
              style={{
                width: '100%',
                background: C.surface,
                border: `1px solid ${C.border}`,
                borderRadius: 8,
                padding: 10,
                color: C.text,
                marginBottom: 12,
              }}
            >
              <option value={30}>30 min (Expresso)</option>
              <option value={45}>45 min</option>
              <option value={60}>60 min</option>
              <option value={90}>90 min</option>
            </select>

            <label style={{ display: 'block', fontSize: 12, color: C.muted, marginBottom: 4 }}>
              LESÕES / LIMITAÇÕES (Separado por vírgula)
            </label>
            <input
              type="text"
              placeholder="ex: Joelhos, Lombar, etc"
              value={injuries}
              onChange={(e) => setInjuries(e.target.value)}
              style={{
                width: '100%',
                background: C.surface,
                border: `1px solid ${C.border}`,
                borderRadius: 8,
                padding: 10,
                color: C.text,
                marginBottom: 20,
              }}
            />

            <button
              onClick={handleSaveInfo}
              style={{
                width: '100%',
                background: C.accent,
                color: C.bg,
                border: 'none',
                borderRadius: 8,
                padding: 12,
                fontFamily: "'Bebas Neue'",
                fontSize: 18,
                letterSpacing: 1,
                cursor: 'pointer',
                marginBottom: 10,
              }}
            >
              CONTINUAR
            </button>
          </motion.div>
        )}

        {step === 'generate' && !plan && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            style={{ textAlign: 'center' }}
          >
            <p style={{ fontSize: 13, color: '#fff', marginBottom: 20 }}>
              A IA vai compilar um plano de {trainingDays.length} dias de treino, adaptado para{' '}
              {equipment}, focando em {duration} mins e salvaguardando o teu perfil biomecânico.
            </p>
            <button
              onClick={handleGenerate}
              disabled={isGenerating}
              style={{
                width: '100%',
                background: 'linear-gradient(135deg, #e8c84a, #e8a44a)',
                color: '#000',
                border: 'none',
                borderRadius: 8,
                padding: 12,
                fontFamily: "'Bebas Neue'",
                fontSize: 18,
                cursor: isGenerating ? 'wait' : 'pointer',
                opacity: isGenerating ? 0.7 : 1,
              }}
            >
              {isGenerating ? 'A COMPUTAR MOTOR DE ELITE...' : '✨ GERAR PLANO AGORA'}
            </button>
            <button
              onClick={() => setStep('info')}
              style={{
                width: '100%',
                background: 'none',
                border: 'none',
                color: C.muted,
                fontSize: 12,
                marginTop: 10,
                cursor: 'pointer',
                textDecoration: 'underline',
              }}
            >
              Voltar atrás e editar
            </button>
          </motion.div>
        )}

        {plan && (
          <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }}>
            <div
              style={{
                background: `${C.accent}22`,
                border: `1px solid ${C.accent}`,
                borderRadius: 8,
                padding: 12,
                marginBottom: 16,
              }}
            >
              <p style={{ fontSize: 12, color: '#fff', margin: 0, fontStyle: 'italic' }}>
                "{plan.reasoning}"
              </p>
            </div>

            <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
              {plan.workouts.map((day: any, i: number) => {
                const isRest =
                  day.focus.toLowerCase().includes('descanso') ||
                  day.focus.toLowerCase().includes('recupera');
                return (
                  <div
                    key={i}
                    style={{
                      background: C.surface,
                      border: `1px solid ${C.border}`,
                      borderRadius: 8,
                      padding: 12,
                    }}
                  >
                    <div
                      style={{
                        display: 'flex',
                        justifyContent: 'space-between',
                        alignItems: 'center',
                        marginBottom: 6,
                      }}
                    >
                      <span style={{ fontFamily: "'Bebas Neue'", fontSize: 16, color: C.accent }}>
                        {day.day}
                      </span>
                      <span
                        style={{
                          fontSize: 11,
                          color: C.text,
                          fontWeight: 'bold',
                          background: C.bg,
                          padding: '2px 8px',
                          borderRadius: 4,
                        }}
                      >
                        {day.focus}
                      </span>
                    </div>
                    <p
                      style={{
                        fontSize: 12,
                        color: C.muted,
                        margin: 0,
                        lineHeight: 1.4,
                        marginBottom: isRest ? 0 : 10,
                      }}
                    >
                      {day.exercises.join(' • ')}
                    </p>
                  </div>
                );
              })}
            </div>

            <button
              onClick={() => {
                alert('Plano Ativo no Dashboard!');
                onClose();
              }}
              style={{
                width: '100%',
                background: C.accent,
                color: '#000',
                border: `none`,
                borderRadius: 8,
                padding: 12,
                fontFamily: "'Bebas Neue'",
                fontSize: 18,
                cursor: 'pointer',
                marginTop: 20,
              }}
            >
              APLICAR E FECHAR
            </button>
          </motion.div>
        )}
      </div>
    </div>
  );
}

import { GradientButton } from '../ui/GradientButton';

export const WorkoutControls = ({ finish, doneSets, totalSets }: any) => {
  return (
    <div
      style={{
        position: 'fixed',
        bottom: 0,
        left: 0,
        right: 0,
        padding: '12px 18px',
        background: `linear-gradient(to top, #080b0f, transparent)`,
      }}
    >
      <GradientButton
        onClick={finish}
        variant="primary"
        style={{
          width: '100%',
          maxWidth: 480,
          display: 'flex',
          justifyContent: 'center',
          margin: '0 auto',
          padding: 14,
          fontSize: 18,
        }}
      >
        TERMINAR · {doneSets}/{totalSets} SÉRIES
      </GradientButton>
    </div>
  );
};

import { AnimatePresence, motion } from 'framer-motion';
import { GhostSetComparison } from '../GhostSetComparison';
import { ExerciseTutorialExt } from '../exercises/ExerciseTutorialExt';
import { VideoTutorial } from '../exercises/VideoTutorial';
import { GlassCard } from '../ui/GlassCard';
import { Tooltip } from '../ui/Tooltip';
import { WorkoutSetRow } from './WorkoutSetRow';

export const WorkoutExerciseList = ({
  localExs,
  sets,
  todayPlan,
  profile,
  history,
  theme,
  C,
  openIdx,
  setOpenIdx,
  getRecommendedReps,
  getHistoricalPR,
  getPrescription,
  checkAutoProgression,
  ME,
  speak,
  applyStrengthPreset,
  applyEndurancePreset,
  applyVolumePreset,
  addWarmups,
  upd,
  toggle,
  setCurrentExerciseIdx,
  setCurrentSetIdx,
  setShowPlateCalc,
  setStartTimes,
  setGhostPRs,
}: any) => {
  return (
    <>
      {localExs.map((ex: any, ei: number) => {
        const allDone = sets[ei].every((s: any) => s.done);
        const isOpen = openIdx === ei;
        const tr = getRecommendedReps(ex.name, ex.base?.hipertrofia?.[2] || 10);
        const pr = getHistoricalPR(ex.name);
        const prescription = getPrescription(profile, ex.name, pr);

        const handleOpen = () => {
          const nextState = isOpen ? -1 : ei;
          setOpenIdx(nextState);
          if (nextState !== -1) {
            const activeSetIdx = sets[ei].findIndex((s: any) => !s.done && !s.isWarmup);
            if (activeSetIdx !== -1) {
              const targetSet = sets[ei][activeSetIdx];
              speak({
                text: `${ex.name}. Série ${activeSetIdx + 1}, ${targetSet.weight} quilos. Mantém a forma.`,
                rate: 0.95,
                pitch: 1.05,
              });
            }
          }
        };

        return (
          <GlassCard
            key={ei}
            style={{
              marginBottom: 10,
              overflow: 'hidden',
              border: `1px solid ${allDone ? theme.success : theme.glassBorder}`,
              boxShadow: isOpen
                ? `0 8px 32px rgba(0,0,0,0.5), 0 0 0 1px ${theme.accent}40`
                : '0 4px 16px rgba(0,0,0,0.3)',
            }}
          >
            <div
              onClick={handleOpen}
              style={{
                width: '100%',
                background: 'none',
                border: 'none',
                padding: '16px',
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center',
                cursor: 'pointer',
              }}
            >
              <div style={{ textAlign: 'left' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: 9 }}>
                  <ExerciseTutorialExt exercise={ex} />
                  <span
                    style={{ color: allDone ? C.green : C.text, fontWeight: 600, fontSize: 14 }}
                  >
                    {ex.name}
                  </span>
                  {allDone && <span style={{ color: C.green, fontSize: 11 }}>✓</span>}
                </div>
                {checkAutoProgression(history, ex.name, 10) && (
                  <div
                    style={{
                      background: C.accentLow,
                      color: C.accent,
                      padding: '2px 6px',
                      borderRadius: 4,
                      fontSize: 9,
                      fontWeight: 'bold',
                      marginLeft: 8,
                      marginTop: 4,
                      display: 'inline-block',
                    }}
                  >
                    ⬆ +2.5kg sugerido
                  </div>
                )}
                {tr !== (ex.base?.hipertrofia?.[2] || 10) && (
                  <div
                    style={{
                      background: C.accent,
                      color: '#000',
                      padding: '2px 6px',
                      borderRadius: 4,
                      fontSize: 9,
                      fontWeight: 'bold',
                      marginLeft: 8,
                      marginTop: 4,
                      display: 'inline-block',
                    }}
                  >
                    🎯 {tr} reps recomendadas
                  </div>
                )}
                <div style={{ color: C.muted, fontSize: 11, marginTop: 4, marginLeft: 8 }}>
                  {ME[ex.muscle] || '🏋️'} {ex.muscle} · {sets[ei].filter((s: any) => s.done).length}/
                  {sets[ei].length} séries
                </div>
              </div>
              <motion.span
                animate={{ rotate: isOpen ? 180 : 0 }}
                style={{ color: theme.accent, fontSize: 14 }}
              >
                ▼
              </motion.span>
            </div>

            <AnimatePresence>
              {isOpen && (
                <motion.div
                  initial={{ height: 0, opacity: 0 }}
                  animate={{ height: 'auto', opacity: 1 }}
                  exit={{ height: 0, opacity: 0 }}
                  style={{ padding: '0 16px 16px' }}
                >
                  <VideoTutorial exerciseName={ex.name} muscle={ex.muscle} />

                  <div
                    style={{
                      marginTop: 8,
                      marginBottom: 12,
                      padding: 12,
                      borderRadius: 8,
                      background: '#0a0f15',
                      border: `1px solid #2a2f36`,
                    }}
                  >
                    <div
                      style={{
                        display: 'grid',
                        gridTemplateColumns: 'repeat(4, 1fr)',
                        gap: 8,
                        fontSize: 10,
                        color: theme.muted,
                        marginBottom: 8,
                      }}
                    >
                      <div>⚡ REPS</div>
                      <div>🏋️ KG SUG.</div>
                      <div>🎯 RPE</div>
                      <div>⏱️ DESC</div>
                    </div>
                    <div
                      style={{
                        display: 'grid',
                        gridTemplateColumns: 'repeat(4, 1fr)',
                        gap: 8,
                        fontSize: 14,
                        fontFamily: "'DM Mono'",
                      }}
                    >
                      <div style={{ color: theme.accent }}>{prescription.repsTarget}</div>
                      <div>
                        {prescription.suggestedWeight
                          ? `${prescription.suggestedWeight}kg`
                          : `${sets[ei].find((s: any) => !s.isWarmup)?.weight || 20}kg`}
                        <div
                          style={{
                            fontSize: 8,
                            color: theme.muted,
                            marginTop: 2,
                            whiteSpace: 'nowrap',
                          }}
                        >
                          ✅{' '}
                          {profile?.goal === 'forca'
                            ? 'Para força'
                            : profile?.goal === 'hipertrofia'
                              ? 'Para hipertrofia'
                              : 'Baseado no teu nível'}
                        </div>
                      </div>
                      <div style={{ color: theme.danger }}>{prescription.rpeTarget}/10</div>
                      <div>{prescription.restSeconds}s</div>
                    </div>
                    {prescription.warmupSets.length > 0 && (
                      <div style={{ marginTop: 8, fontSize: 10, color: theme.muted }}>
                        🔥 Aquecimento:{' '}
                        {prescription.warmupSets
                          .map((w: any) => `${w.weightPercent * 100}% × ${w.reps}`)
                          .join(' → ')}
                      </div>
                    )}
                    <div
                      style={{
                        marginTop: 8,
                        fontSize: 10,
                        color: theme.muted,
                        display: 'flex',
                        justifyContent: 'space-between',
                      }}
                    >
                      <span>⚡ RPE = Taxa de Esforço Percebida (1=fácil, 10=falha)</span>
                    </div>
                    {prescription.explanation && (
                      <div
                        style={{
                          marginTop: 10,
                          padding: '8px 10px',
                          background: 'rgba(255,255,255,0.03)',
                          borderLeft: `3px solid ${theme.accent}`,
                          borderRadius: 4,
                          fontSize: 11,
                          color: '#e2e8f0',
                          lineHeight: 1.4,
                        }}
                      >
                        {prescription.explanation}
                      </div>
                    )}
                    <div style={{ display: 'flex', gap: 6, marginTop: 12 }}>
                      <button
                        onClick={() => applyStrengthPreset(ei)}
                        style={{
                          flex: 1,
                          background: 'rgba(255,255,255,0.05)',
                          border: `1px solid ${C.accent}4d`,
                          borderRadius: 6,
                          padding: '6px 2px',
                          color: C.accent,
                          fontSize: 9,
                          fontWeight: 'bold',
                          cursor: 'pointer',
                          transition: '0.2s',
                        }}
                      >
                        ⚡ FORÇA
                      </button>
                      <button
                        onClick={() => applyEndurancePreset(ei)}
                        style={{
                          flex: 1,
                          background: 'rgba(255,255,255,0.05)',
                          border: `1px solid #38bdf84d`,
                          borderRadius: 6,
                          padding: '6px 2px',
                          color: '#38bdf8',
                          fontSize: 9,
                          fontWeight: 'bold',
                          cursor: 'pointer',
                          transition: '0.2s',
                        }}
                      >
                        💧 RESISTÊNCIA
                      </button>
                      <button
                        onClick={() => applyVolumePreset(ei)}
                        style={{
                          flex: 1,
                          background: 'rgba(255,255,255,0.05)',
                          border: `1px solid ${C.green}4d`,
                          borderRadius: 6,
                          padding: '6px 2px',
                          color: C.green,
                          fontSize: 9,
                          fontWeight: 'bold',
                          cursor: 'pointer',
                          transition: '0.2s',
                        }}
                      >
                        📈 VOLUME
                      </button>
                    </div>
                    <p
                      style={{ fontSize: 9, color: theme.muted, textAlign: 'center', marginTop: 8 }}
                    >
                      Podes ajustar livremente as séries em baixo se quiseres.
                    </p>
                  </div>

                  <div
                    style={{
                      display: 'flex',
                      justifyContent: 'space-between',
                      alignItems: 'flex-end',
                      marginBottom: 7,
                    }}
                  >
                    <div
                      style={{
                        display: 'grid',
                        gridTemplateColumns: '26px 1fr 1fr 1fr 38px',
                        gap: 8,
                        flex: 1,
                      }}
                    >
                      {(() => {
                        const isCardio = ex.type === 'cardio' || ex.type === 'distance';
                        const isBodyweight = ex.type === 'bodyweight';
                        const isTimed = ex.type === 'timed' || ex.type === 'mobility';
                        const head1 = isCardio
                          ? 'KM'
                          : isTimed
                            ? '-'
                            : isBodyweight
                              ? '+KG'
                              : todayPlan.type === 'hiit' || todayPlan.type === 'functional'
                                ? 'CARGA'
                                : 'KG';
                        const head2 = isCardio
                          ? 'MIN'
                          : isTimed
                            ? 'SEGS'
                            : todayPlan.type === 'hiit' || todayPlan.type === 'functional'
                              ? 'TEMPO/REP'
                              : 'REPS';
                        return ['#', head1, head2, 'INTENS.', ''].map((h, i) => (
                          <div
                            key={i}
                            style={{
                              color: theme.muted,
                              fontSize: 9,
                              fontFamily: "'DM Mono'",
                              textAlign: i > 0 && i < 4 ? 'center' : 'left',
                              display: 'flex',
                              justifyContent: i > 0 && i < 4 ? 'center' : 'flex-start',
                            }}
                          >
                            {i === 3 ? (
                              <Tooltip text="RPE (Taxa de Esforço Percebido). RPE 8 significa que terminaste a série sentindo que conseguirias fazer apenas mais 2 repetições antes da falha.">
                                <span>{h}</span>
                              </Tooltip>
                            ) : (
                              h
                            )}
                          </div>
                        ));
                      })()}
                    </div>
                    <button
                      onClick={() => addWarmups(ei)}
                      style={{
                        background: C.accentLow,
                        color: C.accent,
                        border: `1px solid ${C.accent}`,
                        borderRadius: 6,
                        fontSize: 10,
                        padding: '4px 8px',
                        cursor: 'pointer',
                        whiteSpace: 'nowrap',
                        marginLeft: 12,
                      }}
                    >
                      + AQUECIMENTO
                    </button>
                  </div>
                  {/* Ghost Mode: Show last set comparison */}
                  <GhostSetComparison
                    exerciseName={localExs[ei].name}
                    currentSets={sets[ei]}
                    history={history}
                    theme={theme}
                    onPRDetected={(isPR: boolean) =>
                      setGhostPRs((prev: any) => ({ ...prev, [localExs[ei].name]: isPR }))
                    }
                  />
                  {sets[ei].map((s: any, si: number) => (
                    <WorkoutSetRow
                      key={si}
                      s={s}
                      ei={ei}
                      si={si}
                      theme={theme}
                      C={C}
                      upd={upd}
                      toggle={toggle}
                      setCurrentExerciseIdx={setCurrentExerciseIdx}
                      setCurrentSetIdx={setCurrentSetIdx}
                      setShowPlateCalc={setShowPlateCalc}
                      profile={profile}
                      setStartTimes={setStartTimes}
                      tr={tr}
                      equipment={ex.equipment}
                    />
                  ))}
                </motion.div>
              )}
            </AnimatePresence>
          </GlassCard>
        );
      })}
    </>
  );
};

import { motion } from 'framer-motion';

export const WorkoutHeader = ({
  theme,
  C,
  todayPlan,
  elapsed,
  fmt,
  ftms,
  btStatus,
  btConnect,
  bpm,
  doneSets,
  totalSets,
  setShowShareModal,
  setShowTimer,
  setConfirmCancel,
}: any) => {
  return (
    <div
      style={{
        background: 'rgba(8, 11, 15, 0.8)',
        backdropFilter: 'blur(12px)',
        borderBottom: `1px solid ${theme.glassBorder}`,
        padding: '12px 18px',
        position: 'sticky',
        top: 0,
        zIndex: 10,
      }}
    >
      <div
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          maxWidth: 480,
          margin: '0 auto',
        }}
      >
        <div>
          <p style={{ fontFamily: "'Bebas Neue'", fontSize: 11, letterSpacing: 3, color: C.muted }}>
            {todayPlan?.label?.toUpperCase()}
          </p>
          <motion.p
            style={{
              fontFamily: "'DM Mono'",
              fontSize: 17,
              color: C.accent,
              fontVariantNumeric: 'tabular-nums',
            }}
          >
            {fmt(elapsed)}
          </motion.p>
        </div>
        <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
          {ftms?.isConnected && ftms?.machineData && (
            <div
              style={{
                display: 'flex',
                alignItems: 'center',
                background: C.card,
                border: `1px solid ${C.green}`,
                borderRadius: 7,
                padding: '0 6px',
                color: C.green,
                fontSize: 10,
                fontWeight: 'bold',
                height: 32,
              }}
            >
              ⚡ {ftms.machineData.instantSpeed?.toFixed(1) || 0}km/h
            </div>
          )}
          {btStatus !== 'CONNECTED' ? (
            <button
              onClick={btConnect}
              style={{
                background: 'transparent',
                border: `1px solid ${C.blue}`,
                borderRadius: 7,
                padding: '6px',
                color: C.blue,
                fontSize: 11,
                cursor: 'pointer',
                fontFamily: "'Bebas Neue'",
              }}
            >
              {btStatus === 'CONNECTING' ? '...' : '+ HR'}
            </button>
          ) : (
            <div
              style={{
                position: 'relative',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                width: 32,
                height: 32,
                borderRadius: '50%',
                background: bpm > 171 ? C.red : C.card,
                border: `2px solid ${bpm > 171 ? C.red : C.accent}`,
                color: bpm > 171 ? '#FFF' : C.accent,
                fontSize: 11,
                fontWeight: 'bold',
              }}
            >
              {bpm > 0 ? bpm : '--'}
            </div>
          )}
          <span style={{ fontFamily: "'DM Mono'", fontSize: 11, color: C.muted }}>
            {doneSets}/{totalSets}
          </span>
          <button
            onClick={() => setShowShareModal(true)}
            style={{
              background: C.card,
              border: `1px solid ${C.blue}`,
              borderRadius: 7,
              padding: '6px 9px',
              color: C.blue,
              fontSize: 11,
              cursor: 'pointer',
              fontWeight: 'bold',
            }}
          >
            🖧 P2P
          </button>
          <button
            onClick={() => setShowTimer(true)}
            style={{
              background: C.card,
              border: `1px solid ${C.accent}`,
              borderRadius: 7,
              padding: '6px 11px',
              color: C.accent,
              fontSize: 15,
              cursor: 'pointer',
            }}
          >
            ⏱
          </button>
          <button
            onClick={() => setConfirmCancel(true)}
            style={{
              background: C.card,
              border: `1px solid ${C.border}`,
              borderRadius: 7,
              padding: '6px 11px',
              color: C.muted,
              fontSize: 13,
              cursor: 'pointer',
            }}
          >
            ✕
          </button>
        </div>
      </div>
      <div
        style={{
          maxWidth: 480,
          margin: '9px auto 0',
          background: C.dim,
          borderRadius: 2,
          height: 3,
        }}
      >
        <div
          style={{
            width: `${(doneSets / totalSets) * 100 || 0}%`,
            height: '100%',
            background: C.accent,
            borderRadius: 2,
            transition: 'width 0.4s',
          }}
        />
      </div>
    </div>
  );
};

