  const expected = [
    'workouts',
    'setLogs',
    'personalRecords',
    'recoveryMetrics',
    'meals',
    'hydration',
    'weightHistory',
  ];
  const missing = expected.filter((s: string) => !db.objectStoreNames.contains(s as any));
  return {
    healthy: missing.length === 0,
    currentVersion: db.version,
    expectedVersion: CURRENT_DB_VERSION,
    missingStores: missing,
  };
}

