import type { HeartRateData } from '../hooks/useBluetoothHRM';

export type BluetoothState =
  | 'IDLE'
  | 'SCANNING'
  | 'CONNECTING'
  | 'CONNECTED'
  | 'RECONNECTING'
  | 'ERROR';

export interface BluetoothContext {
  device: any | null;
  heartRate: HeartRateData | null;
  reconnectAttempts: number;
  errorMsg: string;
}

export type BluetoothEvent =
  | { type: 'START_SCAN' }
  | { type: 'DEVICE_FOUND'; device: any }
  | { type: 'CONNECTION_SUCCESS' }
  | { type: 'HEART_RATE_UPDATE'; data: HeartRateData }
  | { type: 'DISCONNECT' }
  | { type: 'CONNECTION_LOST' }
  | { type: 'MAX_RECONNECTS_REACHED' }
  | { type: 'ERROR'; message: string };

export function bluetoothReducer(
  state: { value: BluetoothState; context: BluetoothContext },
  event: BluetoothEvent,
): { value: BluetoothState; context: BluetoothContext } {
  const { value, context } = state;

  switch (value) {
    case 'IDLE':
      if (event.type === 'START_SCAN')
        return { value: 'SCANNING', context: { ...context, errorMsg: '' } };
      break;

    case 'SCANNING':
      if (event.type === 'DEVICE_FOUND')
        return { value: 'CONNECTING', context: { ...context, device: event.device } };
      if (event.type === 'ERROR')
        return { value: 'ERROR', context: { ...context, errorMsg: event.message } };
      if (event.type === 'DISCONNECT')
        return { value: 'IDLE', context: { ...context, device: null } };
      break;

    case 'CONNECTING':
      if (event.type === 'CONNECTION_SUCCESS')
        return { value: 'CONNECTED', context: { ...context, reconnectAttempts: 0, errorMsg: '' } };
      if (event.type === 'CONNECTION_LOST')
        return {
          value: 'RECONNECTING',
          context: { ...context, reconnectAttempts: context.reconnectAttempts + 1 },
        };
      if (event.type === 'ERROR')
        return { value: 'ERROR', context: { ...context, errorMsg: event.message } };
      if (event.type === 'DISCONNECT')
        return { value: 'IDLE', context: { ...context, device: null } };
      break;

    case 'CONNECTED':
      if (event.type === 'HEART_RATE_UPDATE')
        return { value: 'CONNECTED', context: { ...context, heartRate: event.data } };
      if (event.type === 'CONNECTION_LOST')
        return {
          value: 'RECONNECTING',
          context: { ...context, reconnectAttempts: context.reconnectAttempts + 1 },
        };
      if (event.type === 'DISCONNECT')
        return {
          value: 'IDLE',
          context: { ...context, device: null, heartRate: null, reconnectAttempts: 0 },
        };
      break;

    case 'RECONNECTING':
      if (event.type === 'CONNECTION_SUCCESS')
        return { value: 'CONNECTED', context: { ...context, reconnectAttempts: 0, errorMsg: '' } };
      if (event.type === 'MAX_RECONNECTS_REACHED')
        return {
          value: 'IDLE',
          context: {
            ...context,
            device: null,
            heartRate: null,
            reconnectAttempts: 0,
            errorMsg: 'Falha ao reconectar.',
          },
        };
      if (event.type === 'CONNECTION_LOST')
        return {
          value: 'RECONNECTING',
          context: { ...context, reconnectAttempts: context.reconnectAttempts + 1 },
        };
      if (event.type === 'DISCONNECT')
        return {
          value: 'IDLE',
          context: { ...context, device: null, heartRate: null, reconnectAttempts: 0 },
        };
      break;

    case 'ERROR':
      if (event.type === 'START_SCAN')
        return { value: 'SCANNING', context: { ...context, errorMsg: '' } };
      if (event.type === 'DISCONNECT')
        return { value: 'IDLE', context: { ...context, device: null, errorMsg: '' } };
      break;
  }

  return state; // No transition
}

import { webcrypto } from 'crypto';
import { Ratelimit } from '@upstash/ratelimit';
import { Redis } from '@upstash/redis';
import type { VercelRequest, VercelResponse } from '@vercel/node';

// Conexão ao Upstash
const redis = new Redis({
  url: process.env.UPSTASH_REDIS_REST_URL || '',
  token: process.env.UPSTASH_REDIS_REST_TOKEN || '',
});

// Algoritmo Sliding Window: 10 requests a cada 60 segundos
const ratelimit = new Ratelimit({
  redis: redis,
  limiter: Ratelimit.slidingWindow(10, '60 s'),
  analytics: true,
});

export const aiRateLimiter = async (req: VercelRequest, res: VercelResponse): Promise<boolean> => {
  try {
    const ip = req.headers['x-forwarded-for'] || req.socket?.remoteAddress || '127.0.0.1';
    const identifier = Array.isArray(ip) ? ip[0] : ip;

    const { success, limit, remaining, reset } = await ratelimit.limit(`ai_limit_${identifier}`);

    res.setHeader('X-RateLimit-Limit', limit);
    res.setHeader('X-RateLimit-Remaining', remaining);
    res.setHeader('X-RateLimit-Reset', reset);

    if (!success) {
      console.warn(`[Upstash] Bloqueio tático ativado. IP: ${identifier} excedeu a quota.`);
      res.status(429).json({
        error: 'Demasiados pedidos. Descansa 1 minuto e tenta novamente.',
      });
      return false;
    }

    return true;
  } catch (error) {
    console.error('[Upstash] Falha no Rate Limiter, a permitir tráfego por precaução:', error);
    return true; // Se o Redis falhar, não quebramos a app inteira
  }
};

// ─── JWT VERIFICATION ─────────────────────────────────────────────
function base64UrlDecode(str: string): Buffer {
  str = str.replace(/-/g, '+').replace(/_/g, '/');
  while (str.length % 4) str += '=';
  return Buffer.from(str, 'base64');
}

export async function verifyJWT(token: string) {
  const JWT_SHARED_SECRET = process.env.JWT_SHARED_SECRET;
  if (!JWT_SHARED_SECRET) {
    console.error('[CRITICAL] JWT_SHARED_SECRET ausente nas variáveis de ambiente!');
    return { valid: false, error: 'Erro interno de configuração de segurança.' };
  }

  try {
    const parts = token.split('.');
    if (parts.length !== 3) {
      return { valid: false, error: 'Token JWT malformado' };
    }

    const headerB64 = parts[0] as string;
    const payloadB64 = parts[1] as string;
    const signatureB64 = parts[2] as string;
    const key = await webcrypto.subtle.importKey(
      'raw',
      new TextEncoder().encode(JWT_SHARED_SECRET),
      { name: 'HMAC', hash: 'SHA-256' },
      false,
      ['verify'],
    );

    const signingInput = `${headerB64}.${payloadB64}`;
    const signature = base64UrlDecode(signatureB64);
    const isValid = await webcrypto.subtle.verify(
      'HMAC',
      key,
      signature,
      new TextEncoder().encode(signingInput),
    );

    if (!isValid) {
      return { valid: false, error: 'Assinatura JWT inválida' };
    }

    const payload = JSON.parse(base64UrlDecode(payloadB64).toString('utf-8'));

    // Validar expiração
    if (payload.exp && Date.now() >= payload.exp * 1000) {
      return { valid: false, error: 'Token expirado' };
    }

    // Proteger contra Replay Attacks com Upstash Redis (Nonces)
    if (payload.nonce) {
      const isNew = await redis.set(`nonce_${payload.nonce}`, '1', { ex: 300, nx: true });
      if (!isNew) {
        return { valid: false, error: 'Replay attack detetado (Nonce reutilizado)' };
      }
    }

    return { valid: true, payload };
  } catch (e: any) {
    return { valid: false, error: e.message || 'Erro na verificação JWT' };
  }
}

export async function protectApi(req: VercelRequest, res: VercelResponse): Promise<boolean> {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ error: 'Acesso negado. Token ausente.' });
    return false;
  }

  const token = authHeader.split(' ')[1];
  if (!token) {
    res.status(401).json({ error: 'Acesso negado. Token mal formatado.' });
    return false;
  }
  const { valid, error } = await verifyJWT(token);

  if (!valid) {
    res.status(403).json({ error: `Acesso bloqueado: ${error}` });
    return false;
  }

  return true;
}

import type React from 'react';
import { lazy } from 'react';
import { PageTransition } from '../components/ui/MotionComponents';
import type { WorkoutSession } from '../db/schema';
import type { ViewName } from '../hooks/useFitnessData';
import type { UserProfile, WorkoutPlan } from '../types';


import { BeginnerGuide } from '../components/onboarding/BeginnerGuide';
import { FitnessAssessment } from '../components/onboarding/FitnessAssessment';
import { ProactiveMessageList } from '../components/ai/ProactiveMessage';

// Lazy loaded components
const Dashboard = lazy(() => import('../screens/Dashboard'));
const ActiveWorkout = lazy(() => import('../screens/ActiveWorkout'));
const Settings = lazy(() => import('../screens/Settings'));
const AICoach = lazy(() => import('../screens/AICoach'));
const Trends = lazy(() => import('../screens/Trends'));
const GymVibe = lazy(() => import('../screens/GymVibe'));
const Milestones = lazy(() => import('../screens/Milestones'));
const CycleReview = lazy(() =>
  import('../screens/CycleReview').then((m) => ({ default: m.CycleReview })),
);
const BackupScreen = lazy(() => import('../screens/BackupScreen'));
const DeviceManager = lazy(() =>
  import('../screens/DeviceManager').then((m) => ({ default: m.DeviceManager })),
);
const WalkingCoachScreen = lazy(() => import('../screens/WalkingCoachScreen'));
const DetailedHistory = lazy(() =>
  import('../components/history/DetailedHistory').then((m) => ({ default: m.DetailedHistory })),
);
const Planner = lazy(() => import('../screens/Planner').then((m) => ({ default: m.Planner })));
const NutritionPlanner = lazy(() => import('../screens/NutritionPlanner'));
const RewardsStore = lazy(() =>
  import('../screens/RewardsStore').then((m) => ({ default: m.RewardsStore })),
);
const CommunityFeed = lazy(() => import('../screens/CommunityFeed'));
const CompeteScreen = lazy(() => import('../screens/CompeteScreen'));
const RecoveryScreen = lazy(() => import('../screens/RecoveryScreen'));
const PostWorkoutFeedback = lazy(() =>
  import('../components/workout/PostWorkoutFeedback').then((m) => ({ default: m.PostWorkoutFeedback })),
);

export interface ViewConfigProps {
  view: ViewName;
  profile: UserProfile;
  setProfile: (p: UserProfile) => void;
  history: WorkoutSession[];
  setView: (v: ViewName) => void;
  handleStartWorkout: (plan: WorkoutPlan | string) => void;
  handleFinishWorkout: (data: WorkoutSession) => void;
  handleFeedbackSubmit: (feedback: { difficulty: string; notes?: string }) => Promise<void>;
  handleInstantSave: (data: WorkoutSession) => Promise<void>;
  handleReset: () => void;
  handleUnlock: (key: CryptoKey) => void;
  workoutData: WorkoutSession | null;
  currentPlan: WorkoutPlan | string | null;
}

/** Build the NutritionPlanner view with required props */
export function buildNutritionView(
  _profile: UserProfile,
  _setProfile: (p: UserProfile) => void,
): React.ReactNode {
  return (
    <NutritionPlanner />
  );
}

/** Create the view configuration map from hook state and handlers */
export function createViewConfigs(props: ViewConfigProps): Record<string, React.ReactNode> {
  const {
    profile,
    setProfile,
    history,
    setView,
    handleStartWorkout,
    handleFinishWorkout,
    handleFeedbackSubmit,
    handleInstantSave,
    handleReset,
    workoutData,
    currentPlan,
  } = props;

  return {
    dashboard: (
      <PageTransition viewKey="dash">
        <Dashboard
          history={history}
          onStartWorkout={handleStartWorkout}
        />
      </PageTransition>
    ),
    workout: currentPlan ? (
      <PageTransition viewKey="work">
        <ActiveWorkout
          todayPlan={currentPlan}
          history={history}
          profile={profile}
          onFinish={handleFinishWorkout}
          onCancel={() => setView('dashboard')}
        />
      </PageTransition>
    ) : null,
    settings: (
      <PageTransition viewKey="set">
        <Settings profile={profile} setProfile={setProfile} onReset={handleReset} />
      </PageTransition>
    ),
    assessment: (
      <PageTransition viewKey="asses">
        <FitnessAssessment
          onComplete={(data: Partial<UserProfile>) => {
            setProfile({ ...profile, ...data } as UserProfile);
            setView('dashboard');
          }}
        />
      </PageTransition>
    ),
    guide: (
      <PageTransition viewKey="gui">
        <BeginnerGuide onComplete={() => setView('dashboard')} />
      </PageTransition>
    ),
    history: (
      <PageTransition viewKey="hist">
        <DetailedHistory workouts={history} profile={profile} onStartWorkout={handleStartWorkout} />
      </PageTransition>
    ),
    feedback: (
      <PageTransition viewKey="feed">
        <PostWorkoutFeedback
          onSubmit={handleFeedbackSubmit}
          profile={profile}
          workoutData={workoutData}
        />
      </PageTransition>
    ),
    aicoach: (
      <PageTransition viewKey="aicoach">
        <AICoach history={history} profile={profile} />
      </PageTransition>
    ),
    trends: (
      <PageTransition viewKey="trends">
        <Trends history={history} />
      </PageTransition>
    ),
    planner: (
      <PageTransition viewKey="planner">
        <Planner onStartWorkout={handleStartWorkout} />
      </PageTransition>
    ),
    gymvibe: (
      <PageTransition viewKey="gymvibe">
        <GymVibe profile={profile} />
      </PageTransition>
    ),
    milestones: (
      <PageTransition viewKey="milestones">
        <Milestones history={history} />
      </PageTransition>
    ),
    cyclereview: (
      <PageTransition viewKey="cyclereview">
        <CycleReview
          history={history}
          onClose={() => setView('dashboard')}
          onGenerateNewPlan={() => {
            setView('dashboard');
            window.dispatchEvent(new CustomEvent('OPEN_WEEKLY_PLAN'));
          }}
        />
      </PageTransition>
    ),
    nutrition: (
      <PageTransition viewKey="nutrition">{buildNutritionView(profile, setProfile)}</PageTransition>
    ),
    devices: (
      <PageTransition viewKey="devices">
        <DeviceManager />
      </PageTransition>
    ),
    rewards: (
      <PageTransition viewKey="rewards">
        <RewardsStore onClose={() => setView('dashboard')} />
      </PageTransition>
    ),
    backup: (
      <PageTransition viewKey="backup">
        <BackupScreen />
      </PageTransition>
    ),
    walkingcoach: (
      <PageTransition viewKey="walkingcoach">
        <WalkingCoachScreen onClose={() => setView('dashboard')} onFinish={handleInstantSave} />
      </PageTransition>
    ),
    community: (
      <PageTransition viewKey="community">
        <CommunityFeed profile={profile} />
      </PageTransition>
    ),
    compete: (
      <PageTransition viewKey="compete">
        <CompeteScreen />
      </PageTransition>
    ),
    recovery: (
      <PageTransition viewKey="recovery">
        <RecoveryScreen />
      </PageTransition>
    ),
    coach: (
      <PageTransition viewKey="coach">
        <ProactiveMessageList />
      </PageTransition>
    ),
  };
}

import { motion } from 'framer-motion';
import { useEffect, useRef, useState } from 'react';
import { C } from '../data/constants';
import { useLS } from '../hooks';
import { AnthropicService } from '../services/anthropicService';
import { NeuralFatigue } from '../services/neuralFatigue';
import { useMilestonesStore } from '../stores/useMilestonesStore';
import { sanitizeText } from '../utils/sanitize';

export default function AICoach({ history, profile }: any) {
  const [messages, setMessages] = useLS<any[]>('coach_chat', [
    {
      role: 'assistant',
      text: 'Eu sou a Inteligência Tática Fittrack (Motor Claude). Partilha as tuas dores ou pede re-periodização baseada no teu histórico.',
    },
  ]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || loading) return;

    const userMsg = sanitizeText(input.trim());
    setInput('');

    const newMsgs = [...messages, { role: 'user', text: userMsg }];
    setMessages(newMsgs);
    setLoading(true);

    const responseText = await AnthropicService.askCoach(userMsg, history);

    setMessages([...newMsgs, { role: 'assistant', text: responseText }]);
    setLoading(false);
  };

  const handleExportPrompt = () => {
    const lastWorkouts = history
      .slice(-5)
      .map((w: any) => `${w.dayLabel}`)
      .join(', ');
    const totalVolume = history.slice(-7).reduce((a: any, w: any) => a + (w.totalVolume || 0), 0);
    const readiness = NeuralFatigue.calculateReadiness(history);
    const prs = useMilestonesStore.getState().prs || {};
    const prText = Object.entries(prs)
      .map(([k, v]) => `${k} = ${v}kg`)
      .join(', ');

    const promptText = `Sou utilizador do FitTrack V7. Os meus dados:

- Género: ${profile?.gender || 'Não especificado'}
- Idade: ${profile?.age || 25}
- Objetivo: ${profile?.goal || 'Hipertrofia'}
- Nível: ${profile?.level || 'Iniciante'}
- Filosofia de Treino: ${profile?.philosophy || 'Clássico'}
- Últimos treinos: ${lastWorkouts || 'Nenhum'}
- Volume acumulado recente: ${totalVolume}kg
- Readiness Score (fadiga neural): ${readiness.score} (${readiness.label})

Os meus PRs: ${prText || 'Nenhum registado'}.

Com base nestes dados, recomenda-me:
- Devo aumentar carga em algum exercício?
- Preciso de um deload?
- Qual a melhor periodização para as próximas 4 semanas?

(Responde em markdown, com justificação científica.)`;

    navigator.clipboard.writeText(promptText);
    alert('Prompt copiado para a área de transferência! Cola no ChatGPT, Claude ou Gemini.');
  };

  return (
    <div
      style={{
        padding: '18px',
        maxWidth: 480,
        margin: '0 auto',
        height: 'calc(100vh - 80px)',
        display: 'flex',
        flexDirection: 'column',
      }}
    >
      <div
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'flex-start',
          marginBottom: 16,
        }}
      >
        <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
          <span style={{ fontSize: 30 }}>🧠</span>
          <div>
            <h2
              style={{
                fontFamily: "'Bebas Neue'",
                fontSize: 24,
                letterSpacing: 2,
                margin: 0,
                color: C.accent,
              }}
            >
              NEURAL COACH
            </h2>
            <p style={{ fontSize: 10, color: C.muted, margin: 0 }}>
              INTEGRAÇÃO CLAUDE DE ANÁLISE DE HISTÓRICO
            </p>
          </div>
        </div>
        <button
          onClick={handleExportPrompt}
          style={{
            background: C.card,
            color: '#fff',
            border: `1px solid ${C.border}`,
            borderRadius: 8,
            padding: '6px 12px',
            fontSize: 12,
            cursor: 'pointer',
            display: 'flex',
            alignItems: 'center',
            gap: 6,
          }}
        >
          📋 Exportar Prompt
        </button>
      </div>

      {/* API Key agora gerida no servidor BFF — sem necessidade de configuração no cliente */}

      <div
        ref={scrollRef}
        style={{
          flex: 1,
          overflowY: 'auto',
          display: 'flex',
          flexDirection: 'column',
          gap: 12,
          paddingBottom: 20,
        }}
      >
        {messages.map((m, i) => (
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            key={i}
            style={{ alignSelf: m.role === 'user' ? 'flex-end' : 'flex-start', maxWidth: '85%' }}
          >
            <div
              style={{
                background: m.role === 'user' ? C.accent : C.card,
                color: m.role === 'user' ? '#000' : C.text,
                padding: '12px 16px',
                borderRadius: 16,
                borderBottomRightRadius: m.role === 'user' ? 4 : 16,
                borderBottomLeftRadius: m.role === 'assistant' ? 4 : 16,
                fontSize: 14,
                border: m.role === 'assistant' ? `1px solid ${C.border}` : 'none',
                lineHeight: 1.4,
              }}
            >
              {m.text}
            </div>
          </motion.div>
        ))}
        {loading && (
          <div
            style={{
              alignSelf: 'flex-start',
              background: C.card,
              padding: '12px 16px',
              borderRadius: 16,
              borderBottomLeftRadius: 4,
              color: C.accent,
            }}
          >
            <span style={{ fontFamily: "'DM Mono'" }}>Processando telemetria...</span>
          </div>
        )}
      </div>

      <div style={{ display: 'flex', gap: 8 }}>
        <input
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && handleSend()}
          placeholder="Quais exercícios deves trocar?"
          style={{
            flex: 1,
            background: C.surface,
            border: `1px solid ${C.border}`,
            borderRadius: 24,
            padding: '0 16px',
            color: C.text,
            fontSize: 14,
          }}
        />
        <button
          onClick={handleSend}
          disabled={loading}
          style={{
            background: C.accent,
            color: '#000',
            border: 'none',
            width: 44,
            height: 44,
            borderRadius: 22,
            cursor: 'pointer',
            display: 'flex',
            justifyContent: 'center',
            alignItems: 'center',
            opacity: loading ? 0.5 : 1,
          }}
        >
          ➤
        </button>
      </div>
    </div>
  );
}

