// ── HOOK PRINCIPAL ─────────────────────────────────────────────────────────

export default function ActiveWorkout({
  todayPlan,
  profile,
  history,
  onFinish,
  onCancel,
}: ActiveWorkoutProps) {
  const { exercises: EXERCISE_DB, fetchExercises } = useExerciseStore();
  useEffect(() => {
    fetchExercises();
  }, [fetchExercises]);

  // Estado principal
  const [localExs, setLocalExs] = useState<LocalExercise[]>(() =>
    todayPlan.exercises.map((n: string) => ({
      name: n,
      muscle: 'Treino',
      ...(EXERCISE_DB[n] || {}),
    })),
  );
  const [sets, setSets] = useState<SetArray>(() => initSets(localExs, profile, todayPlan, history));
  const [openIdx, setOpenIdx] = useState(0);
  const [elapsed, setElapsed] = useState(0);
  const [confirmCancel, setConfirmCancel] = useState(false);
  const [showTimer, setShowTimer] = useState(false);
  const [showLibrary, setShowLibrary] = useState(false);
  const [showPlateCalc, setShowPlateCalc] = useState(false);
  const [showShareModal, setShowShareModal] = useState(false);
  const [showRivalResult, setShowRivalResult] = useState(false);
  const [showConfetti, setShowConfetti] = useState(false);
  const [finalVolume, setFinalVolume] = useState(0);
  const [showRiskPanel, setShowRiskPanel] = useState(true);
  const [riskReport, setRiskReport] = useState<InjuryRiskReport | null>(null);
  const { generateReport } = useInjuryStore();
  const proactiveMessages = useProactiveCoachStore((s) => s.getActiveMessages());
  const injuryMsgs = proactiveMessages.filter(
    (m) => m.trigger === 'injury_risk_high' || m.trigger === 'injury_risk_critical',
  );
  const [newPRData, setNewPRData] = useState<{ exerciseName: string; weight: number } | null>(null);
  const [autoregulationMessage, setAutoregulationMessage] = useState<{
    text: string;
    type: string;
  } | null>(null);
  const [autoRepActive, setAutoRepActive] = useState(false);
  const [currentExerciseIdx, setCurrentExerciseIdx] = useState(0);
  const [currentSetIdx, setCurrentSetIdx] = useState(0);
  const [setStartTimes, setSetStartTimes] = useState<Record<string, number>>({});
  const [_ghostPRs, setGhostPRs] = useState<Record<string, boolean>>({});
  const [rivalState] = useState(() => RivalAI.findRival(history, todayPlan.label));
  const [isCircuit] = useState(todayPlan.type === 'circuit');
  const [currentRound, setCurrentRound] = useState(1);
  const [roundRestRemaining, setRoundRestRemaining] = useState<number | null>(null);
  const [roundExercisesCompleted, setRoundExercisesCompleted] = useState<string[]>([]);

  // Modos de treino
  const [workoutMode, setWorkoutMode] = useState<WorkoutMode>('classic');
  const [amrapDuration] = useState(15 * 60);
  const [amrapTimeLeft, setAmrapTimeLeft] = useState(15 * 60);
  const [amrapRunning, setAmrapRunning] = useState(false);
  const [roundsCompleted, setRoundsCompleted] = useState(0);
  const [emomRemainingSeconds, setEmomRemainingSeconds] = useState(60);
  const [emomRound, setEmomRound] = useState(1);
  const [emomRunning, setEmomRunning] = useState(false);

  const workoutIdRef = useRef<string>(generateId());
  const { beep } = useBeep();
  const hrm = useBluetoothHRM();
  const { bpm, status: btStatus, connect: btConnect } = hrm;
  const ftms = useFitnessMachine();
  const { autoSync: _autoSync } = useDeviceStore();
  const { triggerRepCompletionHaptic } = useProgressiveHaptics();
  const { active: ghostActive, registerAttempt, currentGhost } = useGhostStore();
  const { getRecommendedReps, recordSession, recordSuccess, recordFailure } = useProgressionStore();
  const { speak } = useAudioCoach();

  // Demographics
  const demographicProfile = DemographicEngine.getProfileType(
    profile.age || 30,
    profile.gender || 'other',
    profile.wantsCycleSyncing || false,
  );
  const demoFeatures = DemographicEngine.getFeatures(demographicProfile);
  const [jointPain, setJointPain] = useState(0);
  const isHighImpactPainful = demoFeatures.autoReplaceImpact && jointPain >= 7;

  // Efeitos
  useWakeLock(true);

  useEffect(() => {
    const t = setInterval(() => setElapsed((e) => e + 1), 1000);
    return () => clearInterval(t);
  }, []);

  useEffect(() => {
    if (profile && history) {
      const report = generateReport(history, profile.weight || 75, todayPlan);
      setRiskReport(report);
      if (report.overallRisk === 'low') {
        const hasSeenLowRisk = localStorage.getItem('fittrack_seen_low_risk');
        if (hasSeenLowRisk) {
          setShowRiskPanel(false);
        } else {
          localStorage.setItem('fittrack_seen_low_risk', 'true');
        }
      }
    }
  }, [profile, history, todayPlan]);

  function applyWorkoutModifications(mods: WorkoutModification[]) {
    const newExs = [...localExs];
    const newSets = cloneSets(sets);

    mods.forEach((mod) => {
      const idx = newExs.findIndex((e) => e.name === mod.exerciseName);
      if (idx === -1 || !newExs[idx] || !newSets[idx]) return;

      if (mod.originalType === 'swap' && mod.alternativeExercise) {
        newExs[idx].name = mod.alternativeExercise;
      } else if (mod.originalType === 'reduce_load') {
        newSets[idx].forEach((s) => {
          s.weight = Math.floor((s.weight || 0) * 0.8);
        });
      } else if (mod.originalType === 'reduce_volume') {
        const keepCount = Math.ceil(newSets[idx].length * 0.7);
        newSets[idx] = newSets[idx].slice(0, keepCount);
      } else if (mod.originalType === 'remove') {
        newSets[idx] = [];
      }
    });

    setLocalExs(newExs);
    setSets(newSets);
  }

  useEffect(() => {
    if (workoutMode !== 'amrap' || !amrapRunning) return;
    if (amrapTimeLeft <= 0) {
      setAmrapRunning(false);
      navigator.vibrate?.([300, 100, 300, 100, 300]);
      return;
    }
    const interval = setInterval(() => setAmrapTimeLeft((p) => p - 1), 1000);
    return () => clearInterval(interval);
  }, [workoutMode, amrapRunning, amrapTimeLeft]);

  useEffect(() => {
    if (workoutMode !== 'emom' || !emomRunning) return;
    if (emomRemainingSeconds <= 0) {
      navigator.vibrate?.(500);
      setEmomRemainingSeconds(60);
      setEmomRound((r) => r + 1);
      return;
    }
    const interval = setInterval(() => setEmomRemainingSeconds((p) => p - 1), 1000);
    return () => clearInterval(interval);
  }, [workoutMode, emomRunning, emomRemainingSeconds]);

  useEffect(() => {
    if (Object.keys(EXERCISE_DB).length > 0 && localExs.some((e) => !e.equipment)) {
      setLocalExs((prev) => prev.map((e) => ({ ...e, ...(EXERCISE_DB[e.name] || {}) })));
    }
  }, [EXERCISE_DB]);

  // Handlers
  const handleRepDetected = () => {
    if (!profile.proMode && navigator.vibrate) navigator.vibrate(20);
    if (openIdx !== -1 && sets[openIdx]) {
      const activeSetIdx = sets[openIdx].findIndex((s: any) => !s.done);
      if (activeSetIdx !== -1 && sets[openIdx][activeSetIdx]) {
        const currentReps = sets[openIdx][activeSetIdx].reps;
        upd(openIdx, activeSetIdx, 'reps', String(currentReps + 1));
      }
    }
  };

  const handlePRAndSaveLog = async (_ei: number, si: number, currentSet: any, exName: string) => {
    const prResult = await savePRAndSetLog(exName, si, currentSet, workoutIdRef.current);
    if (prResult) setNewPRData(prResult);
    updateTrendMessage(exName, setAutoregulationMessage);
  };

  const handleGhostMode = (ei: number, currentSet: any) => {
    if (!ghostActive || profile.proMode) return false;
    const isGhostSuccess = currentSet.reps >= (currentGhost?.bestReps || 0);
    const xpGain = registerAttempt(
      localExs[ei]?.name || '',
      currentSet.weight,
      currentSet.reps,
      isGhostSuccess,
    );
    if (xpGain > 0) {
      setShowConfetti(true);
      setTimeout(() => setShowConfetti(false), 3000);
    }
    return isGhostSuccess;
  };

  const handleCircuitCompletion = (ei: number) => {
    if (!isCircuit) return;
    const exName = localExs[ei]?.name;
    if (!exName) return;
    const newCompleted = [...roundExercisesCompleted, exName];
    if (roundExercisesCompleted.includes(exName)) return;
    setRoundExercisesCompleted(newCompleted);
    if (newCompleted.length === localExs.length && currentRound < (todayPlan.rounds || 1)) {
      setRoundRestRemaining(todayPlan.restBetweenRounds || 60);
      const timer = setInterval(() => {
        setRoundRestRemaining((prev) => {
          if (prev === null || prev <= 1) {
            clearInterval(timer);
            setCurrentRound((r) => r + 1);
            setRoundExercisesCompleted([]);
            return null;
          }
          return prev - 1;
        });
      }, 1000);
    }
  };

  const handleProgressionEvaluation = (ei: number, currentSet: any) => {
    const tr = getRecommendedReps(localExs[ei]?.name || '', localExs[ei]?.base?.hipertrofia?.[2] || 10);
    const rpeVal = currentSet?.rpe ? Number(currentSet.rpe) : 8;
    if ((currentSet?.reps || 0) < tr * 0.8 || rpeVal >= 9.5) {
      recordFailure(localExs[ei]?.name || '');
    } else {
      recordSuccess(localExs[ei]?.name || '', currentSet?.reps || 0, tr, rpeVal);
    }
    speak(`Série completada com ${currentSet.weight} quilos. Descansa.`);
  };

  // Toggle simplificado (extraído lógica para funções auxiliares)
  const toggle = (ei: number, si: number) => {
    const currentSet = sets[ei]?.[si];
    if (!currentSet) return;

    if (!currentSet.done && currentSet.weight > 0 && currentSet.reps > 0) {
      handlePRAndSaveLog(ei, si, currentSet, localExs[ei]?.name || '');
    }
    setSets((prev) => {
      const n = cloneSets(prev);
      if (!n[ei] || !n[ei][si]) return n;
      if (!n[ei][si].done) {
        if (!profile.proMode) beep(880, 0.07);
        setShowTimer(true);
        const isGhostSuccess = handleGhostMode(ei, n[ei][si]);
        triggerRepCompletionHaptic(isGhostSuccess);
        handleCircuitCompletion(ei);
        handleProgressionEvaluation(ei, currentSet);
      }
      n[ei][si].done = !n[ei][si].done;
      if (!n[ei][si].done) {
        const nst = { ...setStartTimes };
        delete nst[`${ei}-${si}`];
        setSetStartTimes(nst);
      }
      return n;
    });
  };

  const upd = (ei: number, si: number, f: string, v: string) => {
    const valNum = Number(v);
    if (f === 'rpe') {
      if (valNum >= 9.5) {
        setAutoregulationMessage({
          text: '⚠️ Fadiga Elevada Detetada! Sugerimos reduzir a carga em 5% a 10% na próxima série para manter a boa execução e proteger o SNC.',
          type: 'danger',
        });
        if (navigator.vibrate) navigator.vibrate([100, 50, 100]);
      } else if (valNum <= 6) {
        setAutoregulationMessage({
          text: '🚀 Estás a voar! Podes aumentar a carga em 2.5kg na próxima série se te sentires confiante.',
          type: 'success',
        });
      } else {
        setAutoregulationMessage(null);
      }
    }
    setSets((prev) => {
      const n = cloneSets(prev);
      if (!n[ei] || !n[ei][si]) return n;
      (n[ei][si] as any)[f] = valNum;
      if (f === 'reps' && !setStartTimes[`${ei}-${si}`]) {
        setSetStartTimes((p) => ({ ...p, [`${ei}-${si}`]: Date.now() - 5000 }));
      }
      return n;
    });
  };

  const addWarmups = (ei: number) => {
    setSets((prev) => {
      const n = cloneSets(prev);
      if (!n[ei]) return n;
      const workingWeight = Math.max(...n[ei].map((s) => s.weight)) || 20;
      const warmups = getWarmupSets(workingWeight).map((w) => ({ ...w, rpe: 8, done: false }));
      n[ei] = [...warmups, ...n[ei]];
      return n;
    });
  };

  const applyPreset = (ei: number, mode: 'strength' | 'endurance') => {
    const exName = localExs[ei]?.name;
    if (!exName) return;
    const pr = findHistoricalPR(history, exName);
    const prescription = getPrescription(profile, exName, pr, todayPlan.phase);
    const preset = prescription.presets[mode];
    setSets((prev) => {
      const n = cloneSets(prev);
      if (n[ei]) {
        n[ei] = n[ei].map((s) => ({ ...s, weight: preset.weight, reps: preset.reps }));
      }
      return n;
    });
  };

  const applyVolumePreset = (ei: number) => {
    const exName = localExs[ei]?.name;
    if (!exName) return;
    const pr = findHistoricalPR(history, exName);
    const prescription = getPrescription(profile, exName, pr, todayPlan.phase);
    const delta = prescription.presets.volume.setsDelta || 1;
    setSets((prev) => {
      const n = cloneSets(prev);
      if (!n[ei] || n[ei].length === 0) return n;
      const newSets = [...n[ei]];
      for (let i = 0; i < delta; i++) {
        newSets.push({
          ...(newSets[0] as any),
          reps: newSets[0]?.reps || 10,
          weight: newSets[0]?.weight || 0,
          rpe: newSets[0]?.rpe || 8,
          done: false,
        });
      }
      n[ei] = newSets;
      return n;
    });
  };

  const finish = () => {
    const totalVolume = calcVolume(sets);
    setFinalVolume(totalVolume);
    localExs.forEach((ex, idx) => {
      const tr = getRecommendedReps(ex.name, ex.base?.hipertrofia?.[2] || 10);
      const mappedSets = (sets[idx] || []).map(s => ({ reps: s.reps, weight: s.weight, completed: s.done, rpe: s.rpe }));
      recordSession(ex.name, mappedSets, tr);
    });
    if (rivalState.found) {
      setShowRivalResult(true);
    } else {
      commitFinish(totalVolume);
    }
  };

  const commitFinish = (vol: number) => {
    const isCustom = todayPlan.id?.startsWith('free_') || !!todayPlan.isCustom;
    const doneSetsArr = sets.flat().filter((s) => s.done);
    const totalRpe = doneSetsArr.reduce((sum, s) => sum + (s.rpe || 8), 0);
    const avgRPE =
      doneSetsArr.length > 0 ? Math.round((totalRpe / doneSetsArr.length) * 10) / 10 : 0;

    const payloadExercises = localExs
      .map((ex, ei) => ({
        name: ex.name,
        muscle: ex.muscle,
        type: (ex as any).type || 'weighted',
        sets: (sets[ei] as any[])
          .filter((s) => s.done)
          .map((s) => ({
            weight: s.weight,
            reps: s.reps,
            rpe: s.rpe || 8,
            duration: s.duration,
            distance: s.distance,
            addedWeight: s.addedWeight,
            type: s.type || (ex as any).type || 'weighted',
          })),
      }))
      .filter((e) => e.sets.length > 0);

    const allSetsFlat = payloadExercises.flatMap((e) => e.sets.map((s) => ({ ...s, done: true })));
    const effortScore = calculateWorkoutEffort(allSetsFlat, profile.weight || 75);

    const payload = {
      id: workoutIdRef.current,
      date: new Date().toISOString(),
      dayLabel: todayPlan.label || 'Treino Livre',
      duration: elapsed,
      exercises: payloadExercises,
      totalVolume: vol,
      avgRPE,
      isCustom,
      customExercisesList: isCustom ? todayPlan.exercises : [],
    };
    saveWorkoutSession({
      id: workoutIdRef.current,
      date: Date.now(),
      name: todayPlan.label || 'Treino Livre',
      durationSeconds: elapsed,
      readinessScore: 85,
      totalVolumeKg: vol,
      effortScore,
      avgRPE,
      isCompleted: true,
    } as any).catch((e) => console.warn('[IDB] Falha ao gravar WorkoutSession:', e));
    onFinish(payload);
  };

  const totalSets = sets.flat().length;
  const doneSets = sets.flat().filter((s) => s.done).length;
  const currentVolume = calcVolume(sets);

  // Render
  if (showRiskPanel && riskReport) {
    return (
      <GlobalBackground>
        <div style={{ minHeight: '100vh', padding: 16 }}>
          <InjuryRiskPanel
            report={riskReport}
            onStartWorkout={() => setShowRiskPanel(false)}
            onApplyAllModifications={(mods) => {
              applyWorkoutModifications(mods);
              setShowRiskPanel(false);
            }}
            onDismiss={() => setShowRiskPanel(false)}
          />
        </div>
      </GlobalBackground>
    );
  }

  return (
    <GlobalBackground>
      <div style={{ minHeight: '100vh', paddingBottom: 90 }}>
        {injuryMsgs.length > 0 && (
          <div className="p-4 space-y-3 mb-4">
            {injuryMsgs.map((msg) => (
              <ProactiveMessageCard key={msg.id} message={msg} />
            ))}
          </div>
        )}

        {newPRData && (
          <PRTracker
            exerciseName={newPRData.exerciseName}
            weight={newPRData.weight}
            onClose={() => setNewPRData(null)}
          />
        )}
        {showConfetti && !profile.proMode && <Confetti colors={['#e8c84a', '#d4b03a']} />}
        {!profile.proMode && (
          <div style={{ position: 'fixed', bottom: 90, right: 16, zIndex: 50 }}>
            <GhostToggle />
          </div>
        )}
        {ghostActive && currentGhost && !profile.proMode && (
          <div
            style={{
              position: 'fixed',
              top: 80,
              right: 16,
              background: 'rgba(26, 31, 37, 0.9)',
              backdropFilter: 'blur(10px)',
              padding: 12,
              borderRadius: 8,
              borderLeft: '4px solid #e8c84a',
              zIndex: 40,
            }}
          >
            <p style={{ fontSize: 10, color: C.accent, fontFamily: "'DM Mono'" }}>GHOST TARGET</p>
            <p style={{ fontSize: 14, fontWeight: 'bold', color: '#fff' }}>
              {currentGhost.bestWeight}kg x {currentGhost.bestReps}
            </p>
            <p style={{ fontSize: 10, color: C.muted }}>+250 XP se vencer</p>
          </div>
        )}

        {/* MODAIS */}
        {showLibrary && (
          <ExerciseLibrary
            onClose={() => setShowLibrary(false)}
            onCreateWorkout={(names) => {
              const newExs = names.map((n: string) => ({
                name: n,
                ...(EXERCISE_DB[n] || { muscle: 'Outro' }),
              }));
              setLocalExs((prev) => [...prev, ...newExs]);
              setSets((prev) => {
                const newSets = newExs.map((ex) => {
                  const pr = findHistoricalPR(history, ex.name);
                  const prescription = getPrescription(
                    profile,
                    ex.name,
                    pr,
                    todayPlan.phase,
                    history,
                  );
                  const startW =
                    prescription.suggestedWeight ||
                    ProgressionSystem.calculateNextWeight(pr?.weight || 0, pr?.reps || 10, 10);
                  return Array.from({ length: 3 }, () => ({
                    reps: prescription.repsSuggested,
                    weight: startW,
                    rpe: prescription.rpeTarget,
                    done: false,
                    type: (ex as any).type || 'weighted',
                    duration: 0,
                    distance: 0,
                    addedWeight: 0,
                  }));
                });
                return [...prev, ...newSets];
              });
              setShowLibrary(false);
            }}
          />
        )}
        {showTimer && <RestTimer onClose={() => setShowTimer(false)} />}
        <PlateCalculator
          isOpen={showPlateCalc}
          onClose={() => setShowPlateCalc(false)}
          initialWeight={sets[currentExerciseIdx]?.[currentSetIdx]?.weight || 0}
          onSelectWeight={(newWeight) =>
            upd(currentExerciseIdx, currentSetIdx, 'weight', String(newWeight))
          }
        />
        {confirmCancel && (
          <ConfirmCancelModal onBack={() => setConfirmCancel(false)} onConfirm={onCancel} />
        )}

        {showRivalResult && (
          <RivalResult
            isWinner={finalVolume >= rivalState.rivalVolume}
            rivalVolume={rivalState.rivalVolume}
            userVolume={finalVolume}
            onContinue={() => commitFinish(finalVolume)}
          />
        )}
        {showShareModal && (
          <ShareWorkoutModal
            workoutPlan={todayPlan}
            onClose={() => setShowShareModal(false)}
            onImport={(importedPlan) => {
              if (importedPlan.exercises?.length > 0) {
                const newExs = importedPlan.exercises.map((n: string) => ({
                  name: n,
                  muscle: 'Treino',
                  ...(EXERCISE_DB[n] || {}),
                }));
                setLocalExs(newExs);
                setSets(
                  newExs.map(() =>
                    Array.from({ length: 3 }, () => ({
                      reps: 10,
                      weight: 40,
                      rpe: 8,
                      done: false,
                    })),
                  ),
