import { motion } from 'framer-motion';
// @ts-nocheck
import React from 'react';
import { C } from '../data/constants';
import { calculateStreak, useMilestonesStore } from '../stores/useMilestonesStore';

const BADGES = [
  { id: '1_workout', label: '1º Treino', icon: '🥉', check: (h: any[]) => h.length >= 1 },
  { id: '10_workouts', label: '10 Treinos', icon: '🥈', check: (h: any[]) => h.length >= 10 },
  { id: '25_workouts', label: '25 Treinos', icon: '🥇', check: (h: any[]) => h.length >= 25 },
  { id: '50_workouts', label: '50 Treinos', icon: '💎', check: (h: any[]) => h.length >= 50 },
  { id: '100_workouts', label: '100 Treinos', icon: '👑', check: (h: any[]) => h.length >= 100 },
  {
    id: 'streak_7',
    label: 'Streak 7 dias',
    icon: '🔥',
    check: (h: any[]) => calculateStreak(h) >= 7,
  },
  {
    id: 'streak_30',
    label: 'Streak 30 dias',
    icon: '⚡',
    check: (h: any[]) => calculateStreak(h) >= 30,
  },
  {
    id: 'first_pr',
    label: 'Primeiro PR',
    icon: '💪',
    check: (_h: any[], prs: any) => Object.keys(prs).length > 0,
  },
  {
    id: '1000kg_volume',
    label: '1000kg Volume',
    icon: '🏋️',
    check: (h: any[]) => h.some((w) => w.totalVolume >= 1000),
  },
];

export default function Milestones({ history }: any) {
  const { milestones, unlockMilestone, prs } = useMilestonesStore();

  // Re-evaluate milestones
  React.useEffect(() => {
    BADGES.forEach((badge) => {
      if (!milestones[badge.id] && badge.check(history, prs)) {
        unlockMilestone(badge.id);
      }
    });
  }, [history, prs, milestones, unlockMilestone]);

  const currentStreak = calculateStreak(history);

  return (
    <div style={{ padding: '18px', maxWidth: 480, margin: '0 auto', paddingBottom: 90 }}>
      <div
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          marginBottom: 18,
        }}
      >
        <p
          style={{
            fontFamily: "'Bebas Neue'",
            fontSize: 24,
            letterSpacing: 2,
            margin: 0,
            color: C.accent,
          }}
        >
          CONQUISTAS 🏆
        </p>
      </div>

      <div style={{ display: 'flex', gap: 12, marginBottom: 24 }}>
        <div className="glass" style={{ flex: 1, padding: 16, textAlign: 'center' }}>
          <span style={{ fontSize: 24, display: 'block', marginBottom: 4 }}>🔥</span>
          <span
            style={{
              fontSize: 18,
              fontWeight: 'bold',
              color: currentStreak > 0 ? C.accent : C.text,
            }}
          >
            {currentStreak}
          </span>
          <span style={{ fontSize: 10, color: C.muted, display: 'block' }}>DIAS SEGUIDOS</span>
        </div>
        <div className="glass" style={{ flex: 1, padding: 16, textAlign: 'center' }}>
          <span style={{ fontSize: 24, display: 'block', marginBottom: 4 }}>💪</span>
          <span style={{ fontSize: 18, fontWeight: 'bold', color: C.accent }}>
            {Object.keys(prs).length}
          </span>
          <span style={{ fontSize: 10, color: C.muted, display: 'block' }}>RECORDES (PRs)</span>
        </div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
        {BADGES.map((badge, i) => {
          const unlocked = !!milestones[badge.id];
          const unlockDate = unlocked ? new Date(milestones[badge.id] as number).toLocaleDateString() : '???';

          return (
            <motion.div
              key={badge.id}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: i * 0.05 }}
              style={{
                background: unlocked ? `${C.accent}11` : C.surface,
                border: `1px solid ${unlocked ? C.accent : C.border}`,
                borderRadius: 12,
                padding: 16,
                textAlign: 'center',
                filter: unlocked ? 'none' : 'grayscale(100%) opacity(0.5)',
              }}
            >
              <span
                style={{
                  fontSize: 32,
                  display: 'block',
                  marginBottom: 8,
                  filter: unlocked ? 'drop-shadow(0 0 10px rgba(232,200,74,0.5))' : 'none',
                }}
              >
                {badge.icon}
              </span>
              <span
                style={{
                  display: 'block',
                  fontSize: 13,
                  fontWeight: 'bold',
                  color: unlocked ? C.accent : C.muted,
                  marginBottom: 4,
                }}
              >
                {badge.label}
              </span>
              <span style={{ display: 'block', fontSize: 10, color: C.muted }}>{unlockDate}</span>
            </motion.div>
          );
        })}
      </div>

      {Object.keys(prs).length > 0 && (
        <div style={{ marginTop: 24 }}>
          <p
            style={{
              fontFamily: "'Bebas Neue'",
              fontSize: 20,
              letterSpacing: 1,
              color: C.text,
              marginBottom: 12,
            }}
          >
            RECORDES PESSOAIS (1RM)
          </p>
          <div
            className="glass"
            style={{ padding: 16, display: 'flex', flexDirection: 'column', gap: 8 }}
          >
            {Object.entries(prs).map(([exercise, weight]) => (
              <div
                key={exercise}
                style={{
                  display: 'flex',
                  justifyContent: 'space-between',
                  borderBottom: `1px solid ${C.border}`,
                  paddingBottom: 8,
                }}
              >
                <span style={{ fontSize: 14, color: C.text }}>{exercise}</span>
                <span
                  style={{
                    fontSize: 14,
                    fontWeight: 'bold',
                    color: C.accent,
                    fontFamily: "'DM Mono'",
                  }}
                >
                  {weight} kg
                </span>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

import { AnimatePresence, motion } from 'framer-motion';
import { Activity, AlertTriangle, Apple, Flame, Plus, Send, Sparkles, Trash2 } from 'lucide-react';
import type React from 'react';
import { useEffect, useRef, useState } from 'react';
import type { MealItem } from '../db/schema';
import { PRESET_FOODS } from '../services/nutritionEngine';
// Adapta os imports às localizações exatas do teu V7
import { useNutritionStore } from '../stores/useNutritionStore';
import { validateMealItem } from '../utils/validation';

// ─── TEMA DARK NEON (V7) ─────────────────────────────────────────────────────
const theme = {
  bg: '#080b0f',
  glass: 'rgba(255, 255, 255, 0.03)',
  glassHover: 'rgba(255, 255, 255, 0.06)',
  border: 'rgba(255, 255, 255, 0.08)',
  accent: '#ccff00', // Neon Lime (Primário)
  success: '#00ff88', // Emerald Neon
  text: '#eceae4',
  muted: 'rgba(255, 255, 255, 0.5)',
  danger: '#ff3366',
};

const NutritionPlanner: React.FC = () => {
  // Estado Global via Zustand
  const { profile, currentMealLog: mealsLog, addMeal, removeMeal } = useNutritionStore();
  const currentDate = new Date().toISOString().split('T')[0] || '';

  // O estado atual das refeições no Zustand não expõe "meals" como array de logs se quisermos aceder ao dia específico,
  // expõe apenas "currentMealLog", que é o log da data atual se carregado corretamente.
  const todayMeals = mealsLog || { breakfast: [], lunch: [], snack: [], dinner: [] };

  // Estado Local da UI
  const [activeSegment, setActiveSegment] = useState<'breakfast' | 'lunch' | 'snack' | 'dinner'>(
    'breakfast',
  );
  const [presetFoodIndex, setPresetFoodIndex] = useState('0');
  const [customFood, setCustomFood] = useState({
    name: PRESET_FOODS[0]?.name || '',
    cal: PRESET_FOODS[0]?.calories || 0,
    p: PRESET_FOODS[0]?.protein || 0,
    c: PRESET_FOODS[0]?.carb || 0,
    f: PRESET_FOODS[0]?.fat || 0,
  });
  const [validationErrors, setValidationErrors] = useState<Record<string, string>>({});

  // Estado da IA
  const [userQuery, setUserQuery] = useState('');
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [aiChat, setAiChat] = useState<{ id: string; sender: 'user' | 'ai'; text: string }[]>([
    {
      id: '1',
      sender: 'ai',
      text: 'Bem-vindo ao **NutriChef AI**. Posso gerar receitas com o que tens no frigorífico ou ajustar os teus macros. O que vamos cozinhar hoje?',
    },
  ]);
  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [aiChat]);

  // Cálculos do dia
  const getSum = (items: MealItem[]) =>
    items.reduce(
      (acc, curr) => ({
        cal: acc.cal + curr.calories,
        p: acc.p + curr.protein,
        c: acc.c + curr.carb,
        f: acc.f + curr.fat,
      }),
      { cal: 0, p: 0, c: 0, f: 0 },
    );

  const dailyTotals = (['breakfast', 'lunch', 'snack', 'dinner'] as const).reduce(
    (acc, seg) => {
      const sum = getSum(todayMeals[seg]);
      return { cal: acc.cal + sum.cal, p: acc.p + sum.p, c: acc.c + sum.c, f: acc.f + sum.f };
    },
    { cal: 0, p: 0, c: 0, f: 0 },
  );

  // Handlers
  const handleAddFood = async (e: React.FormEvent) => {
    e.preventDefault();

    // Validar com Zod antes de submeter
    const mealData = {
      name: customFood.name,
      calories: Number(customFood.cal),
      protein: Number(customFood.p),
      carb: Number(customFood.c),
      fat: Number(customFood.f),
    };

    const result = validateMealItem(mealData);
    if (!result.success) {
      setValidationErrors(result.errors || {});
      return;
    }

    // Limpar erros e submeter
    setValidationErrors({});
    await addMeal(currentDate, activeSegment, {
      id: Date.now().toString(),
      name: result.data!.name,
      calories: result.data!.calories,
      protein: result.data!.protein,
      carb: result.data!.carb,
      fat: result.data!.fat,
    });
  };

  const handlePresetChange = (idx: string) => {
    setPresetFoodIndex(idx);
    setValidationErrors({}); // Limpar erros ao mudar preset
    if (idx !== 'custom') {
      const food = PRESET_FOODS[Number(idx)];
      if (food) {
        setCustomFood({
          name: food.name,
          cal: food.calories,
          p: food.protein,
          c: food.carb,
          f: food.fat,
        });
      }
    } else {
      setCustomFood({ name: '', cal: 0, p: 0, c: 0, f: 0 });
    }
  };

  const handleAskAI = async (e?: React.FormEvent, presetPrompt?: string) => {
    e?.preventDefault();
    const query = presetPrompt || userQuery;
    if (!query.trim()) return;

    setAiChat((prev) => [...prev, { id: Date.now().toString(), sender: 'user', text: query }]);
    setUserQuery('');
    setIsAiLoading(true);

    try {
      // Chamada à tua Vercel Function Blindada
      const res = await fetch('/api/nutrichef', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json' /* Adiciona a injeção do JWT Efémero aqui */,
        },
        body: JSON.stringify({
          goal: profile.goal,
          targetCalories: profile.targetCalories || 2000,
          userMessage: query,
        }),
      });
      const data = await res.json();
      setAiChat((prev) => [
        ...prev,
        { id: Date.now().toString(), sender: 'ai', text: data.text || 'Erro na matriz neural.' },
      ]);
    } catch (_err) {
      setAiChat((prev) => [
        ...prev,
        {
          id: Date.now().toString(),
          sender: 'ai',
          text: 'Falha de conexão com o terminal NutriChef.',
        },
      ]);
    } finally {
      setIsAiLoading(false);
    }
  };

  const targetCal = profile.targetCalories || 2000;
  const targetProt = profile.targetProtein || 120;
  const targetCarb = profile.targetCarb || 200;
  const targetFat = profile.targetFat || 60;

  return (
    <div
      style={{
        maxWidth: '1400px',
        margin: '0 auto',
        display: 'flex',
        flexDirection: 'column',
        gap: '24px',
        padding: '16px',
      }}
    >
      {/* ─── TOPO: DASHBOARD METABÓLICO ────────────────────────────────────────── */}
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))',
          gap: '24px',
        }}
      >
        {/* Bloco 1: Balanço Calórico */}
        <div
          className="glass-card"
          style={{
            padding: '24px',
            background: theme.glass,
            border: `1px solid ${theme.border}`,
            borderRadius: '16px',
          }}
        >
          <div
            style={{
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center',
              marginBottom: '16px',
            }}
          >
            <span
              style={{
                fontSize: '0.85rem',
                color: theme.muted,
                textTransform: 'uppercase',
                fontWeight: 700,
              }}
            >
              Balanço Diário
            </span>
            <Flame size={20} color={theme.accent} />
          </div>
          <div style={{ display: 'flex', alignItems: 'baseline', gap: '8px' }}>
            <h2
              style={{
                margin: 0,
                fontSize: '3rem',
                fontFamily: '"Bebas Neue", sans-serif',
                color: theme.text,
              }}
            >
              {Math.max(0, targetCal - dailyTotals.cal)}
            </h2>
            <span
              style={{ color: theme.muted, fontSize: '0.9rem', fontFamily: '"DM Mono", monospace' }}
            >
              kcal restantes
            </span>
          </div>
          <div
            style={{
              marginTop: '16px',
              height: '6px',
              background: 'rgba(255,255,255,0.1)',
              borderRadius: '4px',
              overflow: 'hidden',
            }}
          >
            <motion.div
              initial={{ width: 0 }}
              animate={{ width: `${Math.min(100, (dailyTotals.cal / targetCal) * 100)}%` }}
              style={{
                height: '100%',
                background: theme.accent,
                boxShadow: `0 0 10px ${theme.accent}`,
              }}
            />
          </div>
        </div>

        {/* Bloco 2: Macros (P / C / G) */}
        <div
          className="glass-card"
          style={{
            padding: '24px',
            background: theme.glass,
            border: `1px solid ${theme.border}`,
            borderRadius: '16px',
          }}
        >
          <div
            style={{
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center',
              marginBottom: '16px',
            }}
          >
            <span
              style={{
                fontSize: '0.85rem',
                color: theme.muted,
                textTransform: 'uppercase',
                fontWeight: 700,
              }}
            >
              Macronutrientes
            </span>
            <Activity size={20} color={theme.success} />
          </div>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '16px' }}>
            <MacroGauge
              label="Proteína"
              current={dailyTotals.p}
              target={targetProt}
              color={theme.success}
            />
            <MacroGauge
              label="Carboidratos"
              current={dailyTotals.c}
              target={targetCarb}
              color="#00d4ff"
            />
            <MacroGauge
              label="Gorduras"
              current={dailyTotals.f}
              target={targetFat}
              color="#ffaa00"
            />
          </div>
        </div>
      </div>

      {/* ─── CORPO: LOG DE REFEIÇÕES VS IA (Grid 7/5) ────────────────────────── */}
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(400px, 1fr))',
          gap: '24px',
        }}
      >
        {/* ESQUERDA: Gestor de Refeições */}
        <div style={{ gridColumn: 'span 2' }}>
          <div
            className="glass-card"
            style={{
              background: theme.glass,
              border: `1px solid ${theme.border}`,
              borderRadius: '16px',
              overflow: 'hidden',
            }}
          >
            {/* Tabs */}
            <div
              style={{
                display: 'flex',
                background: 'rgba(0,0,0,0.2)',
                borderBottom: `1px solid ${theme.border}`,
              }}
            >
              {(['breakfast', 'lunch', 'snack', 'dinner'] as const).map((seg) => (
                <button
                  key={seg}
                  onClick={() => setActiveSegment(seg)}
                  style={{
                    flex: 1,
                    padding: '16px 0',
                    background: 'none',
                    border: 'none',
                    cursor: 'pointer',
                    color: activeSegment === seg ? theme.accent : theme.muted,
                    borderBottom:
                      activeSegment === seg ? `2px solid ${theme.accent}` : '2px solid transparent',
                    fontWeight: 700,
                    textTransform: 'uppercase',
                    fontSize: '0.8rem',
                    letterSpacing: '1px',
                    transition: 'all 0.3s ease',
