import type React from 'react';
import { HealthSyncSettings } from '../components/settings/HealthSyncSettings';
import { C, GOALS } from '../data/constants';
import { sanitizeText } from '../utils/sanitize';

interface SettingsProps {
  profile: any;
  setProfile: (p: any) => void;
  onReset: () => void;
}

export default function Settings({ profile, setProfile, onReset }: SettingsProps) {
  const exportBackup = async () => {
    const { get } = await import('idb-keyval');
    const profileData =
      (await get('fit_profile')) || JSON.parse(localStorage.getItem('fit_profile') || '{}');
    const historyData =
      (await get('fit_history')) || JSON.parse(localStorage.getItem('fit_history') || '[]');
    const challengesData =
      (await get('fit_challenges')) || JSON.parse(localStorage.getItem('fit_challenges') || '[]');

    const data = {
      profile: profileData,
      history: historyData,
      challenges: challengesData,
    };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `fittrack_backup_${new Date().toISOString().split('T')[0]}.json`;
    a.click();
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const data = JSON.parse(event.target?.result as string);
        if (data.profile) {
          setProfile(data.profile); // Atualiza a store global e grava seguro via hook
          const { set } = await import('idb-keyval');
          await set('fit_profile', data.profile);
        }
        if (data.history) {
          // Evitar gravar plain text no localStorage
          const { set } = await import('idb-keyval');
          await set('fit_history', data.history);
        }
        alert('Restauro completo! A aplicação vai reiniciar.');
        window.location.reload();
      } catch (_err) {
        alert('Erro ao importar o backup. Ficheiro inválido.');
      }
    };
    reader.readAsText(file);
  };
  return (
    <div style={{ padding: '18px', maxWidth: 480, margin: '0 auto' }}>
