import { getDB, getRecentSetLogsByExercise, getRecoveryMetricsByDateRange } from '../db/schema';

export interface InjuryRiskReport {
  overallRisk: 'low' | 'moderate' | 'high' | 'critical';
  riskScore: number;
  flags: RiskFlag[];
  recommendations: string[];
  affectedMuscleGroups: string[];
  nextReview: string;
}

export interface RiskFlag {
  type:
    | 'volume_spike'
    | 'asymmetry'
    | 'rpe_drift'
    | 'velocity_decay'
    | 'recovery_decline'
    | 'overuse';
  severity: 'warning' | 'alert' | 'critical';
  message: string;
  exerciseName?: string;
  metric: string;
  threshold: string;
}

const ACWR_SAFE_MIN = 0.8;
const ACWR_SAFE_MAX = 1.3;
const ACWR_DANGER = 1.5;
const RPE_DRIFT_THRESHOLD = 0.5;
const _VELOCITY_DECAY_THRESHOLD = 15;
const OVERUSE_THRESHOLD = 5;

export async function generateInjuryRiskReport(): Promise<InjuryRiskReport> {
  const now = Date.now();
  const sevenDaysAgo = now - 7 * 24 * 60 * 60 * 1000;
  const twentyEightDaysAgo = now - 28 * 24 * 60 * 60 * 1000;

  const flags: RiskFlag[] = [];

  const acwrFlags = await analyzeACWR(sevenDaysAgo, twentyEightDaysAgo);
  flags.push(...acwrFlags);

  const rpeFlags = await analyzeRPEDrift(sevenDaysAgo);
  flags.push(...rpeFlags);

  const recoveryFlags = await analyzeRecoveryDecline();
  flags.push(...recoveryFlags);

  const overuseFlags = await analyzeOveruse(sevenDaysAgo);
  flags.push(...overuseFlags);

  const riskScore = calculateOverallRisk(flags);
  const overallRisk = scoreToRiskLevel(riskScore);

  return {
    overallRisk,
    riskScore,
    flags,
    recommendations: generateRecommendations(flags, overallRisk),
    affectedMuscleGroups: extractAffectedGroups(flags),
    nextReview:
      overallRisk === 'critical' ? '24 horas' : overallRisk === 'high' ? '3 dias' : '7 dias',
  };
}

async function analyzeACWR(acuteStart: number, chronicStart: number): Promise<RiskFlag[]> {
  const flags: RiskFlag[] = [];
  const acuteVolume = await calculateVolumeInRange(acuteStart, Date.now());
  const chronicVolume = (await calculateVolumeInRange(chronicStart, Date.now())) / 4;

  if (chronicVolume === 0) return flags;

  const acwr = acuteVolume / chronicVolume;

  if (acwr > ACWR_DANGER) {
    flags.push({
      type: 'volume_spike',
      severity: 'critical',
      message: `Volume de treino aumentou ${((acwr - 1) * 100).toFixed(0)}% esta semana. Risco elevado de overload agudo.`,
      metric: acwr.toFixed(2),
      threshold: `ACWR > ${ACWR_DANGER}`,
    });
  } else if (acwr > ACWR_SAFE_MAX) {
    flags.push({
      type: 'volume_spike',
      severity: 'alert',
      message: `Volume de treino está ${((acwr - 1) * 100).toFixed(0)}% acima do normal. Reduzir 10-15%.`,
      metric: acwr.toFixed(2),
      threshold: `ACWR > ${ACWR_SAFE_MAX}`,
    });
  } else if (acwr < ACWR_SAFE_MIN) {
    flags.push({
      type: 'volume_spike',
      severity: 'warning',
      message: 'Volume de treino abaixo do normal. Possível detraining.',
      metric: acwr.toFixed(2),
      threshold: `ACWR < ${ACWR_SAFE_MIN}`,
    });
  }

  return flags;
}

async function analyzeRPEDrift(since: number): Promise<RiskFlag[]> {
  const flags: RiskFlag[] = [];
  const exercises = ['Barbell Back Squat', 'Bench Press', 'Deadlift', 'Overhead Press'];

  for (const exercise of exercises) {
    const logs = await getRecentSetLogsByExercise(exercise, 30);
    const recentLogs = logs.filter((l) => l.timestamp >= since);

    if (recentLogs.length < 6) continue;
    const weeklyRPE = groupByWeek(
      recentLogs.map((l) => ({ date: l.timestamp, rpe: l.rpe, weight: l.weightKg })),
    );
    if (weeklyRPE.length < 2) continue;

    const avgRPEFirst = weeklyRPE[0].reduce((s, d) => s + d.rpe, 0) / weeklyRPE[0].length;
    const avgRPELast =
      weeklyRPE[weeklyRPE.length - 1].reduce((s, d) => s + d.rpe, 0) /
      weeklyRPE[weeklyRPE.length - 1].length;

    const rpeDrift = avgRPELast - avgRPEFirst;

    if (rpeDrift > RPE_DRIFT_THRESHOLD) {
      flags.push({
        type: 'rpe_drift',
        severity: 'alert',
        message: `RPE em ${exercise} subiu ${rpeDrift.toFixed(1)} com cargas semelhantes.`,
        exerciseName: exercise,
        metric: rpeDrift.toFixed(1),
        threshold: `RPE drift > ${RPE_DRIFT_THRESHOLD}`,
      });
    }
  }
  return flags;
}

async function analyzeRecoveryDecline(): Promise<RiskFlag[]> {
  const flags: RiskFlag[] = [];
  const now = Date.now();
  const fourteenDaysAgo = now - 14 * 24 * 60 * 60 * 1000;

  const hrvMetrics = await getRecoveryMetricsByDateRange(fourteenDaysAgo, now, 'hrv');
  if (hrvMetrics.length < 5) return flags;

  const sorted = hrvMetrics.sort((a, b) => a.timestamp - b.timestamp);
  const firstWeek = sorted.slice(0, Math.floor(sorted.length / 2));
  const secondWeek = sorted.slice(Math.floor(sorted.length / 2));

  const avgFirst = firstWeek.reduce((s, m) => s + m.value, 0) / firstWeek.length;
  const avgSecond = secondWeek.reduce((s, m) => s + m.value, 0) / secondWeek.length;
  const decline = ((avgFirst - avgSecond) / avgFirst) * 100;

  if (decline > 10) {
    flags.push({
      type: 'recovery_decline',
      severity: decline > 20 ? 'critical' : 'alert',
      message: `HRV caiu ${decline.toFixed(1)}% nas últimas 2 semanas.`,
      metric: `${decline.toFixed(1)}%`,
      threshold: 'HRV decline > 10%',
    });
  }
  return flags;
}

async function calculateVolumeInRange(start: number, end: number): Promise<number> {
  const db = await getDB();
  const tx = db.transaction('setLogs', 'readonly');
  const index = tx.store.index('by-timestamp');
  const range = IDBKeyRange.bound(start, end);
  const logs = await index.getAll(range);
  return logs.reduce((sum, l) => sum + l.weightKg * l.repsCompleted, 0);
}

async function analyzeOveruse(since: number): Promise<RiskFlag[]> {
  const flags: RiskFlag[] = [];
  const db = await getDB();
  const tx = db.transaction('setLogs', 'readonly');
  const exercises = await tx.store.index('by-exerciseName').getAllKeys();

  for (const exerciseName of exercises) {
    const range = IDBKeyRange.bound([exerciseName, since], [exerciseName, Date.now()]);
    const logs = await db.getAllFromIndex('setLogs', 'by-exercise-timestamp', range);
    const uniqueWorkouts = new Set(logs.map((l) => l.workoutId)).size;
    if (uniqueWorkouts > OVERUSE_THRESHOLD) {
      flags.push({
        type: 'overuse',
        severity: 'alert',
        message: `Fizeste ${exerciseName} ${uniqueWorkouts} vezes nos últimos 7 dias. Risco de overuse.`,
        exerciseName: String(exerciseName),
        metric: uniqueWorkouts.toString(),
        threshold: `> ${OVERUSE_THRESHOLD}`,
      });
    }
  }
  return flags;
}

function groupByWeek<T extends { date: number }>(data: T[]): T[][] {
  const weeks: T[][] = [];
  const oneWeek = 7 * 24 * 60 * 60 * 1000;
  let currentWeek: T[] = [];
  let weekStart = data[0]?.date || Date.now();

  for (const item of data) {
    if (item.date - weekStart > oneWeek) {
      if (currentWeek.length > 0) weeks.push(currentWeek);
      currentWeek = [item];
      weekStart = item.date;
    } else {
      currentWeek.push(item);
    }
  }
  if (currentWeek.length > 0) weeks.push(currentWeek);
  return weeks;
}

function calculateOverallRisk(flags: RiskFlag[]): number {
  if (flags.length === 0) return 10;
  const severityWeights = { warning: 15, alert: 30, critical: 50 };
  let score = 0;
  for (const flag of flags) score += severityWeights[flag.severity];
  if (flags.length >= 3) score += 15;
  if (flags.length >= 5) score += 20;
  return Math.min(100, score);
}

function scoreToRiskLevel(score: number): InjuryRiskReport['overallRisk'] {
  if (score >= 70) return 'critical';
  if (score >= 50) return 'high';
  if (score >= 25) return 'moderate';
  return 'low';
}

function generateRecommendations(
  flags: RiskFlag[],
  risk: InjuryRiskReport['overallRisk'],
): string[] {
  const recs: string[] = [];
  if (risk === 'critical') {
    recs.push('🛑 PAUSA OBRIGATÓRIA: Não treines hoje. O risco de lesão é extremo.');
    recs.push('Prioriza sono de 8+ horas e hidratação.');
    return recs;
  }
  if (risk === 'high') {
    recs.push('⚠️ REDUZ VOLUME: Corta 30-40% do volume planejado hoje.');
    recs.push('Evita exercícios excêntricos pesados e falha muscular.');
  }
  for (const flag of flags) {
    switch (flag.type) {
      case 'volume_spike':
        recs.push('Implementa deload semanal.');
        break;
      case 'rpe_drift':
        recs.push(`Em ${flag.exerciseName}, reduz séries.`);
        break;
      case 'recovery_decline':
        recs.push('Adiciona 1 dia de descanso ativo.');
        break;
      case 'overuse':
        recs.push('Substitui movimentos padrão por variantes.');
        break;
    }
  }
  return recs;
}

function extractAffectedGroups(flags: RiskFlag[]): string[] {
  const groups = new Set<string>();
  for (const flag of flags) {
    if (flag.exerciseName) {
      const exercise = flag.exerciseName.toLowerCase();
      if (exercise.includes('squat') || exercise.includes('leg'))
        groups.add('Quadríceps / Glúteos');
      if (exercise.includes('deadlift')) groups.add('Posterior Chain');
      if (exercise.includes('bench') || exercise.includes('press')) groups.add('Peito / Ombros');
      if (exercise.includes('row') || exercise.includes('pull')) groups.add('Costas / Bíceps');
    }
  }
  return Array.from(groups);
}

export async function preWorkoutSafetyCheck(): Promise<{
  safe: boolean;
  report: InjuryRiskReport;
  overrideRequired: boolean;
}> {
  const report = await generateInjuryRiskReport();
  return {
    safe: report.overallRisk !== 'critical',
    report,
    overrideRequired: report.overallRisk === 'high' || report.overallRisk === 'critical',
  };
}

// @ts-nocheck
import { getAllExercisesFromHistory, getRecentSetLogsDecrypted } from '../db/encryptedDb';
import type { SetLog } from '../db/schema';
import type { DemographicProfile } from './demographicEngine';

export type InjuryRisk = 'LOW' | 'MODERATE' | 'HIGH' | 'CRITICAL';

export interface InjuryAssessment {
  overallRisk: InjuryRisk;
  acwr: number; // Acute:Chronic Workload Ratio
  acuteLoad: number; // Carga últimos 7 dias (kg)
  chronicLoad: number; // Carga média últimos 28 dias (kg)
  warnings: string[];
  alternativeExercises?: string[];
  restrictedExercises?: string[];
}

interface RiskConfig {
  risk: InjuryRisk;
  warnings: string[];
  restricted: string[];
  alternatives: string[];
}

const FOUR_WEEKS_MS = 28 * 24 * 3600 * 1000;
const ONE_WEEK_MS = 7 * 24 * 3600 * 1000;

// ---- Pure utility functions ----

/** Fetch all set logs for given exercises within the last 4 weeks */
async function fetchRecentSets(exercisesToCheck?: string[]): Promise<SetLog[]> {
  const fourWeeksAgo = Date.now() - FOUR_WEEKS_MS;

  if (exercisesToCheck && exercisesToCheck.length > 0) {
    const setsPromises = exercisesToCheck.map((ex) => getRecentSetLogsDecrypted(ex, 200));
    const setsArrays = await Promise.all(setsPromises);
    return setsArrays.flat().filter((s) => s.timestamp > fourWeeksAgo);
  }

  const allExercises = await getAllExercisesFromHistory();
  const setsPromises = allExercises.map((ex) => getRecentSetLogsDecrypted(ex, 200));
  const setsArrays = await Promise.all(setsPromises);
  return setsArrays.flat().filter((s) => s.timestamp > fourWeeksAgo);
}

/** Calculate acute and chronic loads from sets */
function calculateLoads(sets: SetLog[]) {
  const now = Date.now();
  const acuteStart = now - ONE_WEEK_MS;
  const chronicStart = now - FOUR_WEEKS_MS;

  let acuteLoad = 0;
  let chronicLoad = 0;

  for (const set of sets) {
    const load = set.weightKg * set.repsCompleted;
    if (set.timestamp >= acuteStart) acuteLoad += load;
    if (set.timestamp >= chronicStart) chronicLoad += load;
  }

  return { acuteLoad, chronicLoad, chronicAvg: chronicLoad / 4 };
}

/** Determine base risk from ACWR value */
function classifyBaseRisk(acwr: number): InjuryRisk {
  if (acwr > 1.5) return 'CRITICAL';
  if (acwr > 1.3) return 'HIGH';
  if (acwr > 0.8) return 'MODERATE';
  return 'LOW';
}

/** Adjust risk based on demographic profile */
function adjustRiskForDemographic(
  baseRisk: InjuryRisk,
  acwr: number,
  demographicProfile: DemographicProfile,
): InjuryRisk {
  if (demographicProfile !== 'senior_joint_focus') return baseRisk;

  if (acwr > 1.2 && baseRisk !== 'CRITICAL') return 'HIGH';
  if (acwr > 1.0 && baseRisk === 'LOW') return 'MODERATE';

  return baseRisk;
}

/** Build risk configuration with warnings and recommendations */
function buildRiskConfig(adjustedRisk: InjuryRisk, acwr: number): RiskConfig {
  switch (adjustedRisk) {
    case 'CRITICAL':
      return {
        risk: 'CRITICAL',
        warnings: [
          `🚨 RISCO CRÍTICO! ACWR = ${acwr.toFixed(2)} – carga das últimas 2 semanas muito acima do normal.`,
          'Suspende treinos de alta intensidade por 3-5 dias. Foco em mobilidade e cardio leve.',
        ],
        restricted: ['barbell deadlift', 'barbell back squat', 'box jump', 'burpee', 'sprint'],
        alternatives: ['walking', 'stretching', 'yoga', 'foam rolling'],
      };
    case 'HIGH':
      return {
        risk: 'HIGH',
        warnings: [`⚠️ Risco elevado (ACWR = ${acwr.toFixed(2)}). Reduz volume em 30% esta semana.`],
        restricted: ['jump squat', 'clean and jerk'],
        alternatives: ['dumbell bench press', 'machine leg press'],
      };
    case 'MODERATE':
      return {
        risk: 'MODERATE',
        warnings: [
          `⚖️ Atenção: ACWR = ${acwr.toFixed(2)}. Mantém carga, mas evita picos de intensidade.`,
        ],
        restricted: [],
        alternatives: [],
      };
    default:
      return {
        risk: 'LOW',
        warnings: [`✅ Zona doce. ACWR = ${acwr.toFixed(2)}. Progressão segura.`],
        restricted: [],
        alternatives: [],
      };
  }
}

// ---- Main exported function ----

export async function analyzeInjuryRisk(
  userId: string,
  demographicProfile: DemographicProfile,
  exercisesToCheck?: string[],
): Promise<InjuryAssessment> {
  const allSets = await fetchRecentSets(exercisesToCheck);

  if (allSets.length === 0) {
    return {
      overallRisk: 'LOW',
      acwr: 0,
      acuteLoad: 0,
      chronicLoad: 0,
      warnings: ['Sem dados suficientes para análise de risco. Completa mais treinos.'],
    };
  }

  const { acuteLoad, chronicAvg } = calculateLoads(allSets);
  const acwr = chronicAvg > 0 ? acuteLoad / chronicAvg : 0;

  const baseRisk = classifyBaseRisk(acwr);
  const adjustedRisk = adjustRiskForDemographic(baseRisk, acwr, demographicProfile);
  const config = buildRiskConfig(adjustedRisk, acwr);

  return {
    overallRisk: config.risk,
    acwr: Math.round(acwr * 100) / 100,
    acuteLoad: Math.round(acuteLoad),
    chronicLoad: Math.round(chronicAvg),
    warnings: config.warnings,
    restrictedExercises: config.restricted,
    alternativeExercises: config.alternatives,
  };
}

// @ts-nocheck
// src/services/keyRotationService.ts
// Serviço de rotação de chave mestra (mudança de PIN).
//
// Implementa uma transação atómica no IndexedDB que:
// 1. Valida o PIN antigo decifrando um registo existente
// 2. Re-cifra TODOS os SetLogs com a nova chave
// 3. Actualiza a chave mestra em memória
//
// Se qualquer passo falhar, a transacção reverte automaticamente
// e os dados ficam intactos com o PIN antigo.

import { getDB } from '../db/schema';
import { deriveKey } from '../utils/cryptoEngine';
import { setMasterKey } from '../utils/cryptoEngine';
import { decryptJSON, encryptJSON } from '../utils/cryptoHelpers';

// ─── TIPOS ────────────────────────────────────────────────────────────────────

export interface RotationResult {
  success: boolean;
  rotatedCount: number; // Número de SetLogs re-cifrados
  skippedCount: number; // SetLogs sem encryptedFields (modo dev)
  message: string;
}

export interface RotationProgress {
  phase: 'validating' | 'deriving' | 'rotating' | 'done' | 'error';
  progress?: number; // 0–100
  message: string;
}

type ProgressCallback = (update: RotationProgress) => void;

// ─── CAMPOS SENSÍVEIS (idêntico ao encryptedDb.ts) ────────────────────────────

interface SensitiveSetFields {
  weightKg: number;
  repsCompleted: number;
  rpe: number;
  estimated1RM: number;
}

// ─── FUNÇÃO PRINCIPAL ─────────────────────────────────────────────────────────

/**
 * Rotação atómica da chave mestra.
 *
 * @param oldPin PIN actual (para validação)
 * @param newPin Novo PIN a definir
 * @param onProgress Callback opcional para feedback em tempo real
 * @returns RotationResult com estatísticas da operação
 * @throws Error se o PIN antigo for inválido ou os dados estiverem corrompidos
 */
export async function rotateMasterKey(
  oldPin: string,
  newPin: string,
  onProgress?: ProgressCallback,
): Promise<RotationResult> {
  const report = (phase: RotationProgress['phase'], message: string, progress?: number) => {
    onProgress?.({ phase, message, progress });
  };

  // ── PASSO 1: Validar PINs ──────────────────────────────────────────────────

  if (!oldPin || oldPin.length < 4) {
    throw new Error('PIN antigo deve ter pelo menos 4 caracteres');
  }
  if (!newPin || newPin.length < 4) {
    throw new Error('Novo PIN deve ter pelo menos 4 caracteres');
  }
  if (oldPin === newPin) {
    throw new Error('O novo PIN deve ser diferente do PIN actual');
  }

  // ── PASSO 2: Derivar ambas as chaves ANTES da transacção ──────────────────
  // (O deriveKey usa Web Worker + PBKDF2, não pode estar dentro de IDB tx)

  report('deriving', 'A derivar chaves criptográficas...', 10);

  let oldKey: CryptoKey;
  let newKey: CryptoKey;

  try {
    [oldKey, newKey] = await Promise.all([deriveKey(oldPin), deriveKey(newPin)]);
  } catch (err) {
    throw new Error(
      `Falha na derivação de chave: ${err instanceof Error ? err.message : 'Erro desconhecido'}`,
    );
  }

  // ── PASSO 3: Validação prévia com o PIN antigo ────────────────────────────
  // Tenta decifrar o primeiro SetLog cifrado para verificar que o PIN está correcto
  // ANTES de iniciar a transacção destrutiva.

  report('validating', 'A validar PIN antigo...', 20);

  const db = await getDB();
  const firstEncryptedSet = await findFirstEncryptedSet(db);

  if (firstEncryptedSet) {
    try {
      await decryptJSON<SensitiveSetFields>(firstEncryptedSet.encryptedFields!, oldKey);
    } catch {
      throw new Error('PIN antigo inválido ou dados corrompidos. A operação foi cancelada.');
    }
  }
  // Se não há SetLogs cifrados (modo dev / sem dados), continuamos sem validação

  // ── PASSO 4: Transacção atómica de re-cifragem ────────────────────────────

  report('rotating', 'A re-cifrar os dados com o novo PIN...', 35);

  let rotatedCount = 0;
  let skippedCount = 0;

  try {
    const tx = db.transaction('setLogs', 'readwrite');
    const store = tx.store;

    const allSets = await store.getAll();
    const totalSets = allSets.length;

    const updatedSets = [];

    for (let i = 0; i < allSets.length; i++) {
      const set = allSets[i];

      // Actualizar progresso (35% a 90%)
      const progressPct = 35 + Math.floor((i / totalSets) * 55);
      if (i % 10 === 0) {
        report('rotating', `A re-cifrar série ${i + 1}/${totalSets}...`, progressPct);
      }

      if (!set.encryptedFields) {
        // Modo dev ou série não cifrada — manter como está
        skippedCount++;
        continue;
      }

      // Decifrar com chave antiga
      const sensitive = await decryptJSON<SensitiveSetFields>(set.encryptedFields, oldKey);

      // Re-cifrar com nova chave
      const newEncryptedFields = await encryptJSON(sensitive, newKey);

      updatedSets.push({
        ...set,
        encryptedFields: newEncryptedFields,
      });
      rotatedCount++;
    }

    // Escrever todos de uma vez (operação atómica dentro da transacção)
    for (const updated of updatedSets) {
      await store.put(updated);
    }

    await tx.done;
  } catch (err) {
    // A transacção reverte automaticamente quando lançamos um erro
    const errMsg = err instanceof Error ? err.message : 'Erro desconhecido';

    // Se é erro de PIN inválido durante a re-cifragem (não deverá acontecer,
    // pois já validámos acima, mas por segurança):
    if (errMsg.includes('Invalid PIN') || errMsg.includes('corrupted')) {
      throw new Error('PIN antigo inválido. Os dados não foram alterados.');
    }

    throw new Error(`Falha na rotação de chave: ${errMsg}. Os dados originais foram preservados.`);
  }

  // ── PASSO 5: Actualizar chave mestra em memória ────────────────────────────

  report('done', 'A actualizar sessão...', 95);
  setMasterKey(newKey);

  report('done', `Rotação concluída! ${rotatedCount} séries re-cifradas.`, 100);

  return {
    success: true,
    rotatedCount,
    skippedCount,
    message: `PIN alterado com sucesso. ${rotatedCount} série(s) re-cifrada(s), ${skippedCount} ignorada(s) (sem cifragem).`,
  };
}

// ─── HELPER: Encontrar primeiro SetLog cifrado ────────────────────────────────

async function findFirstEncryptedSet(db: Awaited<ReturnType<typeof getDB>>) {
  const tx = db.transaction('setLogs', 'readonly');
  let cursor = await tx.store.openCursor();

  while (cursor) {
    if (cursor.value.encryptedFields) {
      return cursor.value;
    }
    cursor = await cursor.continue();
  }

  return null; // Sem dados cifrados (modo dev)
}

