import type { WorkoutSession } from '../db/schema';

export interface RivalState {
  found: boolean;
  rivalVolume: number;
  rivalDuration: number; // in seconds
  scorePerSecond: number; // metric to race against
  rivalWorkout?: WorkoutSession;
}

export const RivalAI = {
  // Procura o treino correspondente de há 7-14 dias atrás
  findRival(history: WorkoutSession[], todayPlanLabel: string): RivalState {
    const now = new Date().getTime();
    const minPast = 5 * 24 * 3600 * 1000; // Mínimo 5 dias atrás para ser um super "Rival"

    const pastWorkouts = [...history]
      .filter((w) => w.dayLabel === todayPlanLabel && now - new Date(w.date).getTime() > minPast)
      .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    if (pastWorkouts.length === 0) {
      return { found: false, rivalVolume: 0, rivalDuration: 0, scorePerSecond: 0 };
    }

    const rival = pastWorkouts[0];
    // Score = Total Volume / Duration. Defines "Intensity Speed"
    const scorePerSec = rival.duration > 0 ? rival.totalVolume / rival.duration : 0;

    return {
      found: true,
      rivalVolume: rival.totalVolume,
      rivalDuration: rival.duration,
      scorePerSecond: scorePerSec,
      rivalWorkout: rival,
    };
  },

  // Retorna a posição do fantasma num determinado segundo da corrida
  getGhostProgress(rivalState: RivalState, elapsedSeconds: number): number {
    if (!rivalState.found || rivalState.rivalDuration <= 0) return 0;
    const progress = elapsedSeconds / rivalState.rivalDuration;
    return Math.min(1, progress); // Max 100%
  },

  // Retorna o progresso do user consoante o volume e o objetivo a bater
  getUserProgress(currentVolume: number, rivalState: RivalState): number {
    if (!rivalState.found || rivalState.rivalVolume <= 0) return 0;
    return Math.min(1, currentVolume / rivalState.rivalVolume);
  },
};

/// <reference types="node" />
// ════════════════════════════════════════════════════════════════
// FitTrack V7 — Arsenal MCP: GitHub Audit (Engenheiro de Segurança)
// ════════════════════════════════════════════════════════════════
//
// Lê dados do repositório GitHub via REST API v3.
// Usado para: auditoria de commits, leitura de código, issues.
// ════════════════════════════════════════════════════════════════

const GITHUB_API = 'https://api.github.com';

interface GitHubAuditParams {
  action: 'recent_commits' | 'file_content' | 'open_issues';
  file_path?: string;
  branch?: string;
}

/**
 * Executa uma operação de leitura no repositório GitHub do FitTrack.
 */
export async function executeGitHubAudit(params: GitHubAuditParams): Promise<string> {
  const token = process.env.GITHUB_TOKEN;
  const repo = process.env.GITHUB_REPO || 'JucimarPatmarlove/Fittrack';

  if (!token) {
    console.warn('[GitHub Audit] Token ausente. Ferramenta desativada.');
    return 'Auditoria GitHub não disponível (token não configurado). Responde sem dados do repositório.';
  }

  const headers: Record<string, string> = {
    Accept: 'application/vnd.github.v3+json',
    Authorization: `Bearer ${token}`,
    'User-Agent': 'FitTrack-AI-Coach',
  };

  const { action, file_path, branch = 'main' } = params;

  try {
    switch (action) {
      case 'recent_commits': {
        const res = await fetch(`${GITHUB_API}/repos/${repo}/commits?sha=${branch}&per_page=5`, {
          headers,
        });
        if (!res.ok) return `Erro GitHub (${res.status}). Verifica o token.`;
        const commits = (await res.json()) as Array<{
          sha: string;
          commit: { message: string; author: { name: string; date: string } };
        }>;
        const formatted = commits
          .map(
            (c, i) =>
              `[${i + 1}] ${c.sha.slice(0, 7)} — ${c.commit.message.split('\n')[0]}\n` +
              `    Autor: ${c.commit.author.name} | ${new Date(c.commit.author.date).toLocaleDateString('pt-PT')}`,
          )
          .join('\n\n');
        return `Últimos 5 commits na branch "${branch}":\n\n${formatted}`;
      }

      case 'file_content': {
        if (!file_path) return 'Parâmetro file_path é obrigatório para ler um ficheiro.';
        const res = await fetch(`${GITHUB_API}/repos/${repo}/contents/${file_path}?ref=${branch}`, {
          headers,
        });
        if (!res.ok) {
          if (res.status === 404)
            return `Ficheiro "${file_path}" não encontrado na branch "${branch}".`;
          return `Erro GitHub (${res.status}) ao ler "${file_path}".`;
        }
        const file = (await res.json()) as { content?: string; size: number; name: string };
        if (!file.content) return `Ficheiro "${file_path}" está vazio ou é demasiado grande.`;
        // GitHub devolve conteúdo em base64
        const decoded = Buffer.from(file.content, 'base64').toString('utf-8');
        // Limitar a 3000 chars para não exceder o contexto
        const truncated =
          decoded.length > 3000
            ? decoded.slice(0, 3000) + '\n\n[... ficheiro truncado a 3000 caracteres ...]'
            : decoded;
        return `Conteúdo de "${file.name}" (${file.size} bytes, branch: ${branch}):\n\`\`\`\n${truncated}\n\`\`\``;
      }

      case 'open_issues': {
        const res = await fetch(`${GITHUB_API}/repos/${repo}/issues?state=open&per_page=10`, {
          headers,
        });
        if (!res.ok) return `Erro GitHub (${res.status}) ao listar issues.`;
        const issues = (await res.json()) as Array<{
          number: number;
          title: string;
          labels: Array<{ name: string }>;
          created_at: string;
          user: { login: string };
        }>;
        if (issues.length === 0) return 'Nenhuma issue aberta no repositório. Tudo limpo!';
        const formatted = issues
          .map(
            (issue) =>
              `[#${issue.number}] ${issue.title}\n` +
              `    Labels: ${issue.labels.map((l) => l.name).join(', ') || 'nenhuma'} | ` +
              `Aberta por: ${issue.user.login} | ${new Date(issue.created_at).toLocaleDateString('pt-PT')}`,
          )
          .join('\n\n');
        return `Issues abertas (${issues.length}):\n\n${formatted}`;
      }

      default:
        return `Ação "${action}" não reconhecida. Válidas: recent_commits, file_content, open_issues.`;
    }
  } catch (error) {
    console.error('[GitHub Audit] Falha:', error);
    return 'Falha na ligação ao GitHub. Responde sem dados do repositório.';
  }
}

/// <reference types="node" />
// ════════════════════════════════════════════════════════════════
// FitTrack V7 — Arsenal MCP: Supabase SQL (Analista de Dados)
// ════════════════════════════════════════════════════════════════
//
// Executa funções RPC pré-definidas no Supabase para cálculos
// de métricas de treino. O Gemini NUNCA envia SQL raw.
// ════════════════════════════════════════════════════════════════

import { type SupabaseClient, createClient } from '@supabase/supabase-js';

let supabaseClient: SupabaseClient | null = null;

function getSupabase(): SupabaseClient | null {
  if (supabaseClient) return supabaseClient;
  const url = process.env.SUPABASE_URL;
  const key = process.env.SUPABASE_SERVICE_ROLE_KEY;
  if (!url || !key) return null;
  supabaseClient = createClient(url, key, { auth: { persistSession: false } });
  return supabaseClient;
}

const RPC_MAP: Record<string, string> = {
  volume_total: 'calc_volume_total',
  frequencia_treinos: 'calc_frequencia_treinos',
  pr_exercicio: 'calc_pr_exercicio',
  historico_peso: 'calc_historico_peso',
  treinos_por_grupo_muscular: 'calc_treinos_por_grupo',
};

interface MetricParams {
  metric_type: string;
  exercise_name?: string;
  period_days?: number;
}

/**
 * Executa uma consulta de métricas via Supabase RPC.
 * Se o Supabase não estiver configurado, devolve dados scaffolding.
 */
export async function executeSupabaseMetrics(
  userId: string,
  params: MetricParams,
): Promise<string> {
  const { metric_type, exercise_name, period_days = 30 } = params;
  const supabase = getSupabase();

  // Modo scaffolding quando Supabase não está configurado
  if (!supabase) {
    console.warn('[Supabase Metrics] Não configurado. Modo scaffolding ativo.');
    const exName = exercise_name ? ` para ${exercise_name}` : '';
    return (
      `[MODO DEMO] Métrica "${metric_type}"${exName} (últimos ${period_days} dias): ` +
      `A base de dados SQL ainda não está ligada. Quando ativa, vou calcular valores exatos. ` +
      `Por agora, responde com base no contexto disponível.`
    );
  }

  // Modo produção
  const rpcName = RPC_MAP[metric_type];
  if (!rpcName) {
    return `Tipo de métrica "${metric_type}" não reconhecido. Válidos: ${Object.keys(RPC_MAP).join(', ')}.`;
  }

  try {
    const rpcParams: Record<string, unknown> = { p_user_id: userId, p_days: period_days };
    if (exercise_name) rpcParams.p_exercise = exercise_name;

    const { data, error } = await supabase.rpc(rpcName, rpcParams);

    if (error) {
      console.error(`[Supabase] Erro RPC ${rpcName}:`, error);
      if (error.message.includes('does not exist')) {
        return `A função SQL "${rpcName}" ainda não foi criada no Supabase. Métrica indisponível.`;
      }
      return `Erro SQL: ${error.message}. Responde com contexto disponível.`;
    }

    if (!data || (Array.isArray(data) && data.length === 0)) {
      return `Sem dados para ${metric_type}${exercise_name ? ` (${exercise_name})` : ''} nos últimos ${period_days} dias.`;
    }

    return `Dados da BD (${metric_type}, ${period_days}d):\n${JSON.stringify(data, null, 2)}\nUsa estes números exatos na resposta.`;
  } catch (error) {
    console.error('[Supabase] Falha:', error);
    return 'Falha na ligação à base de dados. Responde com contexto disponível.';
  }
}

// @ts-nocheck
// src/services/trendAnalyzer.ts
// Motor analítico de tendências — o "cérebro" do Personal Trainer IA
// Analisa o histórico de séries no IndexedDB para sugerir progressive overload ou deload.

import { getRecentSetLogsDecrypted } from '../db/encryptedDb';
import type { SetLog } from '../db/schema';

// ─── TIPOS DE RESULTADO ──────────────────────────────────────────────────────

export type TrendStatus = 'NO_DATA' | 'PROGRESSING' | 'FATIGUED' | 'STABLE';

export interface TrendAnalysis {
  status: TrendStatus;
  message: string;
  suggestedWeightIncrement: number; // Positivo = aumentar, Negativo = deload
  nextRpeTarget?: number;
  avgRpeLastWorkout?: number;
  avgWeightLastWorkout?: number;
  totalSetsAnalyzed: number;
}

// ─── MOTOR ANALÍTICO ─────────────────────────────────────────────────────────

/**
 * Analisa a tendência de um exercício baseada no histórico recente.
 *
 * Lógica de decisão:
 * - RPE médio ≤ 7.5 → PROGRESSING → sugere +2.5kg
 * - RPE médio ≥ 9.5 → FATIGUED → sugere -2.5kg (deload tático)
 * - RPE entre 7.5 e 9.5 → STABLE → manter carga
 *
 * @param exerciseName Nome do exercício a analisar
 * @returns Análise de tendência com sugestão de carga
 */
export async function analyzeExerciseTrend(exerciseName: string): Promise<TrendAnalysis> {
  try {
    const recentSets = await getRecentSetLogsDecrypted(exerciseName, 50);

    if (recentSets.length === 0) {
      return {
        status: 'NO_DATA',
        message: 'Ainda sem histórico. Usa a carga base recomendada.',
        suggestedWeightIncrement: 0,
        totalSetsAnalyzed: 0,
      };
    }

    // Agrupar séries por workoutId para ter visão por sessão
    const setsByWorkout = new Map<string, SetLog[]>();
    for (const set of recentSets) {
      if (!setsByWorkout.has(set.workoutId)) {
        setsByWorkout.set(set.workoutId, []);
      }
      setsByWorkout.get(set.workoutId)!.push(set);
    }

    const workoutIds = Array.from(setsByWorkout.keys());

    if (workoutIds.length === 0) {
      return {
        status: 'NO_DATA',
        message: 'Ainda sem histórico. Usa a carga base recomendada.',
        suggestedWeightIncrement: 0,
        totalSetsAnalyzed: 0,
      };
    }

    // Analisar o último treino (o primeiro no array, pois está ordenado desc)
    const lastWorkoutSets = setsByWorkout.get(workoutIds[0])!;

    // Filtrar séries sem dados válidos
    const validSets = lastWorkoutSets.filter(
      (s) => s.weightKg > 0 && s.repsCompleted > 0 && s.rpe > 0,
    );

    if (validSets.length === 0) {
      return {
        status: 'NO_DATA',
        message: 'Dados do último treino incompletos. Preenche peso, reps e RPE.',
        suggestedWeightIncrement: 0,
        totalSetsAnalyzed: recentSets.length,
      };
    }

    // Média de RPE do último treino
    const avgRpe = validSets.reduce((sum, s) => sum + s.rpe, 0) / validSets.length;
    // Carga média usada
    const avgWeight = validSets.reduce((sum, s) => sum + s.weightKg, 0) / validSets.length;

    // ── Regra do PT: Decisão baseada no RPE médio ──

    if (avgRpe <= 7.5) {
      return {
        status: 'PROGRESSING',
        message: 'Estás a dominar esta carga com boa margem de esforço. Bora aumentar!',
        suggestedWeightIncrement: 2.5,
        nextRpeTarget: 8,
        avgRpeLastWorkout: Math.round(avgRpe * 10) / 10,
        avgWeightLastWorkout: Math.round(avgWeight * 10) / 10,
        totalSetsAnalyzed: recentSets.length,
      };
    }

    if (avgRpe >= 9.5) {
      return {
        status: 'FATIGUED',
        message: 'Esforço máximo na última sessão. Reduz a carga para proteger o SNC.',
        suggestedWeightIncrement: -2.5,
        nextRpeTarget: 7.5,
        avgRpeLastWorkout: Math.round(avgRpe * 10) / 10,
        avgWeightLastWorkout: Math.round(avgWeight * 10) / 10,
        totalSetsAnalyzed: recentSets.length,
      };
    }

    // RPE entre 7.5 e 9.5 — zona ideal
    return {
      status: 'STABLE',
      message: 'Mantém o ritmo, consolida a carga antes de subir.',
      suggestedWeightIncrement: 0,
      nextRpeTarget: 8,
      avgRpeLastWorkout: Math.round(avgRpe * 10) / 10,
      avgWeightLastWorkout: Math.round(avgWeight * 10) / 10,
      totalSetsAnalyzed: recentSets.length,
    };
  } catch (error) {
    console.error('[TrendAnalyzer] Erro ao analisar tendência:', error);
    return {
      status: 'NO_DATA',
      message: 'Erro ao ler o histórico. Tenta novamente.',
      suggestedWeightIncrement: 0,
      totalSetsAnalyzed: 0,
    };
  }
}

/**
 * Analisa múltiplos exercícios em batch (útil para dashboard/relatórios).
 */
export async function analyzeMultipleExercises(
  exerciseNames: string[],
): Promise<Map<string, TrendAnalysis>> {
  const results = new Map<string, TrendAnalysis>();

  // Executa em paralelo para melhor performance
  const analyses = await Promise.all(
    exerciseNames.map(async (name) => ({
      name,
      analysis: await analyzeExerciseTrend(name),
    })),
  );

  for (const { name, analysis } of analyses) {
    results.set(name, analysis);
  }

  return results;
}

// @ts-nocheck
import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import { createEncryptedStorage } from './encryptedPersist';

export interface DailyChecklist {
  date: string;
  meals: {
    breakfast: boolean;
    morningSnack: boolean;
    lunch: boolean;
    afternoonSnack: boolean;
    dinner: boolean;
  };
  completed: boolean;
}

export interface Challenge90Data {
  startDate: string | null;
  currentDay: number;
  dailyChecklists: DailyChecklist[];
  currentStreak: number;
  longestStreak: number;
}

interface ChallengeStore extends Challenge90Data {
  startChallenge: () => void;
  toggleMeal: (meal: keyof DailyChecklist['meals']) => void;
  getTodayChecklist: () => DailyChecklist | null;
  getCompletionRate: () => number;
}

const MEAL_ORDER = ['breakfast', 'morningSnack', 'lunch', 'afternoonSnack', 'dinner'];

export const useChallengeStore = create<ChallengeStore>()(
  persist(
    (set, get) => ({
      startDate: null,
      currentDay: 0,
      dailyChecklists: [],
      currentStreak: 0,
      longestStreak: 0,

      startChallenge: () => {
        const today = new Date().toISOString().split('T')[0];
        set({
          startDate: today,
          currentDay: 1,
          dailyChecklists: [
            {
              date: today,
              meals: {
                breakfast: false,
                morningSnack: false,
                lunch: false,
                afternoonSnack: false,
                dinner: false,
              },
              completed: false,
            },
          ],
          currentStreak: 0,
          longestStreak: 0,
        });
      },

      toggleMeal: (meal) => {
        const { dailyChecklists, currentStreak, longestStreak } = get();
        const today = new Date().toISOString().split('T')[0];
        let todayChecklist = dailyChecklists.find((c) => c.date === today);

        if (!todayChecklist) {
          todayChecklist = {
            date: today,
            meals: {
              breakfast: false,
              morningSnack: false,
              lunch: false,
              afternoonSnack: false,
              dinner: false,
            },
            completed: false,
          };
          dailyChecklists.push(todayChecklist);
        }

        todayChecklist.meals[meal] = !todayChecklist.meals[meal];

        const allCompleted = MEAL_ORDER.every(
          (m) => todayChecklist!.meals[m as keyof typeof todayChecklist.meals],
        );
        todayChecklist.completed = allCompleted;

        let newStreak = currentStreak;
        if (allCompleted) {
          const yesterday = new Date(Date.now() - 86400000).toISOString().split('T')[0];
          const yesterdayChecklist = dailyChecklists.find((c) => c.date === yesterday);
          if (yesterdayChecklist?.completed) {
            newStreak++;
          } else {
            newStreak = 1;
          }
        } else {
          newStreak = 0;
        }

        set({
          dailyChecklists: [...dailyChecklists],
          currentStreak: newStreak,
          longestStreak: Math.max(longestStreak, newStreak),
        });
      },

      getTodayChecklist: () => {
        const today = new Date().toISOString().split('T')[0];
        return get().dailyChecklists.find((c) => c.date === today) || null;
      },

      getCompletionRate: () => {
        const { dailyChecklists } = get();
        const completed = dailyChecklists.filter((c) => c.completed).length;
        return dailyChecklists.length ? (completed / dailyChecklists.length) * 100 : 0;
      },
    }),
    {
      name: 'challenge-store',
      storage: createEncryptedStorage(),
    },
  ),
);

// ════════════════════════════════════════════════════════════════
// FitTrack V7 — useCompeteStore (Arena Competitiva)
// ════════════════════════════════════════════════════════════════
//
// Store Zustand para o sistema competitivo "Strava do treino de força".
// Quando configurado via VITE_SUPABASE_URL, liga-se ao Supabase
// mantendo os dados de fallback local para quando estiver offline.
// ════════════════════════════════════════════════════════════════

import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import { getSupabaseBrowser, signInAnonymously } from '../lib/supabaseBrowser';

// ─── TIPOS ──────────────────────────────────────────────────────

export type WeightClass = 'open' | 'u60' | 'u70' | 'u80' | 'u90' | 'u100' | 'o100';

export interface PublicProfile {
  userId: string;
  username: string;
  avatarInitials: string;
  weightClass: WeightClass;
  totalPublishedPRs: number;
  joinedAt: number;
}

export interface PublishedPR {
  id: string;
  exerciseName: string;
  best1RM: number;
  publishedAt: number;
  isPublished: boolean;
}

export interface LeaderboardEntry {
  rank: number;
  userId: string;
  username: string;
  avatarInitials: string;
  weightClass: WeightClass;
  best1RM: number;
  isCurrentUser: boolean;
}

export type ChallengeStatus = 'pending' | 'active' | 'completed' | 'declined' | 'expired';

export interface Challenge {
  id: string;
  exerciseName: string;
  challengerUserId: string;
  challengerUsername: string;
  challengerResult?: number;
  targetUserId: string;
  targetUsername: string;
  targetResult?: number;
  status: ChallengeStatus;
  createdAt: number;
  deadline: number;
  winnerId?: string;
}

// ─── MOCK DATA (Fallback) ───────────────────────────────────────

const MOCK_USERS: PublicProfile[] = [
  {
    userId: 'u_iron',
    username: 'IronMike_PT',
    avatarInitials: 'IM',
    weightClass: 'u90',
    totalPublishedPRs: 12,
    joinedAt: Date.now() - 86400000 * 60,
  },
  {
    userId: 'u_steel',
    username: 'SteelQueen',
    avatarInitials: 'SQ',
    weightClass: 'u70',
    totalPublishedPRs: 8,
    joinedAt: Date.now() - 86400000 * 45,
  },
  {
    userId: 'u_titan',
    username: 'TitanForge',
    avatarInitials: 'TF',
    weightClass: 'u100',
    totalPublishedPRs: 15,
    joinedAt: Date.now() - 86400000 * 90,
  },
];

function generateMockLeaderboard(exerciseName: string, userPR?: number): LeaderboardEntry[] {
  const baselines: Record<string, number> = {
    'Barbell Bench Press': 100,
    'Barbell Back Squat': 140,
    'Barbell Deadlift': 170,
  };
  const base = baselines[exerciseName] || 80;

  const entries: LeaderboardEntry[] = MOCK_USERS.map((u, i) => ({
    rank: 0,
    userId: u.userId,
    username: u.username,
    avatarInitials: u.avatarInitials,
    weightClass: u.weightClass,
    best1RM: Math.round(base * (1.3 - i * 0.08) + Math.random() * 10),
    isCurrentUser: false,
  }));

  if (userPR && userPR > 0) {
    entries.push({
      rank: 0,
      userId: 'user_local',
      username: 'Tu',
      avatarInitials: '⭐',
      weightClass: 'open',
      best1RM: userPR,
      isCurrentUser: true,
    });
  }

  entries.sort((a, b) => b.best1RM - a.best1RM);
  entries.forEach((e, i) => {
    e.rank = i + 1;
  });
  return entries;
}

// ─── STORE ──────────────────────────────────────────────────────

interface CompeteState {
  // Profile
  publicProfile: PublicProfile | null;
  setupProfile: (username: string, weightClass: WeightClass) => Promise<void>;

  // Published PRs
  publishedPRs: PublishedPR[];
  publishPR: (exerciseName: string, best1RM: number) => Promise<void>;
  unpublishPR: (exerciseName: string) => Promise<void>;
  isExercisePublished: (exerciseName: string) => boolean;

  // Leaderboard
  leaderboard: LeaderboardEntry[];
  leaderboardExercise: string;
  fetchLeaderboard: (exerciseName: string) => Promise<void>;

  // Challenges
  challenges: Challenge[];
  fetchChallenges: () => Promise<void>;
  createChallenge: (
    targetUserId: string,
    targetUsername: string,
    exerciseName: string,
    daysUntilDeadline: number,
  ) => Promise<void>;
  acceptChallenge: (challengeId: string) => Promise<void>;
  declineChallenge: (challengeId: string) => Promise<void>;
  submitChallengeResult: (challengeId: string, result: number) => Promise<void>;

  // Derived
  myRank: number | null;
  pendingChallengesCount: number;
}

export const useCompeteStore = create<CompeteState>()(
  persist(
    (set, get) => ({
      // ── Profile ──
      publicProfile: null,

      setupProfile: async (username, weightClass) => {
        const initials = username.slice(0, 2).toUpperCase();
        let userId = 'user_local';

        const sb = getSupabaseBrowser();
        if (sb) {
          const authId = await signInAnonymously();
          if (authId) {
            userId = authId;
            await sb.from('compete_profiles').upsert({
              user_id: userId,
              username,
              avatar_initials: initials,
              weight_class: weightClass,
            });
          }
        }

        set({
          publicProfile: {
            userId,
            username,
            avatarInitials: initials,
            weightClass,
            totalPublishedPRs: get().publishedPRs.filter((p) => p.isPublished).length,
            joinedAt: Date.now(),
          },
        });
      },

      // ── Published PRs ──
      publishedPRs: [],

      publishPR: async (exerciseName, best1RM) => {
        const profile = get().publicProfile;
        const sb = getSupabaseBrowser();

        if (sb && profile && profile.userId !== 'user_local') {
          await sb.from('compete_prs').upsert(
            {
              user_id: profile.userId,
              exercise_name: exerciseName,
              best_1rm: best1RM,
            },
            { onConflict: 'user_id, exercise_name' },
          );
        }

        set((state) => {
          const existing = state.publishedPRs.find((p) => p.exerciseName === exerciseName);
          if (existing) {
            return {
              publishedPRs: state.publishedPRs.map((p) =>
                p.exerciseName === exerciseName
                  ? { ...p, best1RM, isPublished: true, publishedAt: Date.now() }
                  : p,
              ),
            };
          }
          return {
            publishedPRs: [
              ...state.publishedPRs,
              {
                id: `pr_${Date.now()}`,
                exerciseName,
                best1RM,
                publishedAt: Date.now(),
                isPublished: true,
              },
            ],
          };
        });
      },

      unpublishPR: async (exerciseName) => {
        const profile = get().publicProfile;
        const sb = getSupabaseBrowser();

        if (sb && profile && profile.userId !== 'user_local') {
          await sb
            .from('compete_prs')
            .delete()
            .eq('user_id', profile.userId)
            .eq('exercise_name', exerciseName);
        }

        set((state) => ({
          publishedPRs: state.publishedPRs.map((p) =>
            p.exerciseName === exerciseName ? { ...p, isPublished: false } : p,
          ),
        }));
      },

      isExercisePublished: (exerciseName) => {
        return get().publishedPRs.some((p) => p.exerciseName === exerciseName && p.isPublished);
      },

      // ── Leaderboard ──
      leaderboard: [],
      leaderboardExercise: 'Barbell Bench Press',

      fetchLeaderboard: async (exerciseName) => {
        const sb = getSupabaseBrowser();

        if (sb) {
          const { data, error } = await sb
            .from('compete_prs')
            .select(`
              best_1rm,
              compete_profiles (user_id, username, avatar_initials, weight_class)
            `)
            .eq('exercise_name', exerciseName)
            .order('best_1rm', { ascending: false })
            .limit(50);

          if (!error && data) {
            const myId = get().publicProfile?.userId;
            const entries: LeaderboardEntry[] = data.map((d: any, i) => ({
              rank: i + 1,
              userId: d.compete_profiles.user_id,
              username: d.compete_profiles.username,
              avatarInitials: d.compete_profiles.avatar_initials,
              weightClass: d.compete_profiles.weight_class,
              best1RM: d.best_1rm,
              isCurrentUser: d.compete_profiles.user_id === myId,
            }));

            const myEntry = entries.find((e) => e.isCurrentUser);
            set({
              leaderboard: entries,
              leaderboardExercise: exerciseName,
              myRank: myEntry?.rank ?? null,
            });
            return;
          }
        }

        // Fallback to mock
        const userPR = get().publishedPRs.find(
          (p) => p.exerciseName === exerciseName && p.isPublished,
        );
        const entries = generateMockLeaderboard(exerciseName, userPR?.best1RM);
        const myEntry = entries.find((e) => e.isCurrentUser);
        set({
          leaderboard: entries,
          leaderboardExercise: exerciseName,
          myRank: myEntry?.rank ?? null,
        });
      },

      // ── Challenges ──
      challenges: [],

      fetchChallenges: async () => {
        const sb = getSupabaseBrowser();
        const profile = get().publicProfile;

        if (sb && profile && profile.userId !== 'user_local') {
          const { data, error } = await sb
            .from('compete_challenges')
            .select(`
              *,
              challenger:compete_profiles!challenger_id(username),
              target:compete_profiles!target_id(username)
            `)
            .or(`challenger_id.eq.${profile.userId},target_id.eq.${profile.userId}`)
            .order('created_at', { ascending: false });

          if (!error && data) {
            const parsed: Challenge[] = data.map((d: any) => ({
              id: d.id,
              exerciseName: d.exercise_name,
              challengerUserId: d.challenger_id,
              challengerUsername: d.challenger?.username || '?',
              challengerResult: d.challenger_result,
              targetUserId: d.target_id,
              targetUsername: d.target?.username || '?',
              targetResult: d.target_result,
              status: d.status as ChallengeStatus,
              createdAt: new Date(d.created_at).getTime(),
              deadline: new Date(d.deadline).getTime(),
              winnerId: d.winner_id,
            }));
            set({ challenges: parsed });
          }
        }
      },

      createChallenge: async (targetUserId, targetUsername, exerciseName, daysUntilDeadline) => {
        const profile = get().publicProfile;
        const sb = getSupabaseBrowser();
        const deadline = new Date(Date.now() + daysUntilDeadline * 86400000).toISOString();

        let newId = `ch_${Date.now()}`;

        if (sb && profile && profile.userId !== 'user_local') {
          const { data } = await sb
            .from('compete_challenges')
            .insert({
              exercise_name: exerciseName,
              challenger_id: profile.userId,
              target_id: targetUserId,
              deadline,
            })
            .select('id')
            .single();
          if (data) newId = data.id;
        }

        const newChallenge: Challenge = {
          id: newId,
          exerciseName,
          challengerUserId: profile?.userId || 'user_local',
          challengerUsername: profile?.username || 'Tu',
          targetUserId,
          targetUsername,
          status: 'pending',
          createdAt: Date.now(),
          deadline: new Date(deadline).getTime(),
        };

        set((state) => ({ challenges: [newChallenge, ...state.challenges] }));
      },

      acceptChallenge: async (challengeId) => {
        const sb = getSupabaseBrowser();
        if (sb && !challengeId.startsWith('ch_')) {
          await sb.from('compete_challenges').update({ status: 'active' }).eq('id', challengeId);
        }

        set((state) => ({
          challenges: state.challenges.map((c) =>
            c.id === challengeId ? { ...c, status: 'active' as ChallengeStatus } : c,
          ),
        }));
      },

      declineChallenge: async (challengeId) => {
        const sb = getSupabaseBrowser();
        if (sb && !challengeId.startsWith('ch_')) {
          await sb.from('compete_challenges').update({ status: 'declined' }).eq('id', challengeId);
        }

        set((state) => ({
          challenges: state.challenges.map((c) =>
            c.id === challengeId ? { ...c, status: 'declined' as ChallengeStatus } : c,
          ),
        }));
      },

      submitChallengeResult: async (challengeId, result) => {
        const profile = get().publicProfile;
        const stateChallenge = get().challenges.find((c) => c.id === challengeId);
        if (!profile || !stateChallenge) return;

        const isChallenger = stateChallenge.challengerUserId === profile.userId;
        const updates: any = {};

        if (isChallenger) updates.challenger_result = result;
        else updates.target_result = result;

        // Verify if both have completed to set winner
        const opponentResult = isChallenger
          ? stateChallenge.targetResult
          : stateChallenge.challengerResult;

        if (opponentResult) {
          updates.status = 'completed';
          updates.winner_id =
            result >= opponentResult
              ? profile.userId
              : isChallenger
                ? stateChallenge.targetUserId
                : stateChallenge.challengerUserId;
        }

        const sb = getSupabaseBrowser();
        if (sb && !challengeId.startsWith('ch_')) {
          await sb.from('compete_challenges').update(updates).eq('id', challengeId);
        }

        set((state) => ({
          challenges: state.challenges.map((c) => {
            if (c.id !== challengeId) return c;
            return { ...c, ...updates, winnerId: updates.winner_id };
          }),
        }));
      },

      // ── Derived ──
      myRank: null,

      get pendingChallengesCount() {
        const profile = get().publicProfile;
        if (!profile) return 0;
        return get().challenges.filter(
          (c) => c.status === 'pending' && c.targetUserId === profile.userId,
        ).length;
      },
    }),
    { name: 'ft_compete_store' },
  ),
);

