import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import type { ProactiveMessage, TriggerContext } from '../services/aiCoach/proactiveEngine';
import { evaluateTriggers, shouldShowMessage } from '../services/aiCoach/proactiveEngine';
import { trackEvent } from '../utils/telemetry';

interface ProactiveCoachState {
  messages: ProactiveMessage[];
  unreadCount: number;
  isEvaluating: boolean;
  lastEvaluation: string | null;

  // Actions
  evaluate: (context: TriggerContext) => void;
  dismissMessage: (messageId: string) => void;
  dismissAll: () => void;
  markAsRead: (messageId: string) => void;
  getActiveMessages: () => ProactiveMessage[];
  getUrgentMessages: () => ProactiveMessage[];
}

export const useProactiveCoachStore = create<ProactiveCoachState>()(
  persist(
    (set, get) => ({
      messages: [],
      unreadCount: 0,
      isEvaluating: false,
      lastEvaluation: null,

      evaluate: (context) => {
        set({ isEvaluating: true });

        try {
          const newMessages = evaluateTriggers(context);
          const existingIds = new Set(get().messages.map((m) => m.id));
          const trulyNew = newMessages.filter((m) => !existingIds.has(m.id));

          if (trulyNew.length > 0) {
            set((state) => ({
              messages: [...trulyNew, ...state.messages].slice(0, 50), // Max 50 messages
              unreadCount: state.unreadCount + trulyNew.length,
              lastEvaluation: new Date().toISOString(),
            }));

            trackEvent('proactive_evaluation', {
              newMessages: trulyNew.length,
              triggers: trulyNew.map((m) => m.trigger),
            });
          }
        } catch (error) {
          console.error('Error evaluating proactive triggers:', error);
        } finally {
          set({ isEvaluating: false });
        }
      },

      dismissMessage: (messageId) => {
        set((state) => ({
          messages: state.messages.map((m) => (m.id === messageId ? { ...m, dismissed: true } : m)),
          unreadCount: Math.max(0, state.unreadCount - 1),
        }));

        trackEvent('proactive_message_dismissed', { messageId });
      },

      dismissAll: () => {
        set((state) => ({
          messages: state.messages.map((m) => ({ ...m, dismissed: true })),
          unreadCount: 0,
        }));
      },

      markAsRead: (_messageId) => {
        set((state) => ({
          unreadCount: Math.max(0, state.unreadCount - 1),
        }));
      },

      getActiveMessages: () => {
        return get().messages.filter(shouldShowMessage);
      },

      getUrgentMessages: () => {
        return get()
          .messages.filter(shouldShowMessage)
          .filter((m) => m.priority === 'urgent' || m.priority === 'high');
      },
    }),
    {
      name: 'fittrack-proactive-coach',
      partialize: (state) => ({
        messages: state.messages.filter((m) => !m.dismissed),
        lastEvaluation: state.lastEvaluation,
      }),
    },
  ),
);

import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import { createEncryptedStorage } from './encryptedPersist';

interface ExerciseProgress {
  consecutiveSuccesses: number; // séries bem sucedidas seguidas
  lastWeight: number;
  lastReps: number;
  suggestedIncrease: boolean;
  deloadSuggested: boolean;
}

interface ExerciseHistory {
  exerciseId: string;
  date: string;
  sets: { weight: number; reps: number; completed: boolean }[];
  targetReps: number;
  allSetsCompleted: boolean;
}

interface ProgressionStore {
  history: ExerciseHistory[];
  exercises: Record<string, ExerciseProgress>;
  getRecommendedReps: (exerciseId: string, currentTargetReps: number) => number;
  recordSession: (
    exerciseId: string,
    sets: { reps: number; weight: number; completed: boolean; rpe?: number }[],
    targetReps: number,
  ) => void;
  recordSuccess: (exerciseName: string, repsDone: number, repsTarget: number, rpe: number) => void;
  recordFailure: (exerciseName: string) => void;
  shouldIncrease: (exerciseName: string) => boolean;
  shouldDeload: (exerciseName: string) => boolean;
  clearSuggestions: (exerciseName: string) => void;
}

export const useProgressionStore = create<ProgressionStore>()(
  persist(
    (set, get) => ({
      history: [],
      exercises: {},

      getRecommendedReps: (exerciseId, currentTargetReps) => {
        const { history } = get();
        const exerciseHistory = history.filter((h) => h.exerciseId === exerciseId).slice(-3);

        if (exerciseHistory.length === 0) return currentTargetReps;

        const lastTwoSessions = exerciseHistory.slice(-2);
        const allSuccessful = lastTwoSessions.every((session) => session.allSetsCompleted);

        if (allSuccessful && lastTwoSessions.length === 2 && currentTargetReps < 20) {
          return Math.min(currentTargetReps + 2, 20);
        }

        const lastSession = exerciseHistory[exerciseHistory.length - 1];
        if (lastSession && !lastSession.allSetsCompleted && currentTargetReps > 4) {
          return currentTargetReps - 1;
        }

        return currentTargetReps;
      },

      recordSession: (exerciseId, sets, targetReps) => {
        const allSetsCompleted = sets.every((set) => set.completed && set.reps >= targetReps);

        const newHistory: ExerciseHistory = {
          exerciseId,
          date: new Date().toISOString(),
          sets: sets.map((s) => ({ weight: s.weight, reps: s.reps, completed: s.completed })),
          targetReps,
          allSetsCompleted,
        };

        set((state) => ({
          history: [...state.history, newHistory].slice(-50),
        }));
      },

      recordSuccess: (name, repsDone, repsTarget, rpe) => {
        const prev = get().exercises[name] || {
          consecutiveSuccesses: 0,
          lastWeight: 0,
          lastReps: 0,
          suggestedIncrease: false,
          deloadSuggested: false,
        };
        const successRate = repsDone / repsTarget;
        const isHighQuality = successRate >= 0.9 && rpe <= 7;
        const newSuccesses = isHighQuality ? prev.consecutiveSuccesses + 1 : 0;
        const increase = newSuccesses >= 3;
        set((state) => ({
          exercises: {
            ...state.exercises,
            [name]: {
              ...prev,
              consecutiveSuccesses: newSuccesses,
              suggestedIncrease: increase,
              lastWeight: prev.lastWeight,
              lastReps: repsDone,
              deloadSuggested: false,
            },
          },
        }));
      },

      recordFailure: (name) => {
        const prev = get().exercises[name] || {
          consecutiveSuccesses: 0,
          lastWeight: 0,
          lastReps: 0,
          suggestedIncrease: false,
          deloadSuggested: false,
        };
        const failures = (prev.consecutiveSuccesses < 0 ? prev.consecutiveSuccesses : 0) - 1;
        const deload = failures <= -2;
        set((state) => ({
          exercises: {
            ...state.exercises,
            [name]: {
              ...prev,
              consecutiveSuccesses: failures,
              suggestedIncrease: false,
              deloadSuggested: deload,
            },
          },
        }));
      },

      shouldIncrease: (name) => get().exercises[name]?.suggestedIncrease || false,
      shouldDeload: (name) => get().exercises[name]?.deloadSuggested || false,
      clearSuggestions: (name) => {
        const prev = get().exercises[name];
        if (prev) {
          set((state) => ({
            exercises: {
              ...state.exercises,
              [name]: {
                ...prev,
                suggestedIncrease: false,
                deloadSuggested: false,
              },
            },
          }));
        }
      },
    }),
    {
      name: 'progression-store',
      storage: createEncryptedStorage() as any,
    },
  ),
);

