// dentro dos intervalos esperados para cada perfil de atleta.

import { describe, expect, it } from 'vitest';
import { type UserProfile, getPrescription } from '../prescriptionEngine';

// ─── PERFIS DE TESTE ──────────────────────────────────────────────────────────

const profileHipertrofiaIntermedio: UserProfile = {
  sex: 'male',
  age: 30,
  goal: 'hipertrofia',
  level: 'intermedio',
  trainingPhilosophy: 'classic',
  injuries: [],
};

const profileForcaAvancado: UserProfile = {
  sex: 'male',
  age: 25,
  goal: 'forca',
  level: 'avancado',
  injuries: [],
};

const profileResistenciaIniciante: UserProfile = {
  sex: 'female',
  age: 28,
  goal: 'resistencia',
  level: 'iniciante',
  injuries: [],
};

const profileComLesao: UserProfile = {
  sex: 'male',
  age: 35,
  goal: 'hipertrofia',
  level: 'intermedio',
  injuries: ['shoulder'],
};

// ─── PR de referência ─────────────────────────────────────────────────────────

const prBenchPress = { weight: 100, reps: 8 }; // 1RM estimado ≈ 127kg
const prSquat = { weight: 140, reps: 5 }; // 1RM estimado ≈ 163kg

// ─── SUITE: Perfil Hipertrofia Intermédio ─────────────────────────────────────

describe('prescriptionEngine — Hipertrofia Intermédio', () => {
  it('deve sugerir peso dentro do intervalo razoável para Bench Press', () => {
    const rx = getPrescription(profileHipertrofiaIntermedio, 'Barbell Bench Press', prBenchPress);
    // Para hipertrofia: ~70-75% de 127kg ≈ 89-95kg, factor intermédio 0.95 → ~85-90kg
    expect(rx.suggestedWeight).toBeGreaterThan(60);
    expect(rx.suggestedWeight).toBeLessThan(100);
  });

  it('deve recomendar reps alvo entre 15 e 20 para adaptação hipertrofia', () => {
    const rx = getPrescription(profileHipertrofiaIntermedio, 'Barbell Bench Press', prBenchPress);
    expect(rx.repsSuggested).toBeGreaterThanOrEqual(15);
    expect(rx.repsSuggested).toBeLessThanOrEqual(20);
    // Validar string de intervalo
    expect(rx.repsTarget).toMatch(/\d+-\d+/);
  });

  it('deve ter RPE alvo de 7 para hipertrofia', () => {
    const rx = getPrescription(profileHipertrofiaIntermedio, 'Barbell Bench Press', prBenchPress);
    expect(rx.rpeTarget).toBe(7);
  });

  it('deve ter descanso de 45 segundos para adaptação hipertrofia', () => {
    const rx = getPrescription(profileHipertrofiaIntermedio, 'Barbell Bench Press', prBenchPress);
    expect(rx.restSeconds).toBe(45);
  });

  it('deve gerar 3 séries de aquecimento quando há carga', () => {
    const rx = getPrescription(profileHipertrofiaIntermedio, 'Barbell Bench Press', prBenchPress);
    expect(rx.warmupSets).toHaveLength(3);
    expect(rx.warmupSets[0].weightPercent).toBe(0.5);
    expect(rx.warmupSets[1].weightPercent).toBe(0.7);
    expect(rx.warmupSets[2].weightPercent).toBe(0.85);
  });

  it('deve gerar presets de força, resistência e volume', () => {
    const rx = getPrescription(profileHipertrofiaIntermedio, 'Barbell Bench Press', prBenchPress);
    expect(rx.presets.strength.weight).toBeGreaterThan(rx.presets.endurance.weight);
    expect(rx.presets.volume.reps).toBe(rx.repsSuggested);
    expect(rx.presets.volume.setsDelta).toBe(1);
  });

  it('deve incluir explicação textual com o 1RM estimado', () => {
    const rx = getPrescription(profileHipertrofiaIntermedio, 'Barbell Bench Press', prBenchPress);
    expect(rx.explanation).toContain('1RM');
    expect(rx.explanation).toContain('kg');
  });
});

// ─── SUITE: Perfil Força Avançado ─────────────────────────────────────────────

describe('prescriptionEngine — Força Avançado', () => {
  it('deve recomendar reps baixas (3-5) para força', () => {
    const rx = getPrescription(profileForcaAvancado, 'Barbell Back Squat', prSquat);
    expect(rx.repsSuggested).toBeGreaterThanOrEqual(3);
    expect(rx.repsSuggested).toBeLessThanOrEqual(7); // avancado adiciona +2
  });

  it('deve ter RPE alvo mais elevado (>=9) para força avançado', () => {
    const rx = getPrescription(profileForcaAvancado, 'Barbell Back Squat', prSquat);
    expect(rx.rpeTarget).toBeGreaterThanOrEqual(9);
  });

  it('deve ter descanso longo (>=165 segundos) para força', () => {
    const rx = getPrescription(profileForcaAvancado, 'Barbell Back Squat', prSquat);
    expect(rx.restSeconds).toBeGreaterThanOrEqual(165); // 180 - 15 (avancado)
  });

  it('deve sugerir peso mais elevado que hipertrofia para o mesmo PR', () => {
    const rxStrength = getPrescription(profileForcaAvancado, 'Barbell Back Squat', prSquat);
    const rxHypertrophy = getPrescription(
      profileHipertrofiaIntermedio,
      'Barbell Back Squat',
      prSquat,
    );
    expect(rxStrength.suggestedWeight).toBeGreaterThan(rxHypertrophy.suggestedWeight);
  });
});

// ─── SUITE: Sem histórico (PR null) ───────────────────────────────────────────

describe('prescriptionEngine — Sem histórico de PR', () => {
  it('deve usar fallback de 20kg quando não há PR', () => {
    const rx = getPrescription(profileHipertrofiaIntermedio, 'Barbell Bench Press', null);
    expect(rx.suggestedWeight).toBeGreaterThan(0);
    // Com oneRM=40 (fallback) e fatores aplicados, o resultado pode ser baixo
    // mas nunca zero (protegido pelo if de fallback)
  });

  it('deve funcionar sem nenhum parâmetro de PR', () => {
    const rx = getPrescription(profileResistenciaIniciante, 'Dumbbell Curl');
    expect(rx.suggestedWeight).toBeGreaterThanOrEqual(0);
    expect(rx.repsSuggested).toBeGreaterThan(0);
  });
});

// ─── SUITE: Modificador de lesão ──────────────────────────────────────────────

describe('prescriptionEngine — Com lesão', () => {
  it('deve sugerir peso menor para atleta com lesão', () => {
    const rxNormal = getPrescription(
      profileHipertrofiaIntermedio,
      'Barbell Bench Press',
      prBenchPress,
    );
    const rxInjured = getPrescription(profileComLesao, 'Barbell Bench Press', prBenchPress);
    expect(rxInjured.suggestedWeight).toBeLessThan(rxNormal.suggestedWeight);
  });

  it('redução deve ser aproximadamente 20%', () => {
    const rxNormal = getPrescription(
      profileHipertrofiaIntermedio,
      'Barbell Bench Press',
      prBenchPress,
    );
    const rxInjured = getPrescription(profileComLesao, 'Barbell Bench Press', prBenchPress);
    const reductionRatio = rxInjured.suggestedWeight / rxNormal.suggestedWeight;
    // Deve estar entre 0.70 e 0.90 (20% de redução ±tolerância de arredondamento)
    expect(reductionRatio).toBeGreaterThan(0.68);
    expect(reductionRatio).toBeLessThanOrEqual(0.9);
  });
});

// ─── SUITE: Exercícios bodyweight ─────────────────────────────────────────────

describe('prescriptionEngine — Exercícios bodyweight', () => {
  it('deve retornar suggestedWeight=0 para exercícios de peso corporal', () => {
    const rx = getPrescription(profileHipertrofiaIntermedio, 'Pull-up', { weight: 0, reps: 10 });
    // Pull-up é bodyweight → calculateSuggestedWeight retorna 0
    expect(rx.suggestedWeight).toBe(0);
  });

  it('não deve gerar séries de aquecimento para bodyweight', () => {
    const rx = getPrescription(profileHipertrofiaIntermedio, 'Pull-up', { weight: 0, reps: 10 });
    // warmupSets são filtradas quando suggestedWeight === 0
    expect(rx.warmupSets).toHaveLength(0);
  });
});

// Singleton para manter o contexto de áudio vivo e desbloqueado
let audioCtx: AudioContext | null = null;
let unlocked = false;

export function initAudio() {
  if (unlocked) return;

  const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
  if (!AudioContextClass) return;

  try {
    audioCtx = new AudioContextClass();

    // Criar um buffer vazio de 1 milissegundo e tocá-lo silenciosamente
    // Isto prova ao browser que o áudio foi iniciado por uma ação do utilizador
    const buffer = audioCtx.createBuffer(1, 1, 22050);
    const source = audioCtx.createBufferSource();
    source.buffer = buffer;
    source.connect(audioCtx.destination);
    source.start(0);

    unlocked = true;
  } catch (e) {
    console.warn('Erro ao inicializar AudioContext:', e);
  }
}

export function playBeep() {
  if (!unlocked || !audioCtx) {
    // Fallback para o método clássico caso a inicialização tenha falhado
    const audio = new Audio('/beep.mp3');
    audio.volume = 0.5;
    audio.play().catch((e) => console.warn('Autoplay bloqueado:', e));
    return;
  }

  try {
    // Se o contexto foi suspenso pelo sistema operativo, acorda-o
    if (audioCtx.state === 'suspended') {
      audioCtx.resume();
    }

    // Oscilador sintético rápido e perfurante (Estilo Cyberpunk/Neon)
    const oscillator = audioCtx.createOscillator();
    const gainNode = audioCtx.createGain();

    oscillator.type = 'square';
    oscillator.frequency.setValueAtTime(880, audioCtx.currentTime); // Nota A5
    oscillator.frequency.exponentialRampToValueAtTime(440, audioCtx.currentTime + 0.1);

    gainNode.gain.setValueAtTime(0.5, audioCtx.currentTime);
    gainNode.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.2);

    oscillator.connect(gainNode);
    gainNode.connect(audioCtx.destination);

    oscillator.start();
    oscillator.stop(audioCtx.currentTime + 0.2);
  } catch (e) {
    console.warn('Erro ao reproduzir beep sintético:', e);
  }
}

// src/utils/bluetoothParser.ts

import type { HeartRateData } from '../hooks/useBluetoothHRM';
import type { FitnessMachineData } from '../hooks/useFitnessMachine';

export function parseHeartRateMeasurement(value: DataView): HeartRateData {
  const flags = value.getUint8(0);
  const rateFormat = flags & 0x01; // 0 = uint8, 1 = uint16
  let bpm: number;
  if (rateFormat === 0) {
    bpm = value.getUint8(1);
  } else {
    bpm = value.getUint16(1, true);
  }
  const contact = !!(flags & 0x02);
  let energy: number | undefined;
  if (flags & 0x08) {
    const offset = rateFormat === 0 ? 2 : 3;
    energy = value.getUint16(offset, true);
  }
  return { bpm, timestamp: Date.now(), contact, energy };
}

export function parseFTMSMeasurement(value: DataView): FitnessMachineData {
  const data: FitnessMachineData = { timestamp: Date.now() };
  try {
    let offset = 0;
    const flags = value.getUint16(offset, true);
    offset += 2;
    if (flags & 0x0001) {
      data.instantSpeed = value.getUint16(offset, true) / 100;
      offset += 2;
    }
    if (flags & 0x0002) {
      data.averageSpeed = value.getUint16(offset, true) / 100;
      offset += 2;
    }
    if (flags & 0x0010) {
      data.heartRate = value.getUint8(offset);
      offset += 1;
    }
    if (flags & 0x0020) {
      data.cadence = value.getUint16(offset, true);
      offset += 2;
    }
    if (flags & 0x0040) {
      data.power = value.getInt16(offset, true);
      offset += 2;
    }
    if (flags & 0x0080) {
      data.distance = value.getUint32(offset, true);
      offset += 4;
    }
    if (flags & 0x0200) {
      data.calories = value.getUint16(offset, true);
      offset += 2;
    }
  } catch (_e) { /* Return partial data if FTMS parsing fails mid-stream */ }
  return data;
}

const ITERATIONS = 100000;

export function getOrCreateInstallSalt(): string {
  let salt = localStorage.getItem('ft_install_salt');
  if (!salt) {
    // Migration check: If old master key or encrypted data exists, use the old salt to preserve data
    // For simplicity and to avoid breaking existing users on update, we default to old salt if they have history
    const hasHistory = localStorage.getItem('fit_history');
    if (hasHistory) {
      salt = 'fit_track_v7_salt';
    } else {
      const buffer = crypto.getRandomValues(new Uint8Array(16));
      salt = btoa(String.fromCharCode(...buffer));
    }
    localStorage.setItem('ft_install_salt', salt);
  }
  return salt;
}

export async function deriveKey(pin: string): Promise<CryptoKey> {
  return new Promise((resolve, reject) => {
    const worker = new Worker(new URL('../workers/crypto.worker.ts', import.meta.url), {
      type: 'module',
    });

    worker.onmessage = async (e) => {
      if (e.data.success) {
        try {
          // Import raw key into a non-extractable CryptoKey in Main Thread (Zero Trust principle)
          const key = await crypto.subtle.importKey(
            'raw',
            e.data.rawKey,
            { name: 'AES-GCM', length: 256 },
            false, // Non-extractable in main thread!
            ['encrypt', 'decrypt'],
          );
          resolve(key);
        } catch (err) {
          reject(err);
        }
      } else {
        reject(new Error(e.data.error));
      }
      worker.terminate();
    };

    worker.onerror = (err) => {
      reject(err);
      worker.terminate();
    };

    worker.postMessage({ pin, salt: getOrCreateInstallSalt(), iterations: ITERATIONS });
  });
}

let masterKey: CryptoKey | null = null;
export function setMasterKey(key: CryptoKey) {
  masterKey = key;
}
export function getMasterKey() {
  return masterKey;
}

export async function encryptData(key: CryptoKey, data: string): Promise<string> {
  const enc = new TextEncoder();
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const encrypted = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, key, enc.encode(data));
  const buffer = new Uint8Array(iv.length + encrypted.byteLength);
  buffer.set(iv, 0);
  buffer.set(new Uint8Array(encrypted), iv.length);
  return btoa(String.fromCharCode(...buffer));
}

export async function decryptData(key: CryptoKey, base64Data: string): Promise<string> {
  try {
    const binaryStr = atob(base64Data);
    const bytes = new Uint8Array(binaryStr.length);
    for (let i = 0; i < binaryStr.length; i++) {
      bytes[i] = binaryStr.charCodeAt(i);
    }
    const iv = bytes.slice(0, 12);
    const data = bytes.slice(12);

    const decrypted = await crypto.subtle.decrypt({ name: 'AES-GCM', iv }, key, data);
    const dec = new TextDecoder();
    return dec.decode(decrypted);
  } catch (_e) {
    throw new Error('Invalid PIN or corrupted data');
  }
}

// src/utils/cryptoHelpers.ts
// Wrapper de criptografia para objectos JSON.
// Reutiliza as funções AES-GCM do cryptoEngine.ts existente,
// adicionando serialização/deserialização JSON automática.

import { decryptData as decryptString, encryptData as encryptString } from './cryptoEngine';

/**
 * Cifra um objecto JavaScript com AES-GCM.
 * Serializa para JSON, depois cifra com a chave fornecida.
 *
 * @param data Objecto a cifrar
 * @param key CryptoKey derivada do PIN do utilizador
 * @returns String Base64 com IV + ciphertext
 */
export async function encryptJSON(data: any, key: CryptoKey): Promise<string> {
  const jsonStr = JSON.stringify(data);
  return encryptString(key, jsonStr);
}

/**
 * Decifra uma string Base64 para um objecto JavaScript.
 *
 * @param encryptedBase64 String Base64 cifrada
 * @param key CryptoKey derivada do PIN do utilizador
 * @returns Objecto JavaScript original
 * @throws Error se a chave for inválida ou dados corrompidos
 */
export async function decryptJSON<T = any>(encryptedBase64: string, key: CryptoKey): Promise<T> {
  const jsonStr = await decryptString(key, encryptedBase64);
  return JSON.parse(jsonStr) as T;
}

// src/utils/dailyAdjustment.ts
// Motor de Ajuste Dinâmico — Análise Interdiária
// Cruza 3 variáveis biométricas (sono × peso × calorias) para recalcular metas diárias.

export interface BiometricContext {
  currentWeight: number; // Peso atual em kg (RENPHO via HealthKit)
  sleepHours: number; // Horas de sono da última noite (Apple Watch)
  yesterdayCaloriesBurned: number; // Calorias gastas ontem (treinos)
  yesterdayCaloriesConsumed: number; // Calorias consumidas ontem (refeições)
  baselineWeight: number; // Peso base do perfil (idealmente média 7 dias)
  targetCalories: number; // Meta calórica padrão do perfil
}

export interface DailyAdjustment {
  suggestedCalories: number; // Meta calórica recalculada
  workoutType: string; // Tipo de treino recomendado
  intensityModifier: number; // Multiplicador de intensidade (0.7 a 1.1)
  sleepInsight: string; // Nota clínica sobre sono
  weightInsight: string; // Nota clínica sobre variação de peso
  calorieInsight: string; // Nota sobre balanço calórico
}

/**
 * Calcula os ajustes diários com base no contexto biométrico.
 *
 * TABELA DE DECISÃO:
 * ┌──────────────────┬─────────────────┬──────────────────────────────────────────┐
 * │ Variável         │ Threshold       │ Ação                                     │
 * ├──────────────────┼─────────────────┼──────────────────────────────────────────┤
 * │ Sono < 6.5h      │ Fadiga SNC      │ -150 kcal, treino DELOAD / MOBILIDADE    │
 * │ Sono ≥ 8h        │ Superávit neural│ +100 kcal, treino FORÇA MÁXIMA           │
 * │ Peso Δ > 1.2 kg  │ Retenção hídrica│ Cardio regenerativo, -100 kcal           │
 * │ Excesso > 500kcal│ Superávit ontem │ -20% do excesso (máx -300)               │
 * │ Déficit > 500kcal│ Déficit ontem   │ +150 kcal compensação                    │
 * └──────────────────┴─────────────────┴──────────────────────────────────────────┘
 */
export function calculateDailyAdjustments(ctx: BiometricContext): DailyAdjustment {
  let calorieModifier = 0;
  let workoutType = 'TREINO NORMAL';
  let intensityModifier = 1.0;
  let sleepInsight = '';
  let weightInsight = '';
  let calorieInsight = '';

  // ─── 1. ANÁLISE DE SONO (Recuperação do SNC) ────────────────────────────

  if (ctx.sleepHours < 6.5) {
    // Sono restrito → Sensibilidade à insulina alterada + fadiga central acumulada
    calorieModifier -= 150;
    workoutType = 'DELOAD / MOBILIDADE';
    intensityModifier = 0.8;
    sleepInsight = `⚠️ Sono insuficiente (${ctx.sleepHours.toFixed(1)}h). Fadiga do SNC elevada. Meta calórica reduzida e intensidade baixa para proteger articulações.`;
  } else if (ctx.sleepHours >= 8) {
    // Superávit de recuperação neural
    calorieModifier += 100;
    workoutType = 'FORÇA MÁXIMA';
    intensityModifier = 1.1;
    sleepInsight = `✅ Sono excelente (${ctx.sleepHours.toFixed(1)}h). SNC totalmente restaurado. Aproveite o pico hormonal com intensidade máxima.`;
  } else {
    sleepInsight = `🟡 Sono adequado (${ctx.sleepHours.toFixed(1)}h). Recuperação dentro dos padrões.`;
  }

  // ─── 2. ANÁLISE DE PESO (Balanço de Fluidos / Glicogénio) ────────────────

  const weightChange = ctx.currentWeight - ctx.baselineWeight;

  if (Math.abs(weightChange) > 1.2) {
    // Variação > 1.2kg em 24h não é tecido adiposo: é retenção hídrica ou inflamação
    workoutType = 'CARDIO REGENERATIVO';
    intensityModifier = 0.7;
    calorieModifier -= 100;
    const direction = weightChange > 0 ? '+' : '';
    weightInsight = `🌊 Variação brusca de peso (${direction}${weightChange.toFixed(1)}kg). Provável retenção hídrica ou inflamação pós-treino. Cardio leve e boa hidratação recomendados.`;
  } else if (Math.abs(weightChange) > 0.5) {
    weightInsight = `📊 Variação moderada de peso (${weightChange > 0 ? '+' : ''}${weightChange.toFixed(1)}kg). Dentro dos padrões fisiológicos.`;
  } else {
    weightInsight = `📊 Peso estável (Δ ${weightChange > 0 ? '+' : ''}${weightChange.toFixed(1)}kg). Homeostase mantida.`;
  }

  // ─── 3. AJUSTE DINÂMICO DE CALORIAS (Balanço Interdiário) ────────────────

  const netYesterday = ctx.yesterdayCaloriesConsumed - ctx.yesterdayCaloriesBurned;
  const surplus = netYesterday - ctx.targetCalories;

  if (surplus > 500) {
    // Excesso calórico massivo ontem → Compensação suave (20% do excesso, máx 300)
    const reduction = Math.min(300, Math.round(surplus * 0.2));
    calorieModifier -= reduction;
    calorieInsight = `🍽️ Excedeu ${Math.round(surplus)} kcal ontem. Meta de hoje reduzida em ${reduction} kcal para equilibrar a semana sem quebrar a homeostase.`;
  } else if (surplus < -500) {
    // Déficit excessivo ontem → Compensação para proteger recuperação
    calorieModifier += 150;
    calorieInsight = `🔥 Déficit de ${Math.round(Math.abs(surplus))} kcal ontem. Meta aumentada ligeiramente para proteger a síntese proteica e recuperação muscular.`;
  } else {
    calorieInsight = `⚖️ Balanço calórico equilibrado ontem. Mantenha a consistência.`;
  }

  // ─── CÁLCULO FINAL ──────────────────────────────────────────────────────

  const finalCalories = Math.max(
    1200,
    Math.min(3500, Math.round(ctx.targetCalories + calorieModifier)),
  );

  return {
    suggestedCalories: finalCalories,
    workoutType,
    intensityModifier,
    sleepInsight,
    weightInsight,
    calorieInsight,
  };
}

